-- migration_110_speaking_question_bank.sql (2026-11-06)
-- The Sep 2026 – Apr 2027 speaking question bank, in two banks:
--   * Part 1: 39 topics (156 questions) as "Part 1 · Topic N" (numbers
--     2001–2039), one page each on the shelf "Speaking Topics · Part 1".
--     Questions that already have a model answer elsewhere (warm-up bank,
--     Set 8) get it here too. Speaking mocks on a Part 2 & 3 topic take
--     their Part 1 from here (an "about you" topic + two others).
-- The Part 2 & 3 model-answer book: 66 topics, each with
-- its cue card, model talk, rounding-off question and Part 3 discussion
-- (406 questions with model answers, phrases and grammar).
--   * Each topic is a speaking set "Topic N" (numbers 1001–1066, so they
--     never clash with your own Set 1, Set 2 …).
--   * In Practice Bank → Speaking they are three shelves:
--     "Speaking Topics · Parts 2 & 3", "· Part 2", "· Part 3".
--   * Search finds them by name or cue card ("tall building", "river",
--     "describe a person …"), and "By topic" filters People / Places /
--     Things & ideas / Events & experiences.
-- This file: the page maker + Part 1 bank + topics 1–33. Then run migration_111 (34–66).
-- Safe to run more than once.

set lock_timeout = '8s';

create or replace function public.speaking_set_pages()
returns trigger
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_p1 text;
  v_p2 text;
  v_p3 text;
  v_no text;
  v_title text;
begin
  if tg_op = 'DELETE' then
    delete from public.materials where storage_path like 'speaking:' || old.id || '#%';
    return old;
  end if;

  -- The daily warm-up bank (content.warmup) is not a test: no Practice Bank pages.
  if coalesce((new.content->>'warmup')::boolean, false) then
    delete from public.materials where storage_path like 'speaking:' || new.id || '#%';
    return new;
  end if;

  -- Part 1 topic bank (content.p1_no): one Part 1 page per topic.
  if new.content ? 'p1_no' then
    delete from public.materials
     where storage_path like 'speaking:' || new.id || '#%' and storage_path <> 'speaking:' || new.id || '#part1';
    insert into public.materials
      (title, file_name, storage_path, url, mime_type, size_bytes, source,
       skill, question_type, collection, position, on_shelf, created_by)
    values
      ('Part 1 · Topic ' || (new.content->>'p1_no') || ': ' || coalesce(nullif(new.topics, ''), new.content#>>'{part1,0,topic}', new.title), new.title, 'speaking:' || new.id || '#part1', 'speaking:' || new.id || '#part1', 'application/json', 0, 'upload', 'speaking', 'speaking_part1', 'Speaking Topics · Part 1', (new.content->>'p1_no')::int, false, new.created_by)
    on conflict (storage_path) do update
      set title = excluded.title, file_name = excluded.file_name, position = excluded.position, collection = excluded.collection;
    return new;
  end if;

  v_p2 := coalesce(new.content#>>'{part2,cue}', 'Cue card');

  -- Part 2 & 3 topic bank (content.topic_no): three pages, no Part 1,
  -- tagged People / Places / Things & ideas / Events & experiences.
  if new.content ? 'topic_no' then
    v_no := 'Topic ' || (new.content->>'topic_no');
    v_title := coalesce(nullif(new.topics, ''), nullif(new.content#>>'{part3,title}', ''), new.title);
    delete from public.materials where storage_path = 'speaking:' || new.id || '#part1';
    insert into public.materials
      (title, file_name, storage_path, url, mime_type, size_bytes, source,
       skill, question_type, collection, position, on_shelf, created_by, topic)
    values
      (v_no || ': ' || v_title, new.title, 'speaking:' || new.id || '#full', 'speaking:' || new.id || '#full', 'application/json', 0, 'upload', 'speaking', 'speaking_full', 'Speaking Topics · Parts 2 & 3', (new.content->>'topic_no')::int, false, new.created_by, new.content->>'category'),
      (v_no || ': ' || v_p2, new.title, 'speaking:' || new.id || '#part2', 'speaking:' || new.id || '#part2', 'application/json', 0, 'upload', 'speaking', 'speaking_part2', 'Speaking Topics · Part 2', (new.content->>'topic_no')::int, false, new.created_by, new.content->>'category'),
      (v_no || ': ' || v_title, new.title, 'speaking:' || new.id || '#part3', 'speaking:' || new.id || '#part3', 'application/json', 0, 'upload', 'speaking', 'speaking_part3', 'Speaking Topics · Part 3', (new.content->>'topic_no')::int, false, new.created_by, new.content->>'category')
    on conflict (storage_path) do update
      set title = excluded.title, file_name = excluded.file_name, position = excluded.position,
          collection = excluded.collection, topic = excluded.topic;
    return new;
  end if;

  select string_agg(t->>'topic', ' · ') into v_p1 from jsonb_array_elements(coalesce(new.content->'part1', '[]'::jsonb)) t;
  v_p3 := coalesce(nullif(new.content#>>'{part3,title}', ''), initcap(coalesce(nullif(new.content#>>'{part3,theme}', ''), 'Discussion')));

  insert into public.materials
    (title, file_name, storage_path, url, mime_type, size_bytes, source,
     skill, question_type, collection, position, on_shelf, created_by)
  values
    ('Set ' || new.number || ': ' || coalesce(nullif(new.topics, ''), new.title), new.title, 'speaking:' || new.id || '#full', 'speaking:' || new.id || '#full', 'application/json', 0, 'upload', 'speaking', 'speaking_full', 'Speaking Tests · Full tests', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || coalesce(v_p1, 'Part 1'), new.title, 'speaking:' || new.id || '#part1', 'speaking:' || new.id || '#part1', 'application/json', 0, 'upload', 'speaking', 'speaking_part1', 'Speaking Tests · Part 1', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || v_p2, new.title, 'speaking:' || new.id || '#part2', 'speaking:' || new.id || '#part2', 'application/json', 0, 'upload', 'speaking', 'speaking_part2', 'Speaking Tests · Part 2', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || v_p3, new.title, 'speaking:' || new.id || '#part3', 'speaking:' || new.id || '#part3', 'application/json', 0, 'upload', 'speaking', 'speaking_part3', 'Speaking Tests · Part 3', new.number, false, new.created_by)
  on conflict (storage_path) do update
    set title = excluded.title, file_name = excluded.file_name, position = excluded.position;
  return new;
end;
$function$;

