-- Part 1 questions that already have a model answer in another set (the
-- warm-up bank, Set 8 …) get that model answer here too.
update public.speaking_sets s
   set content = jsonb_set(s.content, '{part1,0,questions}', (
         select jsonb_agg(case when m.model is not null then x.q || jsonb_build_object('model', m.model) else x.q end order by x.ord)
           from jsonb_array_elements(s.content #> '{part1,0,questions}') with ordinality as x(q, ord)
           left join lateral (
             select q2 -> 'model' as model
               from public.speaking_sets o,
                    jsonb_array_elements(coalesce(o.content -> 'part1', '[]'::jsonb)) t2,
                    jsonb_array_elements(coalesce(t2 -> 'questions', '[]'::jsonb)) q2
              where o.id <> s.id and not (o.content ? 'p1_no')
                and lower(regexp_replace(q2 ->> 'q', '[^a-zA-Z]', '', 'g')) = lower(regexp_replace(x.q ->> 'q', '[^a-zA-Z]', '', 'g'))
                and q2 ? 'model'
              limit 1) m on true))
 where s.content ? 'p1_no';

-- Check: 39 Part 1 topics, 156 questions, how many with a model answer.
select count(distinct s.id) as part1_topics, count(*) as questions, count(*) filter (where q ? 'model') as with_model
  from public.speaking_sets s, jsonb_array_elements(s.content #> '{part1,0,questions}') q
 where s.content ? 'p1_no';

-- Part 2 & 3 topics 1–33
insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000001', 1001, 'Topic 1', 'Place you’d like to visit in your free time', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 1, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a place you’d like to visit in your free time", "bullets": ["where it is", "what you will do there", "how long you will stay there", "why you’d like to visit it"], "explain": "", "notes": ["Where", "What", "How Long", "Why"], "rounding": {"q": "Would you prefer to go there alone or with other people?", "model": {"answer": "Probably with a friend or two. Hiking alone sounds peaceful, but it’s safer in a small group, and the views are always better when you can share them with someone.", "phrases": [], "grammar": []}}, "model": {"answer": "The first place that comes to mind is the Fann Mountains in Tajikistan, which is only a few hours’ drive from Samarkand, where I grew up. A colleague showed me her photos last summer, and the turquoise lakes simply took my breath away. Ever since, they’ve been at the top of my bucket list. If I ever get round to going, I’d spend most of my time hiking. I’d set off at dawn with a light backpack, make my way up to Kulikalon lake and have a picnic on the shore. Come evening, I’d be swapping stories with other hikers over green tea in a family guesthouse, which is exactly how my colleague made friends there. I’d want to stay for about a week. Any less and it would feel rushed, but if I stayed much longer, I’d have to take extended leave, which isn’t realistic at the moment. A week is long enough to recharge my batteries without falling behind at work. What really draws me there is the chance of a change of scenery. I spend most of my week staring at a screen, so being surrounded by peaks and fresh air is just what I need. Not only is it off the beaten track, but it’s also somewhere you can genuinely switch off, since the phone signal is apparently patchy. Funny enough, the older I get, the more I value places that ask nothing of me. I’ve started putting money aside every month, so with any luck it will become a reality by next summer.", "sections": [{"label": "Where", "text": "The first place that comes to mind is the Fann Mountains in Tajikistan, which is only a few hours’ drive from Samarkand, where I grew up. A colleague showed me her photos last summer, and the turquoise lakes simply took my breath away. Ever since, they’ve been at the top of my bucket list."}, {"label": "What", "text": "If I ever get round to going, I’d spend most of my time hiking. I’d set off at dawn with a light backpack, make my way up to Kulikalon lake and have a picnic on the shore. Come evening, I’d be swapping stories with other hikers over green tea in a family guesthouse, which is exactly how my colleague made friends there."}, {"label": "How Long", "text": "I’d want to stay for about a week. Any less and it would feel rushed, but if I stayed much longer, I’d have to take extended leave, which isn’t realistic at the moment. A week is long enough to recharge my batteries without falling behind at work."}, {"label": "Why", "text": "What really draws me there is the chance of a change of scenery. I spend most of my week staring at a screen, so being surrounded by peaks and fresh air is just what I need. Not only is it off the beaten track, but it’s also somewhere you can genuinely switch off, since the phone signal is apparently patchy."}, {"label": "Reflection", "text": "Funny enough, the older I get, the more I value places that ask nothing of me. I’ve started putting money aside every month, so with any luck it will become a reality by next summer."}], "phrases": [["take (someone’s) breath away", "impress someone so much that they are almost speechless"], ["at the top of my bucket list", "the thing I most want to do in my life"], ["get round to (doing)", "finally find the time to do something"], ["set off", "begin a journey"], ["make my way up", "travel gradually upwards towards a place"], ["swap stories", "exchange experiences with other people"], ["take extended leave", "have a long period away from work"], ["recharge my batteries", "rest so that you get your energy back"], ["a change of scenery", "a different environment for a while"], ["off the beaten track", "far from the usual tourist routes"], ["switch off", "relax and stop thinking about work or problems"], ["put money aside", "save money regularly for something"], ["become a reality", "actually happen after being only an idea"]], "grammar": [{"pattern": "Non-defining relative clause", "use": "noun + , which/where + clause: extra information about a place", "example": "the Fann Mountains in Tajikistan, which is only a few hours’ drive from Samarkand, where I grew up", "try": "______, which is only ______ from here."}, {"pattern": "Conditional with would If + present simple (unlikely), I’d + base", "use": "verb: an imagined plan", "example": "If I ever get round to going, I’d spend most of my time hiking", "try": "If I ever get the chance, I’d ______."}, {"pattern": "Come + time expression", "use": "Come + evening/winter/Monday = when that time arrives", "example": "Come evening, I’d be swapping stories with other hikers", "try": "Come ______, I’d be ______ing."}, {"pattern": "Any less / any more and...", "use": "Any + comparative + and + would: sets a limit", "example": "Any less and it would feel rushed", "try": "Any more than a week and it would ______."}, {"pattern": "Not only... but also (inversion)", "use": "Not only + is/are + subject, but + clause", "example": "Not only is it off the beaten track, but it’s also somewhere you can genuinely switch off", "try": "Not only is it ______, but it’s also ______."}, {"pattern": "The + comparative, the +", "use": "comparative the older I get, the more I value...", "example": "the older I get, the more I value places that ask nothing of me", "try": "The more I ______, the more I ______."}]}}, "part3": {"intro": "We’ve been talking about a place you’d like to visit in your free time, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Place you’d like to visit in your free time", "title": "Place you’d like to visit in your free time", "questions": [{"q": "Why do some people prefer to travel within their own country rather than go abroad?", "model": {"answer": "It usually comes down to money and convenience. Travelling at home means no visa, no jet lag and no language barrier, and a trip can cost a fraction of an overseas holiday, for people on a tight budget. Some feel they should explore their own backyard first. My uncle, who has lived in Tashkent all his life, only saw the Fergana Valley last year and wished he’d gone sooner.", "phrases": [["jet lag", "tiredness after flying across time zones"], ["language barrier", "difficulty communicating because you speak different languages"], ["cost a fraction of", "be much cheaper than"], ["on a tight budget", "having very little money to spend"], ["explore your own backyard", "discover places close to home"]], "grammar": [{"pattern": "Gerund as subject", "use": "-ing form as the subject of a sentence", "example": "Travelling at home means no visa", "try": "Travelling by train means ______."}, {"pattern": "Relative clause + wish", "use": "who + present perfect; wish + had + past participle (regret)", "example": "who has lived in Tashkent all his life", "try": "My aunt, who has ______, wished she’d ______."}]}}, {"q": "What are the benefits of visiting a foreign country?", "model": {"answer": "The biggest benefit, in my view, is that it broadens your horizons. Seeing how other people live challenges your assumptions, and you come home more open-minded. Practically speaking, you also pick up useful phrases, and being forced to get by in another language builds real confidence. Had I never travelled abroad, I’d probably still believe my way of doing things was the only sensible one.", "phrases": [["broaden your horizons", "give you new experiences and ideas"], ["challenge your assumptions", "make you question what you took for granted"], ["open-minded", "willing to accept different ideas"], ["pick up", "learn informally without formal study"], ["get by", "manage with limited resources or language"]], "grammar": [{"pattern": "Inverted third conditional", "use": "Had + subject + past participle, would + base verb", "example": "Had I never travelled abroad, I’d probably still believe my way of doing things was the only sensible one", "try": "Had I never ______, I’d probably ______."}, {"pattern": "Passive gerund", "use": "being + past participle as subject", "example": "being forced to get by in another language builds real confidence", "try": "Being ______ to ______ builds ______."}]}}, {"q": "How has the way people travel changed over the last few decades?", "model": {"answer": "Mostly it’s become cheaper and far more independent. Decades ago, people relied on travel agents and printed guidebooks, whereas now we book everything online in minutes, and budget airlines have put faraway countries within reach of ordinary families. The flip side is that travellers increasingly follow the same tried-and-tested routes recommended on social media, so famous places feel overrun by crowds taking identical photos.", "phrases": [["book everything online", "arrange tickets and hotels on the internet"], ["budget airline", "an airline offering very cheap tickets"], ["within reach", "possible or affordable to obtain"], ["tried-and-tested", "already proven to work"], ["overrun", "filled with too many people"]], "grammar": [{"pattern": "Contrast with whereas", "use": "clause + , whereas + clause: compare past and present", "example": "whereas now we book everything online in minutes", "try": "In the past people ______, whereas now ______."}, {"pattern": "Participle clause", "use": "noun + -ing phrase: reduced relative clause", "example": "crowds taking identical photos", "try": "______ people ______ing the same thing."}]}}, {"q": "Some people say that travel is the best form of education. Do you agree?", "model": {"answer": "Partly, though I wouldn’t go as far as saying it’s the best. Travel teaches things no textbook can, such as how to adapt to unfamiliar surroundings and read a situation quickly. That said, it only educates you if you go in with an open mind; someone who simply sits by a hotel pool learns very little. Ideally, books give you the background and travel provides the first-hand experience.", "phrases": [["go as far as saying", "be willing to claim something strong"], ["adapt to unfamiliar surroundings", "adjust to places you don’t know"], ["read a situation", "understand what is happening and react wisely"], ["go in with an open mind", "approach something without fixed opinions"], ["first-hand experience", "knowledge gained by doing something yourself"]], "grammar": [{"pattern": "Concession with that said", "use": "That said, + contrasting clause", "example": "That said, it only educates you if you go in with an open mind", "try": "That said, it only works if ______."}, {"pattern": "Relative clause with who", "use": "someone who + verb: describing a type of person", "example": "someone who simply sits by a hotel pool learns very little", "try": "Someone who ______ learns very little."}]}}, {"q": "Do you think tourism always benefits the places that people visit?", "model": {"answer": "Not always. It certainly boosts the local economy by creating jobs in hotels, restaurants and transport, but the money doesn’t always stay in the area, particularly when big foreign chains take the lion’s share. Tourism can also push up prices, leaving locals struggling to make ends meet. So whether it benefits a place depends on who owns the businesses and how well visitor numbers are kept in check.", "phrases": [["boost the local economy", "help businesses and jobs in an area grow"], ["take the lion’s share", "get the largest part of something"], ["push up prices", "make things more expensive"], ["make ends meet", "earn just enough to live on"], ["keep (something) in check", "control so it doesn’t grow too much"]], "grammar": [{"pattern": "Participle after leaving", "use": "leaving + object + -ing: result clause", "example": "leaving locals struggling to make ends meet", "try": "..., leaving people ______ing."}, {"pattern": "Noun clause subject", "use": "Whether + clause + depends on...", "example": "whether it benefits a place depends on who owns the businesses", "try": "Whether it works depends on ______."}]}}, {"q": "What problems can arise when a place becomes very popular with tourists?", "model": {"answer": "The most obvious one is overcrowding. When a quiet village becomes a tourist hotspot, streets get congested, queues form everywhere and the peace and quiet that attracted visitors disappears. Worse still, residents can feel priced out of their own neighbourhood, which, over time, erodes the very character that made the place worth visiting. Venice is often cited as the classic example of this problem.", "phrases": [["a tourist hotspot", "a place that attracts many visitors"], ["get congested", "become overcrowded"], ["peace and quiet", "calm without noise"], ["priced out", "unable to afford to live somewhere"], ["worth visiting", "good enough to deserve a visit"]], "grammar": [{"pattern": "Worse still", "use": "Worse still, + new problem: adds a stronger point", "example": "Worse still, residents can feel priced out of their own neighbourhood", "try": "Worse still, ______."}, {"pattern": "Non-defining relative clause", "use": "which, + time phrase, + verb: comment on the whole clause", "example": "which, over time, erodes the very character that made the place worth visiting", "try": "..., which, over time, ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000002', 1002, 'Topic 2', 'Special cake', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 2, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a special cake you received", "bullets": ["what kind of cake it was", "when you had it", "who you were with", "why it was special"], "explain": "", "notes": ["What", "When", "Who", "Why"], "rounding": {"q": "Do you still celebrate your birthday in the same way?", "model": {"answer": "Not really. These days it’s usually a quiet dinner with close friends, but my aunt still insists on baking something, and honestly, hers tastes better every year.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about a Napoleon cake my aunt Gulnora baked for my eighteenth birthday. If you haven’t tried one, it’s a tall cake made of paper-thin, flaky pastry layers sandwiched with vanilla custard, and hers was topped with fresh strawberries. She’d stayed up half the night making it, which I only found out later. It was in March, about six years ago, a few weeks before my final school exams. I’d been under a lot of pressure that month, so I’d completely lost track of the date, and a party was the last thing on my mind. When I got home from a revision class, the flat was in darkness. Then the lights flicked on, and my parents, my grandmother and Aunt Gulnora were all standing there singing, with my little brother holding the cake. I was totally caught off guard. It was special because of the effort behind it. Aunt Gulnora isn’t a confident baker, and she’d gone out of her way to practise the recipe three times that week. The cake was slightly lopsided, but it tasted out of this world, and I remember blowing out the candles with a lump in my throat. Had she not made such an effort, I’d have forgotten that birthday entirely. Looking back, what struck me was that the cake mattered less than the effort. Something homemade carries a kind of sentimental value that no bakery can match, and it was clearly a labour of love.", "sections": [{"label": "What", "text": "Let me tell you about a Napoleon cake my aunt Gulnora baked for my eighteenth birthday. If you haven’t tried one, it’s a tall cake made of paper-thin, flaky pastry layers sandwiched with vanilla custard, and hers was topped with fresh strawberries. She’d stayed up half the night making it, which I only found out later."}, {"label": "When", "text": "It was in March, about six years ago, a few weeks before my final school exams. I’d been under a lot of pressure that month, so I’d completely lost track of the date, and a party was the last thing on my mind."}, {"label": "Who", "text": "When I got home from a revision class, the flat was in darkness. Then the lights flicked on, and my parents, my grandmother and Aunt Gulnora were all standing there singing, with my little brother holding the cake. I was totally caught off guard."}, {"label": "Why", "text": "It was special because of the effort behind it. Aunt Gulnora isn’t a confident baker, and she’d gone out of her way to practise the recipe three times that week. The cake was slightly lopsided, but it tasted out of this world, and I remember blowing out the candles with a lump in my throat. Had she not made such an effort, I’d have forgotten that birthday entirely."}, {"label": "Reflection", "text": "Looking back, what struck me was that the cake mattered less than the effort. Something homemade carries a kind of sentimental value that no bakery can match, and it was clearly a labour of love."}], "phrases": [["flaky pastry", "pastry that breaks into light, thin layers"], ["stay up half the night", "not go to bed until very late"], ["under a lot of pressure", "feeling stressed because of many demands"], ["lose track of", "forget or no longer know exactly"], ["the last thing on my mind", "something I was not thinking about at all"], ["catch (someone) off guard", "surprise someone who isn’t prepared"], ["go out of one’s way", "make a special effort to help"], ["out of this world", "extremely good"], ["with a lump in my throat", "feeling emotional, nearly crying"], ["sentimental value", "importance because of personal feelings or memories"], ["a labour of love", "work done with great care because you love it"]], "grammar": [{"pattern": "Past perfect", "use": "had + past participle: an earlier past action", "example": "She’d stayed up half the night making it", "try": "By the time I arrived, she’d already ______."}, {"pattern": "Third conditional (inverted)", "use": "Had + subject + not + past participle, I’d have + past participle", "example": "Had she not made such an effort, I’d have forgotten that birthday entirely", "try": "Had I not ______, I’d have ______."}, {"pattern": "Cleft sentence What + subject + verb + was + (that)", "use": "clause: stresses an idea", "example": "what struck me was that the cake mattered less than the effort", "try": "What I remember most was ______."}, {"pattern": "Absolute participle with", "use": "with + noun + -ing: a detail of a scene", "example": "with my little brother holding the cake", "try": "..., with my sister ______ing ______."}, {"pattern": "Past perfect continuous feel", "use": "I’d been + adjective/-ing: a state before a past moment", "example": "I’d been under a lot of pressure that month", "try": "I’d been ______ for weeks."}, {"pattern": "Non-defining which", "use": "clause + , which + clause: a comment on a whole idea", "example": "which I only found out later", "try": "..., which I only ______ later."}]}}, "part3": {"intro": "We’ve been talking about a special cake you received, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Special cake", "title": "Special cake", "questions": [{"q": "What foods do people in your country traditionally eat on special occasions?", "model": {"answer": "It varies by occasion, but plov is the undisputed star. At weddings and big gatherings, huge cauldrons of it are cooked by men who have perfected the recipe over decades. During Navruz, families make sumalak, a sweet wheat pudding that takes all night to cook, so neighbours take turns stirring. And at any proper celebration the table is laden with samsa, salads and fresh fruit.", "phrases": [["the undisputed star", "the clearly most important item"], ["perfect the recipe", "improve a dish until it is excellent"], ["take all night to cook", "need many hours to prepare"], ["take turns", "do something one after another"], ["laden with", "loaded with a lot of"]], "grammar": [{"pattern": "Passive with agent", "use": "be + past participle + by + agent", "example": "huge cauldrons of it are cooked by men who have perfected the recipe", "try": "The bread is baked by ______ who ______."}, {"pattern": "Defining relative clause", "use": "a pudding that + verb", "example": "a sweet wheat pudding that takes all night to cook", "try": "a dish that ______."}]}}, {"q": "Why do some people spend so much money on food for celebrations?", "model": {"answer": "Largely because food is how people show respect. Offering guests more than they could possibly eat is seen as a sign of hospitality, and skimping on a wedding feast can damage a family’s reputation. There’s also social pressure, since people compare themselves with relatives and neighbours. The more guests a family invites, the more they feel they must keep up appearances, even when it stretches the budget.", "phrases": [["a sign of hospitality", "evidence of being a generous host"], ["skimp on", "spend too little on"], ["social pressure", "the feeling that others expect you to behave a certain way"], ["keep up appearances", "behave so that others think well of you"], ["stretch the budget", "make your money barely enough"]], "grammar": [{"pattern": "The more..., the more...", "use": "the + comparative + clause, the + comparative + clause", "example": "The more guests a family invites, the more they feel they must keep up appearances", "try": "The more ______, the more ______."}, {"pattern": "Passive + than clause", "use": "is seen as; more than + clause", "example": "Offering guests more than they could possibly eat is seen as a sign of hospitality", "try": "Doing ______ is seen as ______."}]}}, {"q": "How is celebration food in your country different from that in other countries?", "model": {"answer": "The main difference is scale and sharing. At home, celebration meals are usually on a much larger scale, with recipes handed down through generations and dishes served to dozens of guests, whereas elsewhere a gathering might be a sit-down meal for a few close friends. Also, refusing food can be considered rude here, which might surprise visitors from places where leaving something is perfectly acceptable.", "phrases": [["on a large scale", "involving many people or a lot of food"], ["hand down", "pass knowledge or objects to the next generation"], ["sit-down meal", "a formal meal at a table"], ["be considered rude", "be seen as impolite"], ["perfectly acceptable", "completely normal and fine"]], "grammar": [{"pattern": "Reduced passive relative", "use": "noun + past participle: recipes handed down", "example": "recipes handed down through generations", "try": "customs ______ down from ______."}, {"pattern": "Relative clause with where", "use": "places where + clause", "example": "places where leaving something is perfectly acceptable", "try": "...in places where ______."}]}}, {"q": "What do you think of people using their phones during a meal?", "model": {"answer": "Honestly, it can come across as rude, especially at a family table. If everyone is glued to their screens, nobody actually talks, which defeats the purpose of eating together. A quick call about something urgent is fine, and a photo of a lovely dish is harmless in moderation. It’s the constant scrolling that bothers me. A simple rule, such as leaving phones in a basket, works wonders.", "phrases": [["come across as rude", "give the impression of being impolite"], ["glued to (screens)", "unable to stop looking at"], ["defeat the purpose", "make something pointless"], ["in moderation", "in reasonable, limited amounts"], ["work wonders", "produce excellent results"]], "grammar": [{"pattern": "Cleft sentence", "use": "It’s + the + noun + that + clause: emphasis", "example": "It’s the constant scrolling that bothers me", "try": "It’s the ______ that bothers me."}, {"pattern": "First conditional", "use": "If + present simple, present simple/will", "example": "If everyone is glued to their screens, nobody actually talks", "try": "If everybody ______, nobody ______."}]}}, {"q": "Do you think it is important for families to eat together regularly?", "model": {"answer": "Absolutely, because it’s often the only time of day when everyone is in the same room. Over dinner, parents keep up with their children’s lives, and kids pick up good manners and traditions without being lectured. It also strengthens family bonds and tends to be healthier than takeaways. That said, it needn’t be every night; even a few well-balanced meals together a week make a real difference.", "phrases": [["keep up with", "stay informed about"], ["pick up", "learn without formal teaching"], ["strengthen family bonds", "make family relationships closer"], ["well-balanced", "containing a healthy mix of foods"], ["tend to be", "usually are"]], "grammar": [{"pattern": "Time clause", "use": "the only time of day when + clause", "example": "the only time of day when everyone is in the same room", "try": "the only time when ______."}, {"pattern": "Concession with that said", "use": "That said, + it needn’t be...", "example": "That said, it needn’t be every night", "try": "That said, it needn’t be ______."}]}}, {"q": "Why are fewer and fewer people cooking at home these days?", "model": {"answer": "Time is the main culprit. After long commutes and demanding jobs, many people can’t face cooking, so they grab a takeaway or order delivery, and apps have made that so effortless that it’s become a habit. Some young people also never learned to cook because their parents did everything for them. If cooking were taught properly at school, I suspect it would become second nature again.", "phrases": [["long commute", "a tiring journey to work"], ["grab a takeaway", "quickly buy ready-made food"], ["do everything for (someone)", "handle all tasks so they never learn"], ["become second nature", "become automatic through practice"], ["the main culprit", "the chief cause of a problem"]], "grammar": [{"pattern": "so... that result", "use": "so + adjective + that + result", "example": "apps have made that so effortless that it’s become a habit", "try": "It’s so ______ that ______."}, {"pattern": "Second conditional", "use": "If + past simple (passive), would + verb", "example": "If cooking were taught properly at school, I suspect it would become second nature again", "try": "If ______ were taught at school, ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000003', 1003, 'Topic 3', 'Tall building', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 3, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a tall building in your town that you like or dislike", "bullets": ["where this building is", "what it looks like", "what it is used for", "explain why you like or dislike it"], "explain": "", "notes": ["Where", "Look", "Use", "Why"], "rounding": {"q": "Would you like to work in a building like that one day?", "model": {"answer": "Yes, I think so. The views would be wonderful, and being in a modern office would probably motivate me, although I might miss having a garden at lunchtime.", "phrases": [], "grammar": []}}, "model": {"answer": "One building that always catches my eye is a glass tower near my university in Tashkent. It’s about thirty storeys high, so you can see it from almost anywhere in that part of the city, and I walk past it every day on my way to class. It’s sleek and modern, with a curved glass front that catches the light at sunset and turns a lovely shade of orange. A thin metal spire crowns the top, and at night the whole structure glows blue. It towers over the older, low-rise blocks built in the Soviet era, which makes it a real landmark for the neighbourhood. It’s mostly offices, with a bank on the lower floors and a café at street level where my friends and I often stop for coffee. I’ve never been to the top, but a classmate whose father works there says the view from the restaurant on the twenty-eighth floor is breathtaking. I like it for a couple of reasons. For one thing, it gives the area a sense of identity; when I’m giving directions, I just say “the blue tower” and everybody knows where I mean. More importantly, it shows how far the city has come in recent years. Had it been built a decade ago, I doubt it would have looked so confident. Unlike some concrete eyesores nearby, it feels like it belongs in a modern capital. What I enjoy most is that it turns an ordinary walk to class into a small reminder that the city is moving forward.", "sections": [{"label": "Where", "text": "One building that always catches my eye is a glass tower near my university in Tashkent. It’s about thirty storeys high, so you can see it from almost anywhere in that part of the city, and I walk past it every day on my way to class."}, {"label": "Look", "text": "It’s sleek and modern, with a curved glass front that catches the light at sunset and turns a lovely shade of orange. A thin metal spire crowns the top, and at night the whole structure glows blue. It towers over the older, low-rise blocks built in the Soviet era, which makes it a real landmark for the neighbourhood."}, {"label": "Use", "text": "It’s mostly offices, with a bank on the lower floors and a café at street level where my friends and I often stop for coffee. I’ve never been to the top, but a classmate whose father works there says the view from the restaurant on the twenty-eighth floor is breathtaking."}, {"label": "Why", "text": "I like it for a couple of reasons. For one thing, it gives the area a sense of identity; when I’m giving directions, I just say “the blue tower” and everybody knows where I mean. More importantly, it shows how far the city has come in recent years. Had it been built a decade ago, I doubt it would have looked so confident. Unlike some concrete eyesores nearby, it feels like it belongs in a modern capital."}, {"label": "Reflection", "text": "What I enjoy most is that it turns an ordinary walk to class into a small reminder that the city is moving forward."}], "phrases": [["walk past", "go by on foot without stopping"], ["sleek and modern", "smooth, stylish and up to date"], ["catch the light", "reflect sunlight attractively"], ["tower over", "be much taller than"], ["a real landmark", "an easily recognised, important building"], ["breathtaking", "extremely beautiful"], ["a sense of identity", "a feeling of having a special character"], ["give directions", "tell someone how to get somewhere"], ["in recent years", "during the last few years"], ["eyesore", "something very ugly to look at"], ["belong", "fit naturally in a place"], ["move forward", "progress and develop"]], "grammar": [{"pattern": "Relative clause with whose", "use": "a person + whose + noun + verb", "example": "a classmate whose father works there says the view from the restaurant on the twenty-eighth floor is breathtaking", "try": "a friend whose ______ works ______."}, {"pattern": "Third conditional (inverted)", "use": "Had + subject + past participle, I doubt it would have + past participle", "example": "Had it been built a decade ago, I doubt it would have looked so confident", "try": "Had it been ______, it would have ______."}, {"pattern": "Result clause with which", "use": "clause + , which makes it + noun", "example": "which makes it a real landmark for the neighbourhood", "try": "..., which makes it ______."}, {"pattern": "Cleft sentence", "use": "What + subject + verb + is + that + clause", "example": "What I enjoy most is that it turns an ordinary walk to class into a small reminder", "try": "What I like most is that ______."}, {"pattern": "Participle reduced relative", "use": "noun + past participle: built in the Soviet era", "example": "the older, low-rise blocks built in the Soviet era", "try": "the old houses ______ in ______."}, {"pattern": "Comparison of degree", "use": "so + adjective: describing impressiveness", "example": "it shows how far the city has come in recent years", "try": "It shows how far ______ has come."}]}}, "part3": {"intro": "We’ve been talking about a tall building in your town that you like or dislike, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Tall building", "title": "Tall building", "questions": [{"q": "What are the advantages and disadvantages of living in a tall building?", "model": {"answer": "On the plus side, you get panoramic views, more sunlight and usually better security, with a concierge and lifts. The downsides are less obvious. You depend on elevators, which is a real nuisance when they break, and you can feel cut off from the street and from neighbours. Having no garden also means children have nowhere to run around. Personally, I’d enjoy the view but miss fresh air.", "phrases": [["on the plus side", "an advantage is that"], ["panoramic views", "wide, open views of the surroundings"], ["a real nuisance", "something quite annoying"], ["cut off from", "isolated from"], ["nowhere to run around", "no space to play freely"]], "grammar": [{"pattern": "Gerund subject", "use": "Having + noun + also means...", "example": "Having no garden also means children have nowhere to run around", "try": "Having no ______ means ______."}, {"pattern": "Non-defining relative", "use": "which is + noun + when + clause", "example": "which is a real nuisance when they break", "try": "..., which is a real nuisance when ______."}]}}, {"q": "Why are more and more tall buildings being built in cities nowadays?", "model": {"answer": "The simple answer is land. As cities grow, space is at a premium, so building upwards is the only way to house everyone and make the most of limited ground in the centre. Developers also see skyscrapers as status symbols that attract investment. Were land cheaper, I suspect far fewer towers would go up, because tall buildings cost much more to construct.", "phrases": [["at a premium", "scarce and therefore expensive"], ["build upwards", "construct tall buildings instead of wide ones"], ["make the most of", "use something as well as possible"], ["status symbol", "a possession that shows wealth or importance"], ["attract investment", "persuade people to put money in"]], "grammar": [{"pattern": "Inverted second conditional", "use": "Were + subject + adjective, + would + verb", "example": "Were land cheaper, I suspect far fewer towers would go up", "try": "Were ______ cheaper, ______ would ______."}, {"pattern": "As clause", "use": "As + subject + verb, + result", "example": "As cities grow, space is at a premium", "try": "As ______ grow, ______."}]}}, {"q": "Which do people in your country prefer to live in, a high-rise apartment or a house with a garden?", "model": {"answer": "It depends where you live. In Tashkent, many young professionals choose apartments because they’re within easy reach of work and more affordable, whereas in villages and smaller towns a house with a garden is the norm, and it’s what most people aspire to. Families in particular like growing fruit and having space for guests. So preferences are fairly evenly split between city and countryside.", "phrases": [["within easy reach of", "close and convenient to get to"], ["more affordable", "cheaper and easier to pay for"], ["the norm", "what is normal or usual"], ["aspire to", "hope to achieve or have"], ["evenly split", "divided roughly equally"]], "grammar": [{"pattern": "Cleft with what", "use": "what + most people + aspire to", "example": "it’s what most people aspire to", "try": "It’s what most ______ want."}, {"pattern": "Contrast with whereas", "use": "clause, whereas clause", "example": "whereas in villages and smaller towns a house with a garden is the norm", "try": "..., whereas in ______."}]}}, {"q": "What do you think buildings will be like in the future?", "model": {"answer": "I expect they’ll be far greener. Architects are already experimenting with rooftop gardens and solar panels built into walls, and I wouldn’t be surprised if future towers generate their own power. Buildings will probably also be smarter, with sensors that adjust heating automatically to cut energy bills. Whether people will enjoy living in them is another matter, but sustainability will drive the design.", "phrases": [["rooftop garden", "a garden planted on top of a building"], ["generate their own power", "produce electricity themselves"], ["cut energy bills", "reduce the cost of electricity and heating"], ["drive the design", "strongly influence how something is made"], ["another matter", "a separate question"]], "grammar": [{"pattern": "Wouldn’t be surprised if", "use": "I wouldn’t be surprised if + present simple", "example": "I wouldn’t be surprised if future towers generate their own power", "try": "I wouldn’t be surprised if ______."}, {"pattern": "Whether clause as subject", "use": "Whether + clause + is another matter", "example": "Whether people will enjoy living in them is another matter", "try": "Whether ______ is another matter."}]}}, {"q": "Should cities put a limit on how tall new buildings can be?", "model": {"answer": "In historic areas, yes. If a skyscraper went up beside an old madrasa, it would overshadow it and spoil the character of the district. In newer business zones, though, strict limits could be counterproductive, because they would push prices up and spread the city outwards. A sensible compromise is to protect heritage sites and allow height elsewhere, provided the buildings are safe and well planned.", "phrases": [["overshadow", "make something look less important by being bigger"], ["spoil the character", "ruin what makes a place special"], ["counterproductive", "having the opposite of the intended effect"], ["protect heritage sites", "preserve historic places"], ["allow height elsewhere", "permit tall buildings in other areas"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "If a skyscraper went up beside an old madrasa, it would overshadow it", "try": "If a tower went up beside ______, it would ______."}, {"pattern": "Provided that", "use": "provided (that) + condition", "example": "provided the buildings are safe and well planned", "try": "..., provided ______."}]}}, {"q": "How do tall buildings change the appearance of a city?", "model": {"answer": "They transform a skyline, for better or worse. A cluster of well-designed towers can give a city a modern, confident image, and some become iconic landmarks that people associate with the place. But when they’re badly planned, they block out the sun, make streets feel dark and windswept, and clash with older architecture. Whether the result impresses or disappoints mostly comes down to the quality of the design.", "phrases": [["modern, confident image", "an up-to-date and self-assured look"], ["iconic landmark", "a famous building that symbolises a place"], ["block out the sun", "stop sunlight from reaching a place"], ["clash with", "look wrong next to something else"], ["come down to", "depend mainly on"]], "grammar": [{"pattern": "Defining relative with preposition", "use": "landmarks that people associate with the place", "example": "iconic landmarks that people associate with the place", "try": "a building that people ______ with ______."}, {"pattern": "When clause contrast", "use": "But when + passive, they + verb", "example": "But when they’re badly planned, they block out the sun", "try": "But when they’re badly ______, they ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000004', 1004, 'Topic 4', 'Getting up early', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 4, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an occasion when you got up extremely early", "bullets": ["when this happened", "what you needed to do on that day", "who you were with", "how you felt about getting up early on that day"], "explain": "", "notes": ["When", "What", "Who", "Feelings"], "rounding": {"q": "Do you find it easier to get up early when you’re excited about something?", "model": {"answer": "Definitely. If I’m looking forward to something, I wake up before the alarm, but on an ordinary Monday I need at least two alarms and a lot of willpower.", "phrases": [], "grammar": []}}, "model": {"answer": "The occasion I’ll never forget is the morning I dragged myself out of bed at four o’clock to catch a flight to Istanbul, two summers ago. I’m definitely not a morning person, so it felt like quite an ordeal. Our flight was at seven, and with check-in closing so early we had very little leeway. I’d packed the night before, but I was so excited that I hardly slept a wink. When the alarm went off, I woke up with a start, convinced I’d overslept, and spent ten minutes rushing around checking passports, chargers and tickets. The taxi was booked for half past four, and I was terrified we’d be running late. I was travelling with my younger sister, Madina, who, to my surprise, was bright-eyed and bushy-tailed from the moment she woke up. While I was fumbling for my shoes, she was already waiting by the door, joking that I looked like a zombie. At first I felt groggy and grumpy, and I’m not sure I said a single word in the taxi. But when we reached the airport, the streets were silent and the sky was turning pink, and my mood gradually lifted. Never had I seen Tashkent so peaceful. By the time we boarded, I was wide awake and buzzing with excitement. Looking back, if I hadn’t forced myself up, I’d have missed not just the flight but a rare moment of calm. The hardest part of an early start, I’ve learnt, is always the first five minutes.", "sections": [{"label": "When", "text": "The occasion I’ll never forget is the morning I dragged myself out of bed at four o’clock to catch a flight to Istanbul, two summers ago. I’m definitely not a morning person, so it felt like quite an ordeal."}, {"label": "What", "text": "Our flight was at seven, and with check-in closing so early we had very little leeway. I’d packed the night before, but I was so excited that I hardly slept a wink. When the alarm went off, I woke up with a start, convinced I’d overslept, and spent ten minutes rushing around checking passports, chargers and tickets. The taxi was booked for half past four, and I was terrified we’d be running late."}, {"label": "Who", "text": "I was travelling with my younger sister, Madina, who, to my surprise, was bright-eyed and bushy-tailed from the moment she woke up. While I was fumbling for my shoes, she was already waiting by the door, joking that I looked like a zombie."}, {"label": "Feelings", "text": "At first I felt groggy and grumpy, and I’m not sure I said a single word in the taxi. But when we reached the airport, the streets were silent and the sky was turning pink, and my mood gradually lifted. Never had I seen Tashkent so peaceful. By the time we boarded, I was wide awake and buzzing with excitement."}, {"label": "Reflection", "text": "Looking back, if I hadn’t forced myself up, I’d have missed not just the flight but a rare moment of calm. The hardest part of an early start, I’ve learnt, is always the first five minutes."}], "phrases": [["drag yourself out of bed", "force yourself to get up when you don’t want to"], ["leeway", "extra time or room for mistakes"], ["hardly sleep a wink", "get almost no sleep"], ["wake up with a start", "wake suddenly, often in shock"], ["rush around", "hurry from one task to another"], ["run late", "be behind schedule"], ["bright-eyed and bushy-tailed", "full of energy and enthusiasm"], ["fumble", "search clumsily with your hands"], ["groggy", "slow and heavy because you are still sleepy"], ["lift", "become more cheerful"], ["buzzing", "very excited and energetic"]], "grammar": [{"pattern": "Past perfect", "use": "had + past participle: an earlier past action", "example": "I’d packed the night before", "try": "I’d ______ the night before."}, {"pattern": "so... that", "use": "so + adjective + that + result", "example": "I was so excited that I hardly slept a wink", "try": "I was so ______ that I ______."}, {"pattern": "Inversion with never", "use": "Never + had + subject + past participle", "example": "Never had I seen Tashkent so peaceful", "try": "Never had I ______ so ______."}, {"pattern": "Third conditional", "use": "If + past perfect, would have + past participle", "example": "if I hadn’t forced myself up, I’d have missed not just the flight but a rare moment of calm", "try": "If I hadn’t ______, I’d have ______."}, {"pattern": "Past continuous with while", "use": "While + past continuous, past continuous/simple", "example": "While I was fumbling for my shoes, she was already waiting by the door", "try": "While I was ______, she ______."}, {"pattern": "Adjective + clause", "use": "convinced + (that) + past perfect", "example": "convinced I’d overslept", "try": "convinced I’d ______."}]}}, "part3": {"intro": "We’ve been talking about an occasion when you got up extremely early, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Getting up early", "title": "Getting up early", "questions": [{"q": "Why do some people get up very early?", "model": {"answer": "For many, it’s a matter of necessity or simply routine. Farmers, bakers and market traders start work at dawn because their customers are waiting. Others simply feel at their best in the morning and like to get a head start on the day, whether that means exercising, studying or having breakfast without rushing. Some also enjoy the peace and quiet before everyone else wakes up.", "phrases": [["start work at dawn", "begin working at sunrise"], ["feel at one’s best", "be at the peak of energy and ability"], ["get a head start", "begin before others to gain an advantage"], ["peace and quiet", "calm without noise"], ["a matter of necessity", "something you have to do"]], "grammar": [{"pattern": "Whether clause", "use": "whether + verb-ing, verb-ing or verb-ing", "example": "whether that means exercising, studying or having breakfast without rushing", "try": "whether that means ______ or ______."}, {"pattern": "Because clause", "use": "because + subject + be + -ing", "example": "because their customers are waiting", "try": "..., because ______ are waiting."}]}}, {"q": "Is it easy for people to change their sleeping habits?", "model": {"answer": "Not really, at least not overnight. The body clock is surprisingly stubborn, so forcing yourself to wake up two hours earlier usually leaves you drowsy and irritable for days. The trick is to shift your schedule gradually, say by fifteen minutes every few days. Still, people with night-shift jobs or young children often find it almost impossible, because circumstances rather than willpower decide when they sleep.", "phrases": [["body clock", "your natural daily rhythm of sleep"], ["drowsy", "sleepy and slow"], ["shift your schedule gradually", "change your timetable a little at a time"], ["night-shift job", "work done during the night"], ["willpower", "strength to control your own actions"]], "grammar": [{"pattern": "Gerund subject", "use": "forcing + yourself + to + verb + usually leaves you + adjective", "example": "forcing yourself to wake up two hours earlier usually leaves you drowsy and irritable for days", "try": "Forcing yourself to ______ usually leaves you ______."}, {"pattern": "Contrast with rather than", "use": "A rather than B + verb", "example": "circumstances rather than willpower decide when they sleep", "try": "______ rather than ______ decide(s) ______."}]}}, {"q": "Why do some people prefer to stay up late at night?", "model": {"answer": "Quite a few people say they come alive after dark. Once the day’s obligations are over, nobody interrupts them, so they use the late hours for hobbies, gaming or catching up on series. Students, in particular, tend to burn the midnight oil before exams. And then there’s the pull of screens: it’s easy to say “one more episode” and lose track of time until it’s two in the morning.", "phrases": [["come alive", "become energetic and lively"], ["catch up on", "do or watch something you missed"], ["burn the midnight oil", "work late into the night"], ["lose track of time", "not notice how much time has passed"], ["the pull of", "the attraction of"]], "grammar": [{"pattern": "Once clause", "use": "Once + present simple, + subject + verb", "example": "Once the day’s obligations are over, nobody interrupts them", "try": "Once ______ is over, ______."}, {"pattern": "Until clause", "use": "verb + until + time", "example": "lose track of time until it’s two in the morning", "try": "..., until it’s ______."}]}}, {"q": "Are there any situations in which it is particularly important to arrive early?", "model": {"answer": "Definitely, such as job interviews and exams. Arriving early shows you’re reliable, and it gives you time to settle your nerves and find the room. It matters at airports too, where cutting it fine can be costly. And at a first meeting, punctuality is a sign of respect; if you turn up late, you can give the wrong impression before you’ve said a word.", "phrases": [["settle one’s nerves", "become calm before something stressful"], ["cut it fine", "leave very little time"], ["a sign of respect", "evidence that you value someone"], ["give the wrong impression", "make people think something untrue about you"], ["turn up", "arrive"]], "grammar": [{"pattern": "Relative clause with where", "use": "airports, where + clause", "example": "It matters at airports too, where cutting it fine can be costly", "try": "..., where ______ can be ______."}, {"pattern": "First conditional", "use": "if + present simple, can + verb", "example": "if you turn up late, you can give the wrong impression before you’ve said a word", "try": "If you ______, you can ______."}]}}, {"q": "Do you think people who get up early are more productive?", "model": {"answer": "Not necessarily. Early risers often get more done before lunch, but that’s partly because they’ve cleared the decks before distractions begin. Night owls can be just as effective if their schedule suits their natural rhythm. What matters is when you’re mentally at your sharpest and whether you can protect that time. In my own case, I get through twice as much in the morning, but that’s down to personal preference.", "phrases": [["clear the decks", "finish other tasks so you can concentrate"], ["suit one’s natural rhythm", "fit your body’s own pattern"], ["at one’s sharpest", "thinking most clearly"], ["get through", "finish a lot of work"], ["down to", "caused by"]], "grammar": [{"pattern": "Cleft with what", "use": "What + matters + is + when/whether clause", "example": "What matters is when you’re mentally at your sharpest", "try": "What matters is whether ______."}, {"pattern": "Concessive but", "use": "clause + , but + that’s + down to", "example": "but that’s down to personal preference", "try": "..., but that’s down to ______."}]}}, {"q": "How might a lack of sleep affect people’s work or studies?", "model": {"answer": "It affects almost everything. Sleep-deprived people struggle to concentrate, make careless mistakes and take longer to finish tasks. Students who pull all-nighters before exams often perform worse, because memory is consolidated during sleep. Over time, it also takes a toll on mood and health, making people irritable and more prone to illness. In some jobs, such as driving, it can even put lives at risk.", "phrases": [["sleep-deprived", "not getting enough sleep"], ["make careless mistakes", "make errors by not paying attention"], ["pull an all-nighter", "stay awake all night to work"], ["take a toll on", "cause gradual damage to"], ["put lives at risk", "endanger people’s lives"]], "grammar": [{"pattern": "Relative clause", "use": "Students who + verb + often + verb", "example": "Students who pull all-nighters before exams often perform worse", "try": "People who ______ often ______."}, {"pattern": "Participle result", "use": "comma + -ing: result", "example": "making people irritable and more prone to illness", "try": "..., making people ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000005', 1005, 'Topic 5', 'New law', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 5, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a new law you would like to introduce in your country", "bullets": ["what the law is", "what changes it would bring", "whether it would be popular", "and explain how you came up with the idea"], "explain": "", "notes": ["What", "Changes", "Popular", "How I Came Up With It"], "rounding": {"q": "Do you think young people would take such a course seriously?", "model": {"answer": "Most would, I think, as long as it’s practical rather than theoretical. Teenagers enjoy hands-on lessons, and the thought that they could actually save someone makes it feel important.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had the power to introduce one new law, it would be this: every secondary school student must pass a first-aid course before they graduate. It would cover how to perform CPR, what to do when someone is choking and how to stop heavy bleeding, with a short practical test at the end. I’m convinced it would save lives in the long run. At the moment, when someone collapses in the street, people tend to freeze or simply call an ambulance and wait. If a whole generation were trained, there’d be somebody in nearly every crowd who knew what to do. It would also boost young people’s confidence and make them feel responsible for others. I think most people would welcome it, especially parents. Some students might grumble about an extra subject, and schools would worry about fitting it into an already packed timetable, but once people see the value of it, I’d expect the resistance to fade. Hardly anyone argues against learning how to save a life. The idea came to me two years ago when an elderly man collapsed at a bus stop near my university. A small crowd gathered, but nobody knew what to do, and precious minutes ticked by before the ambulance arrived. I remember feeling completely helpless, which is a feeling I never want to have again. Had I known first aid, I could have stepped in. He survived, thankfully, but the incident has stuck with me ever since.", "sections": [{"label": "What", "text": "If I had the power to introduce one new law, it would be this: every secondary school student must pass a first-aid course before they graduate. It would cover how to perform CPR, what to do when someone is choking and how to stop heavy bleeding, with a short practical test at the end."}, {"label": "Changes", "text": "I’m convinced it would save lives in the long run. At the moment, when someone collapses in the street, people tend to freeze or simply call an ambulance and wait. If a whole generation were trained, there’d be somebody in nearly every crowd who knew what to do. It would also boost young people’s confidence and make them feel responsible for others."}, {"label": "Popular", "text": "I think most people would welcome it, especially parents. Some students might grumble about an extra subject, and schools would worry about fitting it into an already packed timetable, but once people see the value of it, I’d expect the resistance to fade. Hardly anyone argues against learning how to save a life."}, {"label": "How I Came Up With It", "text": "The idea came to me two years ago when an elderly man collapsed at a bus stop near my university. A small crowd gathered, but nobody knew what to do, and precious minutes ticked by before the ambulance arrived. I remember feeling completely helpless, which is a feeling I never want to have again. Had I known first aid, I could have stepped in. He survived, thankfully, but the incident has stuck with me ever since."}], "phrases": [["perform CPR", "carry out emergency chest compressions to restart the heart"], ["stop heavy bleeding", "prevent someone losing a lot of blood"], ["save lives", "prevent people from dying"], ["freeze", "become unable to move or act because of shock"], ["boost (someone’s) confidence", "make someone feel more sure of themselves"], ["packed timetable", "a schedule with no free space"], ["see the value of", "recognise the usefulness of"], ["precious minutes", "time that is extremely important"], ["helpless", "unable to do anything to help"], ["step in", "get involved to help"], ["stick with (someone)", "stay in someone’s mind"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If I had the power to introduce one new law, it would be this", "try": "If I had the power to ______, I’d ______."}, {"pattern": "Subjunctive-style passive", "use": "If + subject + were + past participle", "example": "If a whole generation were trained, there’d be somebody in nearly every crowd who knew what to do", "try": "If everyone were ______, there’d be ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, could have + past participle", "example": "Had I known first aid, I could have stepped in", "try": "Had I ______, I could have ______."}, {"pattern": "Negative adverb", "use": "Hardly anyone + present simple", "example": "Hardly anyone argues against learning how to save a life", "try": "Hardly anyone ______."}, {"pattern": "Reduced relative with which", "use": "a feeling + (that) + I + verb", "example": "which is a feeling I never want to have again", "try": "..., which is a feeling I ______."}, {"pattern": "Present perfect with ever since", "use": "has + past participle + ever since", "example": "the incident has stuck with me ever since", "try": "______ has ______ ever since."}]}}, "part3": {"intro": "We’ve been talking about a new law you would like to introduce in your country, and now I’d like to discuss with you one or two general questions related to this.", "theme": "New law", "title": "New law", "questions": [{"q": "Do people in your country generally obey the law?", "model": {"answer": "For the most part, yes, though it varies by the type of rule. Most people abide by serious laws, such as those against theft, because the consequences are obvious. Minor rules are another story; jaywalking and illegal parking are often taken lightly, especially when authorities turn a blind eye. I’d say enforcement matters more than the rule itself: when fines are applied consistently, compliance rises quickly.", "phrases": [["abide by", "follow a rule or law"], ["another story", "a completely different situation"], ["take lightly", "not treat as serious"], ["turn a blind eye", "deliberately ignore something wrong"], ["compliance", "the act of following rules"]], "grammar": [{"pattern": "Passive when clause", "use": "when + noun + are + past participle, + result", "example": "when fines are applied consistently, compliance rises quickly", "try": "when ______ are applied consistently, ______."}, {"pattern": "", "use": "Reduced relative: those against such as those against + noun", "example": "such as those against theft", "try": "serious laws, such as those against ______."}]}}, {"q": "What kinds of rules do schools or workplaces have in your country?", "model": {"answer": "Schools tend to be strict about punctuality, uniforms and mobile phones, and students are expected to show respect to teachers. Workplaces focus on office hours, a dress code and confidentiality, and many companies have clear-cut safety procedures. Interestingly, private firms are often stricter than state organisations, because employers can dismiss staff quickly, whereas schools are expected to give pupils a second chance.", "phrases": [["show respect", "behave politely towards someone"], ["office hours", "the times when people must be at work"], ["dress code", "rules about what to wear"], ["clear-cut", "obvious and well defined"], ["give someone a second chance", "allow another opportunity after a mistake"]], "grammar": [{"pattern": "Passive with expected to", "use": "be + expected to + verb", "example": "students are expected to show respect to teachers", "try": "Employees are expected to ______."}, {"pattern": "Contrast with whereas", "use": "clause, whereas + clause", "example": "whereas schools are expected to give pupils a second chance", "try": "..., whereas ______."}]}}, {"q": "Why is it important for a society to have laws?", "model": {"answer": "Without laws, society would descend into chaos, because the strongest or richest would simply take what they wanted. Laws protect the vulnerable, settle disputes fairly and give everybody the same ground rules. They also make daily life predictable: I can drive, sign a contract or buy medicine without worrying that I’ll be cheated. In short, laws are what allow strangers to trust one another.", "phrases": [["descend into chaos", "become disordered and out of control"], ["protect the vulnerable", "keep weaker people safe"], ["ground rules", "basic rules everyone must follow"], ["cheat", "trick someone dishonestly"], ["trust one another", "believe in each other’s honesty"]], "grammar": [{"pattern": "Without + noun, would", "use": "Without + noun, subject + would + verb", "example": "Without laws, society would descend into chaos", "try": "Without ______, ______ would ______."}, {"pattern": "Cleft with what", "use": "laws are what allow + object + to + verb", "example": "laws are what allow strangers to trust one another", "try": "______ are what allow people to ______."}]}}, {"q": "How can parents teach children to follow rules?", "model": {"answer": "Chiefly by setting an example. Children notice everything, so if parents tell them to wait for the green light and then cross on red, the message is lost. Explaining the reason behind each rule also helps, because kids are more likely to comply when they understand it. And consistency is vital: rewarding good behaviour and applying sensible consequences teaches responsibility without resorting to shouting.", "phrases": [["set an example", "behave in the way you want others to behave"], ["cross on red", "walk across a road when the signal says stop"], ["more likely to comply", "more probable to obey"], ["reward good behaviour", "give praise or prizes for behaving well"], ["resort to shouting", "end up shouting as a last option"]], "grammar": [{"pattern": "First conditional", "use": "if + present simple, the message + is", "example": "if parents tell them to wait for the green light and then cross on red, the message is lost", "try": "If parents ______, the message is ______."}, {"pattern": "Without + gerund", "use": "without + verb-ing", "example": "without resorting to shouting", "try": "..., without ______ing."}]}}, {"q": "How should people who repeatedly break rules be dealt with?", "model": {"answer": "It depends on the offence. For minor ones, such as repeated traffic violations, escalating fines or losing a licence tend to work. For serious cases, I believe rehabilitation matters as much as punishment, since sending someone to prison without addressing the root causes often leads to reoffending. Ideally, offenders would learn a trade or receive counselling, so they can reintegrate into society.", "phrases": [["escalating fine", "a penalty that grows bigger each time"], ["rehabilitation", "helping an offender return to a normal life"], ["address the root cause", "deal with the original reason for a problem"], ["reoffend", "commit a crime again"], ["reintegrate into society", "return to normal community life"]], "grammar": [{"pattern": "Without + gerund", "use": "since + verb-ing + object + without + verb-ing", "example": "sending someone to prison without addressing the root causes often leads to reoffending", "try": "Sending someone to ______ without ______ often ______."}, {"pattern": "Purpose clause with so", "use": "so + subject + can + verb", "example": "so they can reintegrate into society", "try": "..., so they can ______."}]}}, {"q": "Do you think children can learn about the law outside school?", "model": {"answer": "Certainly. Children pick up a lot from watching adults, from seeing how people queue or react to a police officer to hearing family discussions about fines. Videos and even games can raise awareness of legal basics, and activities such as youth clubs or mock trials bring the subject to life. That said, structured lessons at school remain valuable for filling in the gaps.", "phrases": [["pick up", "learn without being taught"], ["raise awareness", "help people become more informed"], ["mock trial", "a pretend court case for learning"], ["bring (something) to life", "make a subject vivid and interesting"], ["fill in the gaps", "provide missing knowledge"]], "grammar": [{"pattern": "Concession with that said", "use": "That said, + clause", "example": "That said, structured lessons at school remain valuable", "try": "That said, ______ remains valuable."}, {"pattern": "Preposition + gerund", "use": "valuable for + verb-ing", "example": "remain valuable for filling in the gaps", "try": "valuable for ______ing ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000006', 1006, 'Topic 6', 'Person who loves to grow plants', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 6, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person you know who loves to grow plants (vegetables, fruits, flowers)", "bullets": ["who this person is", "what this person grows", "where this person grows them", "why this person loves to grow plants"], "explain": "", "notes": ["Who", "What", "Where", "Why"], "rounding": {"q": "Have you ever tried growing anything yourself?", "model": {"answer": "Only herbs on a windowsill, to be honest. Basil survived for a few months, but I clearly didn’t inherit my grandfather’s green thumb, so I’m planning to learn from him.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be my grandfather, who lives in a village outside Samarkand. He’s seventy-three, retired from teaching years ago, and has a green thumb that would put most professional gardeners to shame. He grows a bit of everything. In spring it’s tomatoes, cucumbers and peppers, and by summer his grapevines are laden with fruit. There’s also a row of apricot and pomegranate trees, and along the path he tends roses that he’s been looking after for decades. Every visit I leave with a bag of home-grown produce that tastes nothing like the supermarket stuff. It’s all in his back garden, which is about the size of a tennis court. He’s squeezed in every inch: vines on a trellis for shade, vegetable beds in neat rows, and a small greenhouse he built from scratch using old window frames. In the middle sits a wooden bench where he has his morning tea, taking great pride in the view. He says gardening keeps him young, and I believe it. After retiring, he felt at a loose end until he started planting, and now he’s out there at six every morning. There’s nothing he enjoys more than handing a basket of figs to a neighbour. I once asked why he bothered, and he said, “A tree gives back more than you put in.” It’s clearly a labour of love. What I’ve learnt from him is patience, and some of it has rubbed off on me.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be my grandfather, who lives in a village outside Samarkand. He’s seventy-three, retired from teaching years ago, and has a green thumb that would put most professional gardeners to shame."}, {"label": "What", "text": "He grows a bit of everything. In spring it’s tomatoes, cucumbers and peppers, and by summer his grapevines are laden with fruit. There’s also a row of apricot and pomegranate trees, and along the path he tends roses that he’s been looking after for decades. Every visit I leave with a bag of home-grown produce that tastes nothing like the supermarket stuff."}, {"label": "Where", "text": "It’s all in his back garden, which is about the size of a tennis court. He’s squeezed in every inch: vines on a trellis for shade, vegetable beds in neat rows, and a small greenhouse he built from scratch using old window frames. In the middle sits a wooden bench where he has his morning tea, taking great pride in the view."}, {"label": "Why", "text": "He says gardening keeps him young, and I believe it. After retiring, he felt at a loose end until he started planting, and now he’s out there at six every morning. There’s nothing he enjoys more than handing a basket of figs to a neighbour. I once asked why he bothered, and he said, “A tree gives back more than you put in.” It’s clearly a labour of love."}, {"label": "Reflection", "text": "What I’ve learnt from him is patience, and some of it has rubbed off on me."}], "phrases": [["a green thumb", "a natural talent for growing plants"], ["put (someone) to shame", "be much better than"], ["laden with", "carrying a lot of"], ["look after", "take care of"], ["home-grown", "produced in your own garden"], ["from scratch", "starting with nothing prepared"], ["take pride in", "feel pleased about your achievements"], ["keep (someone) young", "make someone feel full of life"], ["at a loose end", "with nothing useful to do"], ["a labour of love", "work done willingly because you love it"], ["rub off on", "gradually influence someone"]], "grammar": [{"pattern": "Relative clause with who", "use": "a person, who + verb: extra information", "example": "my grandfather, who lives in a village outside Samarkand", "try": "my uncle, who lives ______."}, {"pattern": "Would for a hypothetical", "use": "comparison a noun + that + would + verb", "example": "a green thumb that would put most professional gardeners to shame", "try": "a talent that would ______."}, {"pattern": "Present perfect continuous", "use": "has/have been + -ing + for + period", "example": "roses that he’s been looking after for decades", "try": "______ that I’ve been ______ing for ______."}, {"pattern": "Cleft sentence", "use": "There’s nothing + subject + verb + more than + gerund", "example": "There’s nothing he enjoys more than handing a basket of figs to a neighbour", "try": "There’s nothing I enjoy more than ______ing."}, {"pattern": "Participle clause", "use": "comma + -ing phrase: a person’s action", "example": "taking great pride in the view", "try": "..., ______ing great pride in ______."}, {"pattern": "Relative with which", "use": "noun + , which is + size description", "example": "which is about the size of a tennis court", "try": "..., which is about the size of ______."}]}}, "part3": {"intro": "We’ve been talking about a person you know who loves to grow plants, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who loves to grow plants", "title": "Person who loves to grow plants", "questions": [{"q": "Do many people in your country grow their own plants or vegetables?", "model": {"answer": "Quite a few do, particularly outside the big cities. In villages, almost every household has a vegetable patch or a few fruit trees, and even in Tashkent, many families keep a small plot at a dacha or grow herbs on their balcony. It’s partly a long-standing tradition and partly practical, since home-grown produce cuts down on grocery bills. In apartment blocks, though, it’s much less common.", "phrases": [["vegetable patch", "a small area for growing vegetables"], ["keep a small plot", "own a little piece of land"], ["long-standing tradition", "a custom that has existed for a long time"], ["cut down on", "reduce"], ["household", "all the people living in one home"]], "grammar": [{"pattern": "Partly... partly...", "use": "It’s partly A and partly B: two reasons", "example": "It’s partly a long-standing tradition and partly practical", "try": "It’s partly ______ and partly ______."}, {"pattern": "Since clause", "use": "since + reason", "example": "since home-grown produce cuts down on grocery bills", "try": "..., since ______."}]}}, {"q": "What are the benefits of growing plants at home?", "model": {"answer": "There are benefits for body and mind. Tending plants gets you outdoors and gently active, and many people find the routine helps them unwind. Greenery can also freshen up a room and make a flat feel welcoming. For children, watching a seed become something edible is an eye-opener. And of course you save a little money and know exactly what went into your food.", "phrases": [["help someone unwind", "help someone relax"], ["freshen up", "make a place look brighter"], ["an eye-opener", "a surprising, educational experience"], ["know exactly what went into", "be certain about the ingredients"], ["gently active", "exercising lightly"]], "grammar": [{"pattern": "Participle clause", "use": "Tending plants gets you + adverbial", "example": "Tending plants gets you outdoors and gently active", "try": "Tending ______ gets you ______."}, {"pattern": "Watching + verb", "use": "watching + object + become + noun", "example": "watching a seed become something edible is an eye-opener", "try": "Watching ______ become ______ is ______."}]}}, {"q": "Why do some people prefer to grow vegetables rather than buy them?", "model": {"answer": "Mostly because of taste and trust. Home-grown tomatoes simply taste better, and growers know their crops are free from chemicals. Some people also like the idea of being self-sufficient, since it feels good to depend less on shops. There’s a thrifty side too: a few packets of seeds can yield kilos of vegetables. Not everyone has time, but those who do usually find it well worth the effort.", "phrases": [["free from chemicals", "containing no artificial substances"], ["self-sufficient", "able to provide for yourself"], ["yield", "produce a quantity of crops"], ["well worth the effort", "definitely deserving the work involved"], ["thrifty", "careful with money"]], "grammar": [{"pattern": "Those who", "use": "those who + verb", "example": "those who do usually find it well worth the effort", "try": "Those who ______ usually ______."}, {"pattern": "Since + gerund", "use": "depend less on + noun", "example": "to depend less on shops", "try": "It feels good to depend less on ______."}]}}, {"q": "How do people feel when they eat food they have grown themselves?", "model": {"answer": "Usually proud, and a little protective. There’s a special satisfaction in eating the fruits of your labour, because you’ve watched each plant grow from a seedling. My grandfather’s first tomato of the season is practically a ceremony; he shares it with everybody. People also tend to feel more connected to nature and appreciate food more, so they waste less and enjoy a real sense of achievement.", "phrases": [["eat the fruits of your labour", "enjoy the result of your hard work"], ["connected to nature", "feeling close to the natural world"], ["appreciate food more", "value what you eat"], ["sense of achievement", "feeling of having done something well"], ["protective", "wanting to guard something"]], "grammar": [{"pattern": "Because + present perfect", "use": "because you’ve watched + object + verb", "example": "because you’ve watched each plant grow from a seedling", "try": "because you’ve watched ______ grow."}, {"pattern": "So + result", "use": "so + subject + verb", "example": "so they waste less", "try": "..., so they ______."}]}}, {"q": "Who is more interested in gardening, older people or younger people?", "model": {"answer": "Traditionally, older people, who have more free time and often a garden, but that’s shifting. Many young people are now keen on urban gardening, growing herbs on windowsills and sharing tips online. They’re often motivated by sustainability rather than necessity. So while older generations garden out of habit, the younger ones tend to do it out of curiosity or concern for the environment.", "phrases": [["shift", "change gradually"], ["urban gardening", "growing plants in cities"], ["out of habit", "because it is a routine"], ["out of curiosity", "because you want to find out"], ["concern for the environment", "worry about protecting nature"]], "grammar": [{"pattern": "Reduced contrast", "use": "while + clause, + clause", "example": "while older generations garden out of habit, the younger ones tend to do it out of curiosity", "try": "While ______ do it out of ______, ______."}, {"pattern": "Non-defining relative", "use": "people, who + verb", "example": "older people, who have more free time and often a garden", "try": "older people, who ______."}]}}, {"q": "Should schools teach children how to grow plants?", "model": {"answer": "I think so, and the earlier the better. A school garden teaches responsibility, since plants die if you forget to water them, and it links directly to biology and nutrition. Children who grow carrots are far more likely to eat them. It also gets them away from screens and working as a team. Admittedly, crowded city schools lack space, but even window boxes would do the trick.", "phrases": [["teach responsibility", "help children learn to be reliable"], ["away from screens", "not using phones or computers"], ["window box", "a long container for plants on a windowsill"], ["do the trick", "achieve the desired result"], ["link directly to", "be closely connected with"]], "grammar": [{"pattern": "The + comparative", "use": "the earlier the better", "example": "the earlier the better", "try": "The ______ the better."}, {"pattern": "Defining relative", "use": "Children who + verb + are far more likely to + verb", "example": "Children who grow carrots are far more likely to eat them", "try": "People who ______ are far more likely to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000007', 1007, 'Topic 7', 'Childhood friend', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 7, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a friend from your childhood", "bullets": ["who this person is", "how you met each other", "what you did together", "explain why you liked him or her"], "explain": "", "notes": ["Who", "How We Met", "What We Did", "Why I Liked Him"], "rounding": {"q": "Do you still have anything that reminds you of those days?", "model": {"answer": "Yes, I’ve still got a faded photograph of the two of us on that bicycle. It lives in my desk drawer, and I smile every time I come across it.", "phrases": [], "grammar": []}}, "model": {"answer": "The first person who comes to mind is Rustam, a boy who lived two doors down from us in Samarkand. He was a skinny, cheeky kid with a gap in his front teeth, and he was always up to something. We met on my sixth birthday, of all days. Nobody had told me he’d been invited, so when a stranger turned up holding a battered football, I assumed he’d come to the wrong house. His mother struck up a conversation with mine over tea, and within an hour we were kicking the ball round the courtyard as if we’d known each other for years. Never had I hit it off with anyone so quickly. After that, we were joined at the hip. Most summer evenings we’d play football until the light faded, and when it rained we’d build dens out of blankets and chairs. One summer we saved our pocket money for weeks to buy a secondhand bicycle, which we shared, taking turns to ride and to push. We also got into scrapes now and then; I still remember getting told off by his grandmother for climbing her apricot tree. What I liked most about him was that he never showed off. He was the sort of person who’d stick up for you, even if it meant getting into trouble himself, and he could make me laugh until my stomach hurt. Around him, I always felt I could simply be myself. We drifted apart when his family moved to Tashkent, and I regret that we didn’t try harder to keep in touch. Still, if I bumped into him tomorrow, I’m sure we’d pick up where we left off.", "sections": [{"label": "Who", "text": "The first person who comes to mind is Rustam, a boy who lived two doors down from us in Samarkand. He was a skinny, cheeky kid with a gap in his front teeth, and he was always up to something."}, {"label": "How We Met", "text": "We met on my sixth birthday, of all days. Nobody had told me he’d been invited, so when a stranger turned up holding a battered football, I assumed he’d come to the wrong house. His mother struck up a conversation with mine over tea, and within an hour we were kicking the ball round the courtyard as if we’d known each other for years. Never had I hit it off with anyone so quickly."}, {"label": "What We Did", "text": "After that, we were joined at the hip. Most summer evenings we’d play football until the light faded, and when it rained we’d build dens out of blankets and chairs. One summer we saved our pocket money for weeks to buy a secondhand bicycle, which we shared, taking turns to ride and to push. We also got into scrapes now and then; I still remember getting told off by his grandmother for climbing her apricot tree."}, {"label": "Why I Liked Him", "text": "What I liked most about him was that he never showed off. He was the sort of person who’d stick up for you, even if it meant getting into trouble himself, and he could make me laugh until my stomach hurt. Around him, I always felt I could simply be myself."}, {"label": "Reflection", "text": "We drifted apart when his family moved to Tashkent, and I regret that we didn’t try harder to keep in touch. Still, if I bumped into him tomorrow, I’m sure we’d pick up where we left off."}], "phrases": [["cheeky", "playfully rude or disrespectful in a way that is hard to dislike"], ["up to something", "doing something mischievous, often secretly"], ["strike up a conversation", "begin talking to someone, usually a stranger"], ["hit it off", "get on well with someone immediately"], ["joined at the hip", "always together, inseparable"], ["get into scrapes", "get into small troubles or mischief"], ["get told off", "be scolded for doing something wrong"], ["show off", "try to impress people by displaying your skills or possessions"], ["stick up for", "defend or support someone"], ["drift apart", "slowly become less close over time"], ["keep in touch", "stay in contact with someone"], ["bump into", "meet someone by chance"], ["pick up where we left off", "continue as if no time had passed"]], "grammar": [{"pattern": "Relative clause with who", "use": "noun (person) + who + verb", "example": "a boy who lived two doors down from us", "try": "My neighbour is a woman who ______."}, {"pattern": "Past perfect for earlier events", "use": "had + past participle: something before the main past event", "example": "Nobody had told me he’d been invited", "try": "Nobody had told me that ______."}, {"pattern": "Negative inversion", "use": "Never + had + subject + past participle: strong emphasis", "example": "Never had I hit it off with anyone so quickly", "try": "Never had I ______ so ______."}, {"pattern": "Would for past habits", "use": "would + base verb: repeated actions in the past", "example": "we’d play football until the light faded", "try": "Every summer we’d ______."}, {"pattern": "Cleft sentence with what", "use": "What + subject + verb + was + that-clause: highlights the main point", "example": "What I liked most about him was that he never showed off", "try": "What I admired most about her was that ______."}, {"pattern": "Real conditional about the future", "use": "If + past simple, I’m sure + would: an imagined situation", "example": "if I bumped into him tomorrow, I’m sure we’d pick up where we left off", "try": "If I met her tomorrow, I’m sure we’d ______."}]}}, "part3": {"intro": "We’ve been talking about a friend from your childhood, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Childhood friend", "title": "Childhood friend", "questions": [{"q": "Do people usually keep in touch with their childhood friends?", "model": {"answer": "Not as often as they mean to, I’d say. Life pulls people in different directions: one moves abroad, another gets married, and the friendship fades away without anyone deciding to end it. The ones that last usually involve a deliberate effort, like a yearly reunion. If people don’t make a real effort, they lose touch and only catch up when they happen to be in the same city.", "phrases": [["pull people in different directions", "give people different paths and priorities"], ["fade away", "slowly disappear"], ["make an effort", "try hard to do something"], ["lose touch", "stop communicating with someone"], ["catch up", "exchange news after time apart"]], "grammar": [{"pattern": "Relative clause with that", "use": "the ones that + verb: identifies which items", "example": "The ones that last usually involve a deliberate effort", "try": "The friendships that ______ are the ones that ______."}, {"pattern": "without + subject + -ing", "use": "without + person + -ing: something happening unnoticed", "example": "without anyone deciding to end it", "try": "It ended without anyone ______."}]}}, {"q": "What is the difference between having older friends and having younger friends?", "model": {"answer": "There’s a real contrast. Older friends have usually been through what you’re facing, so they can steer you in the right direction and share their experience. With younger friends, it’s you who sets the example, which can bring out a more patient, protective side of you. Not only do they keep you up to date with new trends, but they also remind you not to take life too seriously.", "phrases": [["go through", "experience something difficult or important"], ["steer someone in the right direction", "guide them towards a good choice"], ["set an example", "behave in a way others will copy"], ["bring out", "make a quality appear"], ["keep (someone) up to date", "give them the latest information"]], "grammar": [{"pattern": "Cleft sentence with it", "use": "it’s + person + who + verb: emphasises who", "example": "it’s you who sets the example", "try": "It’s my sister who ______."}, {"pattern": "Not only … but also …", "use": "Not only + auxiliary + subject … but also: adds a second point with emphasis", "example": "Not only do they keep you up to date with new trends, but they also remind you", "try": "Not only do they ______, but they also ______."}]}}, {"q": "How has technology changed the way people keep up their friendships?", "model": {"answer": "It has made friendships easier to maintain, though arguably shallower. A voice message takes seconds, so you can stay in the loop with a friend abroad. The flip side is that a like on a photo can feel like keeping in touch when it isn’t. Had it not been for messaging apps, I’d have lost contact with half my school friends, but they’re no substitute for a proper conversation.", "phrases": [["stay in the loop", "keep informed about what is happening"], ["the flip side", "the negative or opposite aspect"], ["keep in touch", "stay in contact"], ["lose contact with", "stop being in communication with"], ["no substitute for", "not able to replace"]], "grammar": [{"pattern": "Inverted third conditional", "use": "Had + subject + (not) + past participle, would have + past participle", "example": "Had it not been for messaging apps, I’d have lost contact with half my school friends", "try": "Had it not been for ______, I’d have ______."}, {"pattern": "Concession with though", "use": "main clause, though + adverb/adjective: a reservation", "example": "though arguably shallower", "try": "It’s much faster, though arguably ______."}]}}, {"q": "Do you think online communication will ever replace face-to-face meetings?", "model": {"answer": "Not entirely, in my view. Video calls are fine for routine meetings, and they save time and money. But so much of communication is body language, and you can’t pick up on a pause, a glance or a hug through a screen. The more we rely on screens, the more I suspect people will treasure quality time in person, as something special rather than the default.", "phrases": [["save time and money", "reduce cost and effort"], ["body language", "communication through posture and gestures"], ["pick up on", "notice something subtle"], ["rely on", "depend on"], ["quality time", "time spent giving someone your full attention"]], "grammar": [{"pattern": "The more … the more …", "use": "the more + clause, the more + clause: two things increasing together", "example": "The more we rely on screens, the more I suspect people will treasure quality time", "try": "The more people ______, the more ______."}, {"pattern": "so much of + noun", "use": "so much of + uncountable noun: a very large part", "example": "so much of communication is body language", "try": "So much of learning is ______."}]}}, {"q": "Is it important for children to have close friends?", "model": {"answer": "Absolutely, because friendships are where children learn the ropes of getting along with others. They practise sharing, compromising and handling arguments, which no textbook can teach. A close friend also gives a child someone to confide in when things go wrong at school. Children who lack that support tend to feel left out, and that can knock their confidence well into adulthood.", "phrases": [["learn the ropes", "learn how something works"], ["compromise", "accept less than you wanted to reach agreement"], ["confide in", "tell someone your secrets or worries"], ["feel left out", "feel excluded from a group"], ["knock someone’s confidence", "reduce their self-belief"]], "grammar": [{"pattern": "Non-defining relative clause with which", "use": ", which + subject + verb: adds extra comment", "example": "which no textbook can teach", "try": "They practise sharing, which ______."}, {"pattern": "tend to + base verb", "use": "tend to + verb: describes a general tendency", "example": "Children who lack that support tend to feel left out", "try": "People who ______ tend to ______."}]}}, {"q": "What can parents do to help shy children make friends?", "model": {"answer": "If I were a parent of a shy child, I wouldn’t push them into big groups. Instead, I’d arrange a playdate with just one classmate, so they can open up at their own pace. It also helps to praise small steps, such as saying hello to a neighbour, rather than putting them on the spot. Parents who lead by example find that their child comes out of their shell.", "phrases": [["arrange a playdate", "organise a time for children to play together"], ["open up", "start to talk freely about yourself"], ["put someone on the spot", "force them to respond in an awkward moment"], ["lead by example", "show the right behaviour through your own actions"], ["come out of your shell", "become more confident and sociable"]], "grammar": [{"pattern": "Second conditional", "use": "If + subject + were/past simple, would + base verb", "example": "If I were a parent of a shy child, I wouldn’t push them into big groups", "try": "If I were ______, I’d ______."}, {"pattern": "rather than + -ing", "use": "rather than + gerund: contrasts two actions", "example": "rather than putting them on the spot", "try": "Praise effort rather than ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000008', 1008, 'Topic 8', 'Plan you had to change', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 8, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a plan you had to change", "bullets": ["what the plan was", "why you had to change it", "what the new plan was", "how you felt about the change"], "explain": "", "notes": ["What", "Why", "New Plan", "Feelings"], "rounding": {"q": "Are you better at adapting to changes of plan these days?", "model": {"answer": "Definitely. I’ve learnt to keep a backup in mind, so a change of plan doesn’t throw me off the way it used to. I’d say I’ve become a lot more relaxed about it.", "phrases": [], "grammar": []}}, "model": {"answer": "One summer I’ll never forget is the one when my plans fell through. After my second-year exams, two classmates and I had set our hearts on a two-week trip to Istanbul. We’d been saving for months, and I had even drawn up a day-by-day itinerary, complete with the bakeries I wanted to try. Then, ten days before departure, my grandfather had a fall and ended up in hospital. He wasn’t in danger, but he needed someone with him, and my parents were both tied up at work. There was no question of my leaving. Had I gone, I would have spent the whole trip worrying, so I called it off, and we lost a fair part of the money on the tickets. As it turned out, the new plan was far simpler. I moved into my grandparents’ house for three weeks, cooking lunch, doing the shopping and keeping him company. When he was well enough, we took short drives to nearby villages, which he used to visit as a young man. I also made the most of the quiet evenings to read, catching up on books I’d been putting off for ages. I won’t pretend I wasn’t gutted at first. I was in a bad mood for a couple of days, especially when my friends posted photos from the Grand Bazaar. But what struck me was how much I enjoyed my grandfather’s stories, many of which I’d never heard. Looking back, it was a blessing in disguise. It taught me that a plan is only a starting point, and that going with the flow sometimes leads somewhere more meaningful than the original idea.", "sections": [{"label": "What", "text": "One summer I’ll never forget is the one when my plans fell through. After my second-year exams, two classmates and I had set our hearts on a two-week trip to Istanbul. We’d been saving for months, and I had even drawn up a day-by-day itinerary, complete with the bakeries I wanted to try."}, {"label": "Why", "text": "Then, ten days before departure, my grandfather had a fall and ended up in hospital. He wasn’t in danger, but he needed someone with him, and my parents were both tied up at work. There was no question of my leaving. Had I gone, I would have spent the whole trip worrying, so I called it off, and we lost a fair part of the money on the tickets."}, {"label": "New Plan", "text": "As it turned out, the new plan was far simpler. I moved into my grandparents’ house for three weeks, cooking lunch, doing the shopping and keeping him company. When he was well enough, we took short drives to nearby villages, which he used to visit as a young man. I also made the most of the quiet evenings to read, catching up on books I’d been putting off for ages."}, {"label": "Feelings", "text": "I won’t pretend I wasn’t gutted at first. I was in a bad mood for a couple of days, especially when my friends posted photos from the Grand Bazaar. But what struck me was how much I enjoyed my grandfather’s stories, many of which I’d never heard. Looking back, it was a blessing in disguise."}, {"label": "Reflection", "text": "It taught me that a plan is only a starting point, and that going with the flow sometimes leads somewhere more meaningful than the original idea."}], "phrases": [["fall through", "fail to happen"], ["set your heart on", "want something very much"], ["draw up (a plan)", "prepare in writing"], ["tied up", "very busy"], ["call off", "cancel"], ["keep (someone) company", "stay with someone so they are not alone"], ["make the most of", "use an opportunity as well as possible"], ["catch up on", "do something you have not had time for"], ["put off", "delay"], ["gutted", "extremely disappointed (informal)"], ["a blessing in disguise", "something that seems bad but turns out good"], ["go with the flow", "accept events and adapt calmly"]], "grammar": [{"pattern": "Past perfect continuous", "use": "had been + -ing: an activity continuing up to a past moment", "example": "We’d been saving for months", "try": "We’d been ______ for weeks."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, would have + past participle", "example": "Had I gone, I would have spent the whole trip worrying", "try": "Had I ______, I would have ______."}, {"pattern": "No question of + -ing There was no question of + possessive +", "use": "-ing: it was impossible", "example": "There was no question of my leaving", "try": "There was no question of my ______."}, {"pattern": "Relative clause with which", "use": "place + , which + clause: extra information", "example": "nearby villages, which he used to visit as a young man", "try": "..., which I used to ______."}, {"pattern": "Cleft sentence with what", "use": "What struck me was + clause", "example": "what struck me was how much I enjoyed my grandfather’s stories", "try": "What struck me was how ______."}, {"pattern": "many of which", "use": "many of which + subject + verb: quantifier + relative", "example": "many of which I’d never heard", "try": "He told stories, many of which ______."}]}}, "part3": {"intro": "We’ve been talking about a plan you had to change, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Plan you had to change", "title": "Plan you had to change", "questions": [{"q": "Do older people change their plans more often than younger people?", "model": {"answer": "Not really; if anything, it’s the other way round. Younger people tend to be more spontaneous, so their plans change at the last minute because something better comes up. Older people have fixed routines and responsibilities, so they stick to what they’ve arranged. Still, when they do change plans, it’s usually for health or family reasons, which are much harder to plan around.", "phrases": [["the other way round", "the opposite"], ["at the last minute", "very close to the deadline"], ["fixed routine", "a regular pattern that rarely changes"], ["stick to", "keep following"], ["plan around", "arrange things allowing for something"]], "grammar": [{"pattern": "If anything", "use": "if anything + clause: suggests the opposite is truer", "example": "if anything, it’s the other way round", "try": "He isn’t lazy; if anything, ______."}, {"pattern": "Sentential which", "use": "clause, which + be + comparative: comments on the whole clause", "example": "usually for health or family reasons, which are much harder to plan around", "try": "People fall ill, which is ______."}]}}, {"q": "What are the common reasons why people have to change their plans?", "model": {"answer": "Money and health top the list, I’d say. A sudden illness or an unexpected bill can derail even a carefully made plan. Bad weather can ruin outdoor plans too. Work is another big one, since a deadline or a last-minute meeting can eat into a free weekend. Sometimes people simply change their minds because their priorities have shifted, which is perfectly natural.", "phrases": [["top the list", "be the most common or important"], ["derail", "ruin or disrupt"], ["last-minute", "happening very late"], ["eat into", "use up part of something"], ["change your mind", "decide differently"]], "grammar": [{"pattern": "Present perfect for change", "use": "have + past participle: a change connected to now", "example": "because their priorities have shifted", "try": "People’s tastes have ______."}, {"pattern": "Modal can for possibility", "use": "can + base verb: something that sometimes happens", "example": "A sudden illness or an unexpected bill can derail even a carefully made plan", "try": "A traffic jam can ______."}]}}, {"q": "How would you tell a friend that you had to change your plans?", "model": {"answer": "I’d call rather than text, particularly if it’s something they were looking forward to. I’d give them as much notice as possible and explain the reason briefly, without making excuses. Then I’d suggest a new date: ‘Could we reschedule for next weekend?’ A message can come across as careless, whereas a phone call shows I genuinely value their time, and I’d make it up to them with coffee.", "phrases": [["give notice", "warn someone in advance"], ["make excuses", "give false or weak reasons"], ["reschedule", "arrange for a new time"], ["come across as", "seem to be"], ["make it up to someone", "do something to compensate"]], "grammar": [{"pattern": "rather than", "use": "I’d + verb + rather than + verb: preference", "example": "I’d call rather than text", "try": "I’d visit rather than ______."}, {"pattern": "whereas for contrast", "use": "A, whereas B", "example": "whereas a phone call shows I genuinely value their time", "try": "A text is quick, whereas ______."}]}}, {"q": "How has technology helped people to make plans?", "model": {"answer": "Enormously. You can compare prices and book a flight or a table in minutes, and shared calendars mean nobody has to chase people up to pin down a date. Live traffic updates also help you allow for delays. The downside is that the easier it is to cancel, the less seriously people take a commitment, so plans fall through more casually than they used to.", "phrases": [["compare prices", "check different costs before buying"], ["chase (people) up", "remind people to reply or act"], ["pin down (a date)", "fix a decision exactly"], ["allow for", "include extra time or money for"], ["fall through", "fail to happen"]], "grammar": [{"pattern": "The + comparative, the +", "use": "comparative the easier … the less …", "example": "the easier it is to cancel, the less seriously people take a commitment", "try": "The easier it is to ______, the more ______."}, {"pattern": "nobody has to", "use": "nobody has to + verb: no one is obliged", "example": "nobody has to chase people up", "try": "Nobody has to ______ any more."}]}}, {"q": "Why do some parents still plan everything for their children?", "model": {"answer": "Mostly out of anxiety. Parents who worry about their children’s future want to leave nothing to chance, so they pick the school, the tutors and even the university. There’s also peer pressure: if the neighbours’ kids are doing extra classes, they feel they must keep up. Children raised this way may struggle to make decisions when they finally have to stand on their own two feet.", "phrases": [["leave nothing to chance", "control every detail"], ["peer pressure", "influence from people in the same group"], ["keep up", "stay at the same level as others"], ["struggle to", "find it difficult to"], ["stand on your own two feet", "be independent"]], "grammar": [{"pattern": "Reduced relative clause", "use": "noun + past participle: children (who are) raised this way", "example": "Children raised this way may struggle", "try": "People trained this way may ______."}, {"pattern": "First conditional", "use": "if + present continuous, subject + must", "example": "if the neighbours’ kids are doing extra classes, they feel they must keep up", "try": "If other parents are ______, they feel ______."}]}}, {"q": "Is it better to plan everything carefully or to stay flexible?", "model": {"answer": "A bit of both, really. For anything important, such as an exam or a trip abroad, thorough planning pays off. But life rarely goes according to plan, so the key is to plan the essentials and leave the details open. People who are too rigid get thrown when things change, whereas those who are too relaxed often miss out on opportunities.", "phrases": [["thorough planning", "careful and complete preparation"], ["pay off", "bring a good result"], ["go according to plan", "happen as expected"], ["get thrown", "be confused or upset by a surprise"], ["miss out on", "lose a chance to enjoy or gain something"]], "grammar": [{"pattern": "Cleft with the key is to", "use": "The key is to + base verb", "example": "the key is to plan the essentials and leave the details open", "try": "The key is to ______."}, {"pattern": "those who", "use": "those who + verb: refers to a group of people", "example": "those who are too relaxed often miss out on opportunities", "try": "Those who ______ often ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000009', 1009, 'Topic 9', 'Food for special occasions', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 9, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a type of food that people eat at special events", "bullets": ["what the food is", "why people eat it at special events", "how people prepare this food", "why you like this food so much"], "explain": "", "notes": ["What", "Why", "How", "Why I Like It"], "rounding": {"q": "Is plov made differently in different parts of the country?", "model": {"answer": "Yes, every region has its own twist. Some add chickpeas or raisins, others prefer yellow carrots. Honestly, everyone thinks their local version is the best.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one dish, it would be plov, or osh, as we call it. No wedding, memorial or big family celebration in Uzbekistan feels complete without it, and the smell alone is enough to make your mouth water. People serve it because it’s bound up with hospitality. Plov is meant to bring people together: when a family hosts one, neighbours and relatives turn up without a formal invitation, and nobody would dream of refusing a plate. It’s also practical, as a single enormous pot can feed a crowd of a hundred. The preparation is a real labour of love. The cook, who is nearly always a man, heats oil in a cast-iron cauldron called a kazan, fries the onions until golden, then adds the lamb, the carrots and finally the rice, and leaves it all to simmer over a low fire. Last winter I watched my uncle keep an eye on one for hours, barely saying a word. Everything depends on timing, which is why only experienced cooks are trusted with it. The recipes themselves are passed down from father to son. What I love most is the sense of occasion. Not only is it delicious, with tender meat and rice that’s fluffy rather than greasy, but it also takes me back to my childhood, when we’d sit around one big dish in my grandmother’s yard. Whenever I eat plov abroad, it never quite hits the spot, because it isn’t just the food I’m missing. For me, it’s a taste of home, and I think that’s why it stands the test of time.", "sections": [{"label": "What", "text": "If I had to pick one dish, it would be plov, or osh, as we call it. No wedding, memorial or big family celebration in Uzbekistan feels complete without it, and the smell alone is enough to make your mouth water."}, {"label": "Why", "text": "People serve it because it’s bound up with hospitality. Plov is meant to bring people together: when a family hosts one, neighbours and relatives turn up without a formal invitation, and nobody would dream of refusing a plate. It’s also practical, as a single enormous pot can feed a crowd of a hundred."}, {"label": "How", "text": "The preparation is a real labour of love. The cook, who is nearly always a man, heats oil in a cast-iron cauldron called a kazan, fries the onions until golden, then adds the lamb, the carrots and finally the rice, and leaves it all to simmer over a low fire. Last winter I watched my uncle keep an eye on one for hours, barely saying a word. Everything depends on timing, which is why only experienced cooks are trusted with it. The recipes themselves are passed down from father to son."}, {"label": "Why I Like It", "text": "What I love most is the sense of occasion. Not only is it delicious, with tender meat and rice that’s fluffy rather than greasy, but it also takes me back to my childhood, when we’d sit around one big dish in my grandmother’s yard. Whenever I eat plov abroad, it never quite hits the spot, because it isn’t just the food I’m missing."}, {"label": "Reflection", "text": "For me, it’s a taste of home, and I think that’s why it stands the test of time."}], "phrases": [["make your mouth water", "look or smell so good that you want to eat it"], ["bound up with", "closely connected with"], ["bring people together", "unite people"], ["turn up", "arrive, often unexpectedly"], ["feed a crowd", "provide enough food for many people"], ["a labour of love", "hard work done because you care"], ["keep an eye on", "watch carefully"], ["pass down", "give knowledge or objects from one generation to the next"], ["a sense of occasion", "a feeling that an event is special"], ["take me back", "remind me strongly of the past"], ["hit the spot", "satisfy exactly what you wanted"], ["stand the test of time", "remain popular or valuable for a long time"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If I had to pick one dish, it would be plov", "try": "If I had to choose a place, it would be ______."}, {"pattern": "Subject-less relative clause", "use": "who + verb: extra information about a person", "example": "The cook, who is nearly always a man, heats oil", "try": "My uncle, who ______, always ______."}, {"pattern": "Passive with which is why", "use": "..., which is why + passive", "example": "which is why only experienced cooks are trusted with it", "try": "..., which is why ______ are trusted with it."}, {"pattern": "Not only … but also", "use": "Not only is it + adjective, but it also + verb", "example": "Not only is it delicious, with tender meat and rice that’s fluffy rather than greasy, but it also takes me back", "try": "Not only is it ______, but it also ______."}, {"pattern": "Would for past habit", "use": "when we’d + base verb", "example": "when we’d sit around one big dish", "try": "When we were small we’d ______."}, {"pattern": "Whenever + present", "use": "Whenever + present simple, present simple: a repeated pattern", "example": "Whenever I eat plov abroad, it never quite hits the spot", "try": "Whenever I ______, it ______."}]}}, "part3": {"intro": "We’ve been talking about a type of food that people eat at special events, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Food for special occasions", "title": "Food for special occasions", "questions": [{"q": "Why are traditional dishes important at celebrations?", "model": {"answer": "Because food carries memory. A dish that’s passed down through generations links today’s celebration to everything before it, so eating it feels like taking part in a ritual rather than just having a meal. It also gives the occasion a sense of identity: a wedding without the usual dishes simply wouldn’t feel right. Besides, cooking them together strengthens family bonds, which matters more than the food itself.", "phrases": [["pass down", "give from one generation to the next"], ["take part in", "participate in"], ["a sense of identity", "a feeling of who you are or belong to"], ["feel right", "seem correct or proper"], ["strengthen family bonds", "make family relationships closer"]], "grammar": [{"pattern": "Defining relative clause", "use": "noun + that + passive verb", "example": "A dish that’s passed down through generations", "try": "A recipe that’s ______ through generations ______."}, {"pattern": "Second conditional with without", "use": "without + noun … would(n’t)", "example": "a wedding without the usual dishes simply wouldn’t feel right", "try": "A birthday without ______ wouldn’t ______."}]}}, {"q": "Do you think the food people eat today is better than it was in the past?", "model": {"answer": "In some respects, yes. We have far more variety, access to fresh produce all year round, and food safety has improved considerably. But much of what we eat is heavily processed, packed with sugar and salt. My grandmother’s cooking, made from scratch with seasonal ingredients, was simpler but healthier. So it’s better in terms of choice, but not necessarily in terms of nutrition.", "phrases": [["access to", "the ability to get or use"], ["improve considerably", "get much better"], ["heavily processed", "changed a lot by factory methods"], ["from scratch", "using basic ingredients, not ready-made products"], ["in terms of", "regarding"]], "grammar": [{"pattern": "Participle phrase", "use": "noun, + past participle phrase, + verb", "example": "My grandmother’s cooking, made from scratch with seasonal ingredients, was simpler but healthier", "try": "My father’s car, ______ in 1990, was ______."}, {"pattern": "not necessarily", "use": "not necessarily + noun: not always true", "example": "but not necessarily in terms of nutrition", "try": "More choice isn’t necessarily ______."}]}}, {"q": "In what ways has the food people eat in your country changed over the last few decades?", "model": {"answer": "Diets have become noticeably more international. Pizza, sushi and burgers were once rare, yet now every city has them. People eat on the go more often and cook less than they used to, so traditional dishes are reserved for weekends and celebrations. Meanwhile, many younger people have become more health-conscious and are cutting down on sugar and fried food. Busy schedules are largely to blame.", "phrases": [["eat on the go", "eat while travelling or busy"], ["reserved for", "kept for a particular use or occasion"], ["health-conscious", "caring about staying healthy"], ["cut down on", "reduce"], ["be to blame", "be responsible for a problem"]], "grammar": [{"pattern": "Present perfect for change", "use": "have become + comparative adjective", "example": "Diets have become noticeably more international", "try": "Lifestyles have become ______."}, {"pattern": "used to for past contrast", "use": "than they used to", "example": "cook less than they used to", "try": "People read ______ than they used to."}]}}, {"q": "Do families still prepare traditional dishes themselves, or do they mostly buy them?", "model": {"answer": "It depends on the dish and the occasion. For everyday meals, most families still do the cooking themselves, but for a big wedding they often hire a caterer, simply because the guest list is enormous. That said, dishes with real emotional weight, like plov, are usually prepared in-house, even if only because a relative takes pride in it. And younger people do buy ready-made pastries.", "phrases": [["do the cooking", "prepare food"], ["hire a caterer", "pay a company to provide the food"], ["emotional weight", "importance because of feelings"], ["take pride in", "feel proud of"], ["ready-made", "already prepared"]], "grammar": [{"pattern": "Passive with modal adverb", "use": "noun phrase + are usually + past participle", "example": "dishes with real emotional weight, like plov, are usually prepared in-house", "try": "Dishes like ______ are usually ______."}, {"pattern": "even if only because", "use": "even if only because + reason: a minimal reason", "example": "even if only because a relative takes pride in it", "try": "..., even if only because ______."}]}}, {"q": "What are the advantages and disadvantages of eating out on special occasions?", "model": {"answer": "The obvious advantage is convenience: nobody has to slave over a hot stove, so the host can actually enjoy the evening. Restaurants also cater for large groups and special diets. On the downside, it can cost a fortune, and a restaurant rarely has the warmth of a home. If the celebration is held somewhere busy, you may feel rushed, as the table has to be freed for the next booking.", "phrases": [["slave over a hot stove", "work hard cooking"], ["cater for", "provide what is needed for"], ["cost a fortune", "be very expensive"], ["feel rushed", "feel pressured to hurry"], ["on the downside", "as a disadvantage"]], "grammar": [{"pattern": "Result clause with so", "use": "clause, so + subject + can", "example": "so the host can actually enjoy the evening", "try": "Nobody cooks, so the host can ______."}, {"pattern": "Passive of necessity", "use": "has to be + past participle", "example": "the table has to be freed for the next booking", "try": "The room has to be ______ by six."}]}}, {"q": "Do you think fast food has changed people’s eating habits?", "model": {"answer": "Without a doubt, particularly among the young. Fast food has made it normal to grab a bite in ten minutes, so family meals are being replaced by quick snacks in front of a screen. Consequently, portion sizes have grown and cooking skills are dying out. That’s not to say it’s all bad; it’s affordable and handy when you’re pressed for time.", "phrases": [["grab a bite", "eat something quickly"], ["quick snack", "a small, fast meal"], ["portion size", "the amount of food served"], ["die out", "gradually disappear"], ["pressed for time", "in a hurry"]], "grammar": [{"pattern": "Present continuous passive", "use": "are being + past participle: a change in progress", "example": "family meals are being replaced by quick snacks", "try": "Handwriting is being replaced by ______."}, {"pattern": "That’s not to say", "use": "That’s not to say + clause: a concession", "example": "That’s not to say it’s all bad", "try": "That’s not to say ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000010', 1010, 'Topic 10', 'Live sports event you watched', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 10, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a time when you watched a live sports event and liked it", "bullets": ["what the sports event was", "where and when the sports event took place", "why you watched it live", "why you liked it live"], "explain": "", "notes": ["What", "Where & When", "Why Live", "Why I Liked It"], "rounding": {"q": "Would you like to attend a major tournament in person one day?", "model": {"answer": "Definitely. I’d love to see a World Cup match in the stadium, even from the cheapest seats. I suspect the atmosphere would be unlike anything I’ve experienced.", "phrases": [], "grammar": []}}, "model": {"answer": "One occasion I’ll never forget is the first time I watched a football match live: a league game between Pakhtakor and Bunyodkor. I’d followed derbies on TV for years, but this was the real thing. It took place at the Pakhtakor Central Stadium in Tashkent on a chilly evening last October, and the floodlights made the pitch look almost unreal. I hadn’t been planning to go at all. Then my cousin Jahongir, who’s a season-ticket holder, phoned me an hour before kick-off to say a friend had dropped out. ‘Come on, you’ve been going on about this derby all week,’ he said. I jumped at the chance, and we only just made it to our seats as the teams walked out. What I enjoyed most was the atmosphere. Fans were chanting non-stop, there was a sea of scarves in the stands, and the noise was almost deafening. When Pakhtakor scored an equaliser in the eightieth minute, the whole stadium erupted, and complete strangers were hugging each other. I had goosebumps. On TV you see the goals, but you miss the buzz, the tension you can almost feel in the air, and the little things, like the smell of roasted sunflower seeds. The last ten minutes were nail-biting, and I was on the edge of my seat until the final whistle. By the end, I’d lost my voice, and it’s hard to put into words how happy I was. Looking back, what I took from that night is that sport is about sharing the moment. Had I stayed at home, I’d have seen the same goals, but I’d have missed the feeling of belonging.", "sections": [{"label": "What", "text": "One occasion I’ll never forget is the first time I watched a football match live: a league game between Pakhtakor and Bunyodkor. I’d followed derbies on TV for years, but this was the real thing."}, {"label": "Where & When", "text": "It took place at the Pakhtakor Central Stadium in Tashkent on a chilly evening last October, and the floodlights made the pitch look almost unreal."}, {"label": "Why Live", "text": "I hadn’t been planning to go at all. Then my cousin Jahongir, who’s a season-ticket holder, phoned me an hour before kick-off to say a friend had dropped out. ‘Come on, you’ve been going on about this derby all week,’ he said. I jumped at the chance, and we only just made it to our seats as the teams walked out."}, {"label": "Why I Liked It", "text": "What I enjoyed most was the atmosphere. Fans were chanting non-stop, there was a sea of scarves in the stands, and the noise was almost deafening. When Pakhtakor scored an equaliser in the eightieth minute, the whole stadium erupted, and complete strangers were hugging each other. I had goosebumps. On TV you see the goals, but you miss the buzz, the tension you can almost feel in the air, and the little things, like the smell of roasted sunflower seeds. The last ten minutes were nail-biting, and I was on the edge of my seat until the final whistle. By the end, I’d lost my voice, and it’s hard to put into words how happy I was."}, {"label": "Reflection", "text": "Looking back, what I took from that night is that sport is about sharing the moment. Had I stayed at home, I’d have seen the same goals, but I’d have missed the feeling of belonging."}], "phrases": [["drop out", "withdraw from something you planned to do"], ["go on about", "talk about something repeatedly"], ["jump at the chance", "accept an opportunity eagerly"], ["make it to", "succeed in arriving at"], ["a sea of", "a very large number of, filling a space"], ["erupt", "suddenly make a loud noise or burst into excitement"], ["goosebumps", "small bumps on the skin from strong emotion"], ["buzz", "a feeling of excitement in a place"], ["nail-biting", "extremely tense and exciting"], ["on the edge of my seat", "very excited and waiting to see what happens"], ["lose my voice", "be unable to speak because of shouting"], ["hard to put into words", "difficult to describe"], ["share the moment", "enjoy an experience together with others"]], "grammar": [{"pattern": "Past perfect for earlier background", "use": "had + past participle: what happened before the story", "example": "I’d followed derbies on TV for years", "try": "I’d ______ for years before I ______."}, {"pattern": "Past perfect continuous (negative)", "use": "hadn’t been + -ing: something not intended before", "example": "I hadn’t been planning to go at all", "try": "I hadn’t been planning to ______."}, {"pattern": "Non-defining relative clause", "use": "who + verb: extra information about a person", "example": "my cousin Jahongir, who’s a season-ticket holder", "try": "My friend ______, who ______, called me."}, {"pattern": "Cleft sentence with what", "use": "What + subject + verb + was", "example": "What I enjoyed most was the atmosphere", "try": "What I enjoyed most was ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, would have + past participle", "example": "Had I stayed at home, I’d have seen the same goals", "try": "Had I ______, I’d have ______."}, {"pattern": "Present perfect continuous", "use": "have been + -ing: an action up to now", "example": "you’ve been going on about this derby all week", "try": "You’ve been ______ all week."}]}}, "part3": {"intro": "We’ve been talking about a time when you watched a live sports event and liked it, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Live sports event you watched", "title": "Live sports event you watched", "questions": [{"q": "What is the difference between watching a match at home and watching it in a stadium?", "model": {"answer": "The biggest difference is atmosphere. At home you get replays, commentary and a comfortable sofa, but in a stadium you’re part of the crowd, soaking up the energy and chanting along with thousands of strangers. At home, however, you can follow the action more closely and pause for a snack. So it comes down to whether you want to feel the occasion or simply keep track of the result.", "phrases": [["soak up", "absorb, enjoy fully"], ["chant along", "sing or shout together with others"], ["follow the action", "watch what is happening closely"], ["come down to", "depend mainly on"], ["keep track of", "stay aware of"]], "grammar": [{"pattern": "Participle clause", "use": "verb + -ing: two actions at the same time", "example": "you’re part of the crowd, soaking up the energy", "try": "You’re part of the crowd, ______ the ______."}, {"pattern": "whether … or …", "use": "whether + clause + or + clause", "example": "whether you want to feel the occasion or simply keep track of the result", "try": "It depends on whether you want to ______ or ______."}]}}, {"q": "What are the advantages of watching sports online?", "model": {"answer": "Flexibility is the main one. You can stream a match on your phone during a commute, catch up on highlights afterwards, or choose between several camera angles and commentators. It’s also far cheaper than a stadium ticket, not to mention the travel. Fans abroad can follow their national team live, too. That said, a weak connection can freeze the screen at the decisive moment, which is infuriating.", "phrases": [["stream", "watch live over the internet"], ["catch up on", "watch something you missed"], ["not to mention", "and also (adding a further point)"], ["the decisive moment", "the point that decides the result"], ["infuriating", "extremely annoying"]], "grammar": [{"pattern": "Comparative with far", "use": "far + comparative + than", "example": "It’s also far cheaper than a stadium ticket", "try": "It’s far ______ than ______."}, {"pattern": "Sentential which", "use": "..., which is + adjective: comment on the whole clause", "example": "a weak connection can freeze the screen at the decisive moment, which is infuriating", "try": "The Wi-Fi cut out, which was ______."}]}}, {"q": "Why do some people not enjoy watching major sports events such as the Olympic Games?", "model": {"answer": "For some, it simply comes down to personal taste: they find sport dull and would rather spend their time on something else. Others feel the Olympics have become overly commercial, full of adverts and hype. And since events are often broadcast at odd hours because of time differences, watching can mean losing sleep. Had they played sport as children, I suspect more people would be hooked.", "phrases": [["come down to", "be mainly a question of"], ["overly commercial", "too focused on making money"], ["hype", "excessive publicity"], ["odd hours", "unusual times, such as very late at night"], ["be hooked", "be addicted or very interested"]], "grammar": [{"pattern": "Passive voice", "use": "are + often + past participle", "example": "since events are often broadcast at odd hours", "try": "Matches are often ______ late at night."}, {"pattern": "Inverted conditional", "use": "Had + subject + past participle, … would", "example": "Had they played sport as children, I suspect more people would be hooked", "try": "Had they ______, more people would ______."}]}}, {"q": "Do you think professional athletes are paid too much?", "model": {"answer": "In the case of top footballers, perhaps, but it’s more complicated than that. Clubs bring in huge sums from tickets, sponsorship and merchandise, so wages simply reflect market value. Their careers are also short and can end through injury. What bothers me is the gap between them and professionals such as nurses or teachers, who are paid far less for work with far greater social impact.", "phrases": [["bring in", "earn or generate money"], ["market value", "what the market will pay"], ["the gap", "the large difference"], ["social impact", "effect on society"], ["reflect", "show or correspond to"]], "grammar": [{"pattern": "Cleft sentence with what", "use": "What + verb + me + is + noun", "example": "What bothers me is the gap between them and professionals", "try": "What bothers me is ______."}, {"pattern": "Relative clause with who + passive", "use": "who + are + past participle", "example": "who are paid far less for work with far greater social impact", "try": "Nurses, who are ______, deserve ______."}]}}, {"q": "How do big sporting events benefit the city or country that hosts them?", "model": {"answer": "Mostly through investment and exposure. A city hosting a tournament usually upgrades its infrastructure, such as roads, metro lines and stadiums, which residents keep using long after the event. It also puts the city on the map, boosting tourism and bringing in revenue for hotels and restaurants. The caveat is that if the costs are poorly managed, the venues can become white elephants.", "phrases": [["exposure", "public attention"], ["upgrade infrastructure", "improve roads, transport and buildings"], ["put (a place) on the map", "make it widely known"], ["boost tourism", "increase the number of tourists"], ["white elephant", "an expensive thing that is no longer useful"]], "grammar": [{"pattern": "Non-defining relative clause", "use": "..., which + subject + verb", "example": "which residents keep using long after the event", "try": "new metro lines, which people ______."}, {"pattern": "Participle clause", "use": "verb + -ing: results", "example": "boosting tourism and bringing in revenue for hotels and restaurants", "try": "It attracts visitors, ______ local business."}]}}, {"q": "Do you think competition is good for children?", "model": {"answer": "In moderation, yes. Healthy competition teaches children to set goals, handle defeat gracefully and push themselves harder, as well as how to cooperate in a team. The problem arises when winning becomes everything: children who are constantly compared with others may burn out or lose confidence. Ideally, parents should praise effort rather than results, so that competition remains a source of motivation rather than pressure.", "phrases": [["set goals", "decide what you want to achieve"], ["handle defeat", "cope with losing"], ["push yourself", "make yourself try harder"], ["burn out", "become exhausted from too much pressure"], ["pressure", "stress caused by high expectations"]], "grammar": [{"pattern": "Reduced passive relative", "use": "children who are + past participle", "example": "children who are constantly compared with others may burn out", "try": "Children who are ______ may ______."}, {"pattern": "so that", "use": "so that + clause: purpose", "example": "so that competition remains a source of motivation", "try": "..., so that children ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000011', 1011, 'Topic 11', 'Place you’ve travelled to that you’d recommend', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 11, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a place you’ve travelled to that you’d recommend to others", "bullets": ["what place it was", "why you went there", "what you did there", "how you felt about it"], "explain": "", "notes": ["What", "Why I Went", "What I Did", "Feelings"], "rounding": {"q": "Would you like to go back there one day?", "model": {"answer": "Definitely. Next time I’d stay a few days longer and visit the smaller villages around it. I’d also take a friend who hasn’t been, just to see their reaction.", "phrases": [], "grammar": []}}, "model": {"answer": "If someone asked me where to go in Uzbekistan, I’d say Khiva without hesitation. It’s a small walled city in the far west of the country, in a region called Khorezm, and I went there two Aprils ago. The reason was a little embarrassing. I’d lived in Uzbekistan all my life, yet I’d never been beyond Samarkand and Bukhara. My father, who had visited Khiva as a student, kept raving about it, and when I finished my exams he said, ‘It’s high time you saw it for yourself.’ So we booked two train tickets and set off that same week. We checked into a small guesthouse inside the old walls, in a house that had been lovingly restored. Early each morning we wandered around the narrow lanes before the tour groups arrived, and one afternoon I climbed the Islam Khoja minaret, from which you can see the whole city stretching out below, rooftops the colour of sand. We also tried shivit oshi, green noodles served with meat, which I’d never tasted before, and I ended up haggling with a carpet seller who taught me to tell silk from cotton by touch. Honestly, the place took my breath away. In the evenings, with the light turning golden on the old walls, time seemed to slow down. Had I known how beautiful it was, I would have gone years earlier. What struck me was that, despite its fame, it still felt lived-in rather than like a museum, and it lived up to everything my father had promised. I’d recommend it to anyone who wants to get off the beaten track and see a more peaceful side of the country.", "sections": [{"label": "What", "text": "If someone asked me where to go in Uzbekistan, I’d say Khiva without hesitation. It’s a small walled city in the far west of the country, in a region called Khorezm, and I went there two Aprils ago."}, {"label": "Why I Went", "text": "The reason was a little embarrassing. I’d lived in Uzbekistan all my life, yet I’d never been beyond Samarkand and Bukhara. My father, who had visited Khiva as a student, kept raving about it, and when I finished my exams he said, ‘It’s high time you saw it for yourself.’ So we booked two train tickets and set off that same week."}, {"label": "What I Did", "text": "We checked into a small guesthouse inside the old walls, in a house that had been lovingly restored. Early each morning we wandered around the narrow lanes before the tour groups arrived, and one afternoon I climbed the Islam Khoja minaret, from which you can see the whole city stretching out below, rooftops the colour of sand. We also tried shivit oshi, green noodles served with meat, which I’d never tasted before, and I ended up haggling with a carpet seller who taught me to tell silk from cotton by touch."}, {"label": "Feelings", "text": "Honestly, the place took my breath away. In the evenings, with the light turning golden on the old walls, time seemed to slow down. Had I known how beautiful it was, I would have gone years earlier. What struck me was that, despite its fame, it still felt lived-in rather than like a museum, and it lived up to everything my father had promised."}, {"label": "Reflection", "text": "I’d recommend it to anyone who wants to get off the beaten track and see a more peaceful side of the country."}], "phrases": [["rave about", "talk about with great enthusiasm"], ["it’s high time", "it is already late for something to happen"], ["check into", "register at a hotel"], ["lovingly restored", "repaired with great care"], ["wander around", "walk with no fixed plan"], ["stretch out", "extend over a large area"], ["haggle", "bargain over a price"], ["take my breath away", "impress me deeply"], ["slow down", "become slower"], ["live up to", "be as good as expected"], ["get off the beaten track", "go to places few tourists visit"], ["set off", "start a journey"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If someone asked me where to go in Uzbekistan, I’d say Khiva without hesitation", "try": "If someone asked me where to eat, I’d ______."}, {"pattern": "Past perfect passive", "use": "had been + past participle", "example": "in a house that had been lovingly restored", "try": "..., a place that had been ______."}, {"pattern": "Relative clause with preposition", "use": "preposition + which", "example": "from which you can see the whole city", "try": "a tower from which you can ______."}, {"pattern": "Third conditional", "use": "Had + subject + past participle, would have + past participle", "example": "Had I known how beautiful it was, I would have gone years earlier", "try": "Had I known ______, I would have ______."}, {"pattern": "Cleft sentence with what", "use": "What struck me was that + clause", "example": "What struck me was that, despite its fame, it still felt lived-in", "try": "What struck me was that ______."}, {"pattern": "Contrast with yet", "use": "clause, yet + clause", "example": "I’d lived in Uzbekistan all my life, yet I’d never been beyond Samarkand and Bukhara", "try": "I’d ______ all my life, yet I’d never ______."}]}}, "part3": {"intro": "We’ve been talking about a place you’ve travelled to that you’d recommend to others, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Place you’ve travelled to that you’d recommend", "title": "Place you’ve travelled to that you’d recommend", "questions": [{"q": "What should people prepare before going on holiday?", "model": {"answer": "Documents come first: passport, visas and insurance, because forgetting any of them can ruin a trip before it starts. After that, it’s worth doing a bit of research on the weather, local customs and transport, and booking early in busy seasons. I’d also pack light and bring a small first-aid kit. A bit of foresight saves you far more trouble than it costs.", "phrases": [["ruin a trip", "spoil a holiday"], ["do some research", "look up information beforehand"], ["book early", "reserve before the busy period"], ["pack light", "take few belongings"], ["foresight", "the ability to think ahead"]], "grammar": [{"pattern": "Gerund as subject", "use": "-ing + verb: an action as the subject", "example": "forgetting any of them can ruin a trip", "try": "Losing your ______ can ______."}, {"pattern": "Comparative with than", "use": "far more + noun + than + clause", "example": "A bit of foresight saves you far more trouble than it costs", "try": "A little planning saves far more ______ than it ______."}]}}, {"q": "Where do people in your country usually go on holiday?", "model": {"answer": "It varies with the season and the budget. In summer, many families head to the mountains near Tashkent, such as Chimgan, or to Charvak lake to escape the heat, while others travel to Turkey or the UAE if they can afford it. Domestic tourism has been growing too, with Samarkand and Bukhara attracting younger Uzbeks who want to see their own heritage. Older people, by contrast, often visit relatives.", "phrases": [["head to", "go towards"], ["escape the heat", "get away from hot weather"], ["domestic tourism", "holidays within your own country"], ["by contrast", "in comparison"], ["heritage", "traditions and buildings from the past"]], "grammar": [{"pattern": "Present perfect continuous", "use": "has been + -ing", "example": "Domestic tourism has been growing too", "try": "Interest in ______ has been growing."}, {"pattern": "Participle clause", "use": "verb + -ing + object + who", "example": "attracting younger Uzbeks who want to see their own heritage", "try": "..., attracting visitors who want to ______."}]}}, {"q": "Is it better to plan a trip carefully or to be spontaneous?", "model": {"answer": "It depends on the trip. For a long journey abroad, careful planning is essential, because flights and hotels get expensive at the last minute, and a missed connection can be costly. But for a short weekend away, I enjoy being spontaneous, as some of my best memories came from unplanned detours. The ideal approach is to fix the basics and leave gaps for surprises.", "phrases": [["careful planning", "thorough preparation"], ["spontaneous", "done without planning"], ["unplanned detour", "an unexpected change of route"], ["fix the basics", "arrange the essential things"], ["the last minute", "the final moments before a deadline"]], "grammar": [{"pattern": "Because for reason", "use": "because + clause", "example": "because flights and hotels get expensive at the last minute", "try": "..., because tickets ______."}, {"pattern": "Gerund after enjoy", "use": "enjoy + -ing", "example": "I enjoy being spontaneous", "try": "I enjoy being ______."}]}}, {"q": "Do you think people rely too much on online reviews when choosing where to go?", "model": {"answer": "Yes, up to a point. Reviews are useful for spotting red flags, such as a dirty room or a rude host, but they can be misleading: some are fake, and others reflect personal taste rather than quality. What worries me is that everyone ends up at the same top-rated restaurant, while hidden gems go unnoticed. I take most reviews with a pinch of salt.", "phrases": [["spot red flags", "notice warning signs"], ["misleading", "giving a false impression"], ["hidden gem", "a wonderful place few people know"], ["take with a pinch of salt", "not trust completely"], ["end up", "finally be in a situation"]], "grammar": [{"pattern": "Cleft sentence with what", "use": "What + verb + me + is + that", "example": "What worries me is that everyone ends up at the same top-rated restaurant", "try": "What worries me is that ______."}, {"pattern": "while for contrast", "use": "..., while + clause", "example": "while hidden gems go unnoticed", "try": "Some places are crowded, while ______."}]}}, {"q": "How can tourists show respect for local people and their culture?", "model": {"answer": "The simplest way is to learn a few words of the local language, as a ‘thank you’ goes a long way. Tourists should also dress modestly at religious sites, ask permission before photographing people and follow customs such as removing shoes. The more effort you make, the warmer the welcome. Rather than haggling over every coin, remember that a small amount means far more to a seller than to you.", "phrases": [["learn a few words", "pick up some basic phrases"], ["go a long way", "have a big effect"], ["dress modestly", "wear covering, non-revealing clothes"], ["ask permission", "request approval"], ["follow customs", "behave according to local traditions"]], "grammar": [{"pattern": "The more … the …", "use": "the more + clause, the + comparative", "example": "The more effort you make, the warmer the welcome", "try": "The more you ______, the ______ the ______."}, {"pattern": "Rather than + -ing", "use": "Rather than + -ing, imperative", "example": "Rather than haggling over every coin, remember that", "try": "Rather than ______, try to ______."}]}}, {"q": "How are holidays today different from those of your grandparents’ generation?", "model": {"answer": "Travel is far more accessible now. My grandparents’ holidays, if they had any, meant a few quiet days at a relative’s house, whereas today people can book a flight abroad in minutes. We take shorter, more frequent breaks and document everything online. On the other hand, their trips were less rushed, more about rest than ticking off sights, and I envy how well they could unwind.", "phrases": [["book a flight", "reserve plane tickets"], ["document", "record, for example in photos"], ["less rushed", "calmer, with less hurry"], ["tick off sights", "visit famous places quickly, like items on a list"], ["unwind", "relax"]], "grammar": [{"pattern": "Whereas for contrast", "use": "A, whereas B", "example": "whereas today people can book a flight abroad in minutes", "try": "In the past people wrote letters, whereas today ______."}, {"pattern": "Conditional ellipsis", "use": "if + they had any", "example": "if they had any", "try": "..., if they had any."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000012', 1012, 'Topic 12', 'Important decision you made', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 12, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an important decision you made", "bullets": ["what the decision was", "how you made your decision", "what the results of the decision were", "why it was important"], "explain": "", "notes": ["What", "How I Decided", "Results", "Why It Mattered"], "rounding": {"q": "Do you ever wonder how your life would have turned out otherwise?", "model": {"answer": "Occasionally, yes. But I don’t dwell on it. I suspect I’d have been a perfectly decent doctor, just a less happy one.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about the decision to study Economics instead of medicine. It was the summer I finished school, and everyone around me assumed I’d become a doctor, as my mother and two of my uncles had. I spent about a month agonising over it. I made a list of pros and cons, talked it over with my older cousin, who’d studied abroad, and even spent a day shadowing a doctor at a clinic. What really decided it was a question from my chemistry teacher: ‘Would you still choose this if nobody were watching?’ That hit home. I realised I was choosing out of duty rather than interest, and that I’d always been drawn to numbers and the way money shapes people’s lives. Telling my parents was nerve-racking. My mother was upset for a few weeks, and I braced myself for constant disapproval. But as it turned out, she came round once she saw how engaged I was. Five years on, I’m close to graduating, and I’ve discovered that I love explaining difficult ideas to other people, which I’d never have imagined. It was important because it was the first time I took ownership of my own life. Had I simply gone along with expectations, I might have ended up stuck in a career I didn’t enjoy. Looking back, what I value most isn’t the outcome but the principle: it’s worth trusting your own judgement, even when it goes against the grain.", "sections": [{"label": "What", "text": "Let me tell you about the decision to study Economics instead of medicine. It was the summer I finished school, and everyone around me assumed I’d become a doctor, as my mother and two of my uncles had."}, {"label": "How I Decided", "text": "I spent about a month agonising over it. I made a list of pros and cons, talked it over with my older cousin, who’d studied abroad, and even spent a day shadowing a doctor at a clinic. What really decided it was a question from my chemistry teacher: ‘Would you still choose this if nobody were watching?’ That hit home. I realised I was choosing out of duty rather than interest, and that I’d always been drawn to numbers and the way money shapes people’s lives."}, {"label": "Results", "text": "Telling my parents was nerve-racking. My mother was upset for a few weeks, and I braced myself for constant disapproval. But as it turned out, she came round once she saw how engaged I was. Five years on, I’m close to graduating, and I’ve discovered that I love explaining difficult ideas to other people, which I’d never have imagined."}, {"label": "Why It Mattered", "text": "It was important because it was the first time I took ownership of my own life. Had I simply gone along with expectations, I might have ended up stuck in a career I didn’t enjoy."}, {"label": "Reflection", "text": "Looking back, what I value most isn’t the outcome but the principle: it’s worth trusting your own judgement, even when it goes against the grain."}], "phrases": [["agonise over", "worry for a long time about a decision"], ["talk (it) over with", "discuss with someone"], ["hit home", "have a strong emotional effect"], ["nerve-racking", "making you very nervous"], ["brace yourself", "prepare for something unpleasant"], ["come round", "change your opinion and agree"], ["take ownership", "take responsibility and control"], ["go along with", "accept what others want"], ["stuck", "unable to move on from a situation"], ["trust your own judgement", "believe your own opinion"], ["go against the grain", "be different from what is usual or expected"], ["engaged", "interested and involved"]], "grammar": [{"pattern": "Relative clause with who", "use": "who + past perfect", "example": "my older cousin, who’d studied abroad", "try": "my friend, who’d ______."}, {"pattern": "Cleft sentence with what", "use": "What + really + verb + was + noun", "example": "What really decided it was a question from my chemistry teacher", "try": "What really decided it was ______."}, {"pattern": "Second conditional in direct speech", "use": "if + nobody were + -ing", "example": "if nobody were watching", "try": "Would you do it if nobody ______?"}, {"pattern": "Relative clause with which", "use": "..., which + I’d never + past participle", "example": "which I’d never have imagined", "try": "..., which I’d never have ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, might have + past participle", "example": "Had I simply gone along with expectations, I might have ended up stuck", "try": "Had I ______, I might have ______."}, {"pattern": "worth + -ing", "use": "it’s worth + -ing: it is valuable to", "example": "it’s worth trusting your own judgement", "try": "It’s worth ______."}]}}, "part3": {"intro": "We’ve been talking about an important decision you made, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Important decision you made", "title": "Important decision you made", "questions": [{"q": "Do you think children should make important decisions on their own?", "model": {"answer": "Not entirely. Younger children lack the experience to foresee the consequences, so parents should guide them and explain their reasoning. From their teens onwards, though, they ought to be given more say, particularly on matters that affect them directly, such as hobbies or school subjects. Allowing children to make their own mistakes within safe limits is the best way to build independence.", "phrases": [["foresee the consequences", "predict the results of an action"], ["have a say", "have a voice in a decision"], ["make mistakes", "do things wrongly"], ["build independence", "help someone become self-reliant"], ["within limits", "not going beyond a safe boundary"]], "grammar": [{"pattern": "Passive with ought to", "use": "ought to be given + noun", "example": "they ought to be given more say", "try": "Teenagers ought to be given ______."}, {"pattern": "Gerund as subject", "use": "Allowing + object + to-infinitive + is", "example": "Allowing children to make their own mistakes within safe limits is the best way to build independence", "try": "Allowing students to ______ is the best way to ______."}]}}, {"q": "What important decisions do young people have to make after they finish school?", "model": {"answer": "The biggest is what to study, and where, since that shapes their career for years. Closely linked to this is whether to move away from home, which brings financial and emotional challenges. Some also have to choose between going straight to university, taking a gap year, or starting work to support their families. Each choice involves weighing up short-term gains against long-term goals.", "phrases": [["shape a career", "strongly influence a career"], ["take a gap year", "take a year off before studying"], ["support a family", "provide money for relatives"], ["weigh up", "consider carefully the good and bad points"], ["straight to", "directly to"]], "grammar": [{"pattern": "Indirect question with whether", "use": "whether + to-infinitive", "example": "whether to move away from home", "try": "They must decide whether to ______."}, {"pattern": "Involve + -ing", "use": "involve + -ing + A against B", "example": "Each choice involves weighing up short-term gains against long-term goals", "try": "Each choice involves ______ A against B."}]}}, {"q": "Who can young people turn to for advice when they have a decision to make?", "model": {"answer": "Parents are the obvious first port of call, as they know you best and want what’s best for you. However, they can be biased by their own hopes, so a teacher, an older sibling or a mentor who has been in the same position can offer a more objective view. Increasingly, young people also consult online forums, though advice from strangers should be taken with a pinch of salt.", "phrases": [["first port of call", "the first person or place you go to"], ["biased", "unfairly influenced"], ["be in the same position", "have had the same situation"], ["objective view", "fair opinion not based on feelings"], ["with a pinch of salt", "not completely trusting"]], "grammar": [{"pattern": "Present perfect in relative clause", "use": "who has + past participle", "example": "a mentor who has been in the same position", "try": "Ask someone who has ______."}, {"pattern": "Passive modal", "use": "should be + past participle", "example": "advice from strangers should be taken with a pinch of salt", "try": "Online advice should be ______."}]}}, {"q": "Do you think people make better decisions alone or in a group?", "model": {"answer": "If it’s a complex problem, a group usually wins, because different people bring different perspectives and spot risks you’d overlook. The danger is groupthink, where nobody wants to rock the boat and everyone just agrees with the loudest voice. For personal choices, I’d rather decide alone after seeking advice, since I’m the one who has to live with the outcome.", "phrases": [["bring different perspectives", "offer different points of view"], ["overlook", "fail to notice"], ["groupthink", "everyone in a group thinking the same way"], ["rock the boat", "cause trouble by disagreeing"], ["seek advice", "ask for guidance"]], "grammar": [{"pattern": "Zero conditional", "use": "If + present, present", "example": "If it’s a complex problem, a group usually wins", "try": "If it’s a personal issue, I usually ______."}, {"pattern": "Relative clause with where", "use": "noun + where + clause", "example": "groupthink, where nobody wants to rock the boat", "try": "..., where nobody ______."}]}}, {"q": "What do people usually consider before making a big decision?", "model": {"answer": "Cost and risk come first. People ask what they stand to gain or lose, and whether they could afford to fail. Then they factor in how it will affect their family, as decisions rarely affect just one person. Timing matters as well: even a good opportunity can be wrong if it arrives at the wrong moment. Many people finally go with their gut once the logic has been done.", "phrases": [["stand to gain or lose", "be likely to benefit or suffer"], ["afford to", "be able to bear the cost or risk of"], ["factor in", "include in your thinking"], ["at the wrong moment", "at an unsuitable time"], ["go with your gut", "follow your instinct"]], "grammar": [{"pattern": "Indirect question", "use": "ask + what / whether + clause", "example": "People ask what they stand to gain or lose, and whether they could afford to fail", "try": "People ask whether they could ______."}, {"pattern": "Conditional with can", "use": "even + noun + can be wrong if", "example": "even a good opportunity can be wrong if it arrives at the wrong moment", "try": "Even a good idea can fail if ______."}]}}, {"q": "Do advertisements influence the decisions that people make when shopping?", "model": {"answer": "Undoubtedly, and often more than people admit. Advertisers target specific audiences, so a young person scrolling online sees products tailored to their tastes, which makes a purchase feel essential. Influencer promotions are even more persuasive, because they come across as a friend’s recommendation. That said, careful shoppers see through the hype; the real danger lies in impulse buying, especially late at night.", "phrases": [["target", "aim at a particular group"], ["tailored to", "designed for a particular person"], ["come across as", "seem like"], ["see through", "recognise the truth behind"], ["impulse buying", "buying without planning"]], "grammar": [{"pattern": "Participle clause", "use": "noun + -ing + verb", "example": "a young person scrolling online sees products", "try": "A teenager ______ online sees ______."}, {"pattern": "Even + comparative", "use": "even more + adjective + because", "example": "Influencer promotions are even more persuasive, because", "try": "Videos are even more ______, because ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000013', 1013, 'Topic 13', 'Teamwork', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 13, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a time when you worked in a group", "bullets": ["what the team was like", "why you joined it", "what you did", "how you felt about it"], "explain": "", "notes": ["What", "Why", "What I Did", "Feelings"], "rounding": {"q": "Would you like to work in a team like that again in the future?", "model": {"answer": "Yes, I would, as long as everyone is committed. That project taught me a lot, and I’d happily repeat it, although next time I’d agree on clearer roles from day one.", "phrases": [], "grammar": []}}, "model": {"answer": "One occasion I’ll never forget is a group project in my second year at university, where five of us had to write a market research report for a local bakery. The team was a real mixed bag. Dilnoza was ruthlessly organised, Timur was the creative one, and Aziz, who barely said a word at the first meeting, turned out to be brilliant with numbers. I hadn’t chosen to join it, to be honest; the lecturer had assigned the groups. But I wasn’t unhappy about that, because I’d been struggling to keep up with statistics all term, and I needed people who could fill in the gaps in my knowledge. My job was to design and run the customer survey, so I spent two weeks outside the bakery in Chilonzor, stopping passers-by with a clipboard. Halfway through, Timur and Dilnoza had a falling-out over the layout of the report, and I had to step in. Had I stayed silent, the whole project would have collapsed. We eventually met in the middle, and the night before the deadline we pulled an all-nighter, bouncing ideas off each other until sunrise. Looking back, I loved it. I’d been worried that someone would slack off, but everyone pulled their weight, and the owner even took on board several of our suggestions. What struck me was how much better the report was than anything I could have written alone. A good team really can be greater than the sum of its parts.", "sections": [{"label": "What", "text": "One occasion I’ll never forget is a group project in my second year at university, where five of us had to write a market research report for a local bakery. The team was a real mixed bag. Dilnoza was ruthlessly organised, Timur was the creative one, and Aziz, who barely said a word at the first meeting, turned out to be brilliant with numbers."}, {"label": "Why", "text": "I hadn’t chosen to join it, to be honest; the lecturer had assigned the groups. But I wasn’t unhappy about that, because I’d been struggling to keep up with statistics all term, and I needed people who could fill in the gaps in my knowledge."}, {"label": "What I Did", "text": "My job was to design and run the customer survey, so I spent two weeks outside the bakery in Chilonzor, stopping passers-by with a clipboard. Halfway through, Timur and Dilnoza had a falling-out over the layout of the report, and I had to step in. Had I stayed silent, the whole project would have collapsed. We eventually met in the middle, and the night before the deadline we pulled an all-nighter, bouncing ideas off each other until sunrise."}, {"label": "Feelings", "text": "Looking back, I loved it. I’d been worried that someone would slack off, but everyone pulled their weight, and the owner even took on board several of our suggestions. What struck me was how much better the report was than anything I could have written alone. A good team really can be greater than the sum of its parts."}], "phrases": [["a mixed bag", "a group made up of very different people or things"], ["struggle to keep up with", "find it hard to stay at the level or speed of others"], ["fill in the gaps", "provide what is missing"], ["have a falling-out", "have an argument that damages a relationship"], ["step in", "get involved to solve a problem"], ["meet in the middle", "reach a compromise"], ["pull an all-nighter", "work through the whole night"], ["bounce ideas off (someone)", "share ideas and get quick reactions"], ["slack off", "work less hard than you should"], ["pull your weight", "do your fair share of the work"], ["take (something) on board", "accept an idea and consider it seriously"], ["greater than the sum of its parts", "better together than separately"]], "grammar": [{"pattern": "Non-defining relative clause with", "use": "where a situation + , where + clause", "example": "a group project in my second year at university, where five of us had to write a market research report", "try": "I took a course last year, where ______."}, {"pattern": "Non-defining relative clause with", "use": "who a person + , who + clause + , main verb", "example": "Aziz, who barely said a word at the first meeting, turned out to be brilliant with numbers", "try": "My cousin, who ______, turned out to be ______."}, {"pattern": "Past perfect for background", "use": "had / hadn’t + past participle: an earlier action or state", "example": "I hadn’t chosen to join it", "try": "I hadn’t ______ before that."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, would have + past participle", "example": "Had I stayed silent, the whole project would have collapsed", "try": "Had I ______, I would have ______."}, {"pattern": "Cleft sentence with what", "use": "What + verb + was + clause: puts the focus on one idea", "example": "What struck me was how much better the report was than anything I could have written alone", "try": "What struck me was ______."}, {"pattern": "Participle clause", "use": "main clause + , + -ing phrase: two actions together", "example": "bouncing ideas off each other until sunrise", "try": "We stayed up late, ______ing ______."}]}}, "part3": {"intro": "We’ve been talking about a time when you worked in a group, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Teamwork", "title": "Teamwork", "questions": [{"q": "Do you prefer working in a team or on your own?", "model": {"answer": "It depends on the stage of the task. At the start, I’d much rather be in a team, because ideas bounce off each other and weak ones get filtered out quickly. But when I’m actually writing or crunching numbers, I work best on my own. So ideally, I’d do the groundwork alone and then pool our ideas with colleagues, which is how my best projects have usually come together.", "phrases": [["bounce off each other", "develop through being shared back and forth"], ["crunch numbers", "do detailed calculations"], ["work best", "be most productive"], ["do the groundwork", "prepare the basic work first"], ["pool ideas", "put everyone’s ideas together"]], "grammar": [{"pattern": "would rather", "use": "would (much) rather + base verb: a preference", "example": "I’d much rather be in a team", "try": "I’d much rather ______ than ______."}, {"pattern": "Relative clause with which", "use": "a whole idea + , which + is how / is why + clause", "example": "which is how my best projects have usually come together", "try": "______, which is why ______."}]}}, {"q": "Why do some people prefer to work alone?", "model": {"answer": "Mostly because of past experience. People who have been let down by teammates learn that it’s safer to rely on themselves. Personality plays a part too: introverts often find group work draining and would rather get on with things at their own pace. And perfectionists, who find it hard to let go of control, see collaboration as a risk. Frankly, some just don’t want to carry the team.", "phrases": [["let (someone) down", "disappoint someone by not doing what they expected"], ["draining", "tiring, using up your energy"], ["get on with", "continue doing something"], ["let go of", "stop holding on to"], ["carry the team", "do most of the work while others do little"]], "grammar": [{"pattern": "Present perfect passive", "use": "have been + past participle: an experience that affects now", "example": "People who have been let down by teammates learn that it’s safer to rely on themselves", "try": "Anyone who has been ______ by ______ will ______."}, {"pattern": "Defining relative clause", "use": "noun + who + verb: identifies which people", "example": "perfectionists, who find it hard to let go of control", "try": "People who ______ often ______."}]}}, {"q": "What kinds of jobs require people to work in a team?", "model": {"answer": "Almost anything where the stakes are high. A surgeon can’t operate without nurses and an anaesthetist, and an airline crew has to work in sync for a flight to run safely. Software development and journalism are team efforts too, with each person supplying one piece of the puzzle. Without constant communication, the whole thing would fall apart. Writing a novel is perhaps the exception, since that’s a fairly solitary pursuit.", "phrases": [["work in sync", "work together smoothly and at the same pace"], ["team effort", "work done by a group, not one person"], ["piece of the puzzle", "one part of a larger whole"], ["fall apart", "fail completely"], ["solitary", "done alone"]], "grammar": [{"pattern": "without + noun", "use": "without + noun: ’if there isn’t...’", "example": "A surgeon can’t operate without nurses and an anaesthetist", "try": "A restaurant can’t run without ______."}, {"pattern": "with + noun + -ing", "use": "with + noun + -ing: adds a simultaneous detail", "example": "with each person supplying one piece of the puzzle", "try": "______, with everyone ______."}]}}, {"q": "What qualities should a good team member have?", "model": {"answer": "Reliability comes first. A good team member keeps their word and meets deadlines, so nobody is left picking up the slack. Equally important is the ability to listen as well as speak, because a team full of talkers gets nowhere. Flexibility matters too: plans change, and you can’t dig your heels in every time. Finally, a sense of humour does wonders to ease the tension before a deadline.", "phrases": [["keep your word", "do what you promised"], ["meet deadlines", "finish work on time"], ["pick up the slack", "do work that others haven’t done"], ["dig your heels in", "refuse to change your position"], ["ease the tension", "make a tense situation more relaxed"]], "grammar": [{"pattern": "be left + -ing", "use": "be left + -ing: forced to do something because of others", "example": "nobody is left picking up the slack", "try": "Nobody should be left ______."}, {"pattern": "as well as", "use": "A as well as B: both things, with B as a bonus", "example": "the ability to listen as well as speak", "try": "A good manager must ______ as well as ______."}]}}, {"q": "What makes a good leader?", "model": {"answer": "Someone who leads from the front rather than simply giving orders. If a leader sets the tone by working hard and staying calm under pressure, the team will usually follow. They also need to trust people, not breathe down their necks, and to take responsibility when things go wrong. The best boss I’ve had was firm but fair, and she always gave credit where it was due.", "phrases": [["lead from the front", "set an example by doing the hard work yourself"], ["set the tone", "decide the atmosphere or standard of a group"], ["breathe down (someone’s) neck", "watch someone too closely"], ["take responsibility", "accept blame or duty"], ["give credit where it’s due", "praise people who deserve it"]], "grammar": [{"pattern": "First conditional", "use": "If + present simple, will + base verb", "example": "If a leader sets the tone by working hard and staying calm under pressure, the team will usually follow", "try": "If a manager ______, the team will ______."}, {"pattern": "Superlative + present perfect", "use": "the best + noun + I’ve + past participle", "example": "The best boss I’ve had was firm but fair", "try": "The best teacher I’ve had was ______."}]}}, {"q": "Do you think team-building activities are useful for companies?", "model": {"answer": "On the one hand, a day out or a weekend retreat helps colleagues bond, and it often breaks down barriers between departments. On the other hand, activities that feel forced can backfire, especially if staff are made to take part in something awkward. They work best when they’re voluntary and when managers follow up afterwards with real changes, rather than treating the whole thing as a box-ticking exercise.", "phrases": [["bond", "form a close connection"], ["break down barriers", "remove the distance between groups"], ["backfire", "have the opposite of the intended effect"], ["follow up", "take action afterwards to continue the effect"], ["box-ticking exercise", "something done only to look official"]], "grammar": [{"pattern": "On the one hand... on the other", "use": "hand two-sided structure for balanced opinions", "example": "On the one hand, a day out or a weekend retreat helps colleagues bond", "try": "On the one hand, ______. On the other hand, ______."}, {"pattern": "be made to + base verb", "use": "passive of make: be forced to do something", "example": "staff are made to take part in something awkward", "try": "Students are sometimes made to ______."}, {"pattern": "rather than + -ing", "use": "rather than + -ing: instead of doing something", "example": "rather than treating the whole thing as a box-ticking exercise", "try": "______, rather than ______ing."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000014', 1014, 'Topic 14', 'Successful business person you know', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 14, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a successful business person you know", "bullets": ["who this person is", "how you know them", "what business this person does", "why this person is successful"], "explain": "", "notes": ["Who", "How I Know Her", "Business", "Why"], "rounding": {"q": "Would you like to start your own business one day?", "model": {"answer": "Perhaps, yes. I’d need more experience first, though. I’d like to learn the ropes in someone else’s company before taking that kind of risk myself.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be Gulnora opa, a woman in her late forties who lives in Margilan. She’s one of the most down-to-earth people I know, even though she’s well off by any standard. She’s my aunt’s old classmate, and I got to know her properly when I did a summer internship in her office at nineteen. I’d expected a stern boss, so I was taken aback when she struck up a conversation with me about my studies on my very first morning. Her company makes silk and ikat fabrics and sells them to boutiques in Tashkent and, increasingly, abroad. She started out with two looms in her garage, and over twenty years she’s built up the business into a workshop employing about eighty people, most of them women from nearby villages. So what makes her successful? For one thing, she has a good head for figures and never takes reckless risks. But what really sets her apart is how she treats people. Because she pays fairly and listens to her weavers, hardly anyone ever leaves. She’s resilient, too: when a big export order was cancelled during the pandemic, she didn’t panic, she simply bounced back by moving online within a few months. Had she given up then, the business wouldn’t exist today. I genuinely look up to her. She taught me that success is mostly down to persistence and decency, and if I ever run a company, I’d like to follow in her footsteps.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be Gulnora opa, a woman in her late forties who lives in Margilan. She’s one of the most down-to-earth people I know, even though she’s well off by any standard."}, {"label": "How I Know Her", "text": "She’s my aunt’s old classmate, and I got to know her properly when I did a summer internship in her office at nineteen. I’d expected a stern boss, so I was taken aback when she struck up a conversation with me about my studies on my very first morning."}, {"label": "Business", "text": "Her company makes silk and ikat fabrics and sells them to boutiques in Tashkent and, increasingly, abroad. She started out with two looms in her garage, and over twenty years she’s built up the business into a workshop employing about eighty people, most of them women from nearby villages."}, {"label": "Why", "text": "So what makes her successful? For one thing, she has a good head for figures and never takes reckless risks. But what really sets her apart is how she treats people. Because she pays fairly and listens to her weavers, hardly anyone ever leaves. She’s resilient, too: when a big export order was cancelled during the pandemic, she didn’t panic, she simply bounced back by moving online within a few months. Had she given up then, the business wouldn’t exist today. I genuinely look up to her. She taught me that success is mostly down to persistence and decency, and if I ever run a company, I’d like to follow in her footsteps."}], "phrases": [["down-to-earth", "practical, natural and not arrogant"], ["well off", "having plenty of money"], ["taken aback", "surprised and a little shocked"], ["strike up a conversation", "start talking to someone casually"], ["start out", "begin, especially in a small way"], ["build (something) up", "develop something gradually into something bigger"], ["have a good head for", "be naturally good at (figures, business)"], ["set (someone) apart", "make someone different from and better than others"], ["bounce back", "recover quickly after a failure"], ["look up to", "admire and respect"], ["be down to", "be caused by, depend on"], ["follow in (someone’s) footsteps", "do the same career or path as someone"]], "grammar": [{"pattern": "Concession with even though", "use": "even though + clause: contrast with a surprising fact", "example": "even though she’s well off by any standard", "try": "He’s very modest, even though ______."}, {"pattern": "Past perfect for expectation", "use": "I’d expected + noun, so I was surprised", "example": "I’d expected a stern boss, so I was taken aback", "try": "I’d expected ______, so I was ______."}, {"pattern": "Participle clause", "use": "noun + -ing + details: reduced relative clause", "example": "a workshop employing about eighty people", "try": "a company employing ______."}, {"pattern": "Cleft sentence with what", "use": "What + verb + is + clause", "example": "what really sets her apart is how she treats people", "try": "What really sets him apart is ______."}, {"pattern": "Negative adverb hardly", "use": "hardly anyone / ever: almost nobody", "example": "hardly anyone ever leaves", "try": "Hardly anyone ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, would + base verb", "example": "Had she given up then, the business wouldn’t exist today", "try": "Had I ______, I wouldn’t ______ today."}]}}, "part3": {"intro": "We’ve been talking about a successful business person you know, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Successful business person you know", "title": "Successful business person you know", "questions": [{"q": "Why do some people decide to start their own business?", "model": {"answer": "Usually it comes down to independence. Many people are tired of taking orders and want to be their own boss, with the freedom to call the shots. Others spot a gap in the market, or simply have an idea they’re passionate about. Then there’s money: a successful business can earn far more than a salary, although it’s a real gamble when you’re starting from scratch.", "phrases": [["be your own boss", "work for yourself"], ["call the shots", "make the important decisions"], ["gap in the market", "a need that no company is meeting yet"], ["gamble", "a risky decision that might not work"], ["start from scratch", "begin with nothing"]], "grammar": [{"pattern": "Adjective + to-infinitive", "use": "be tired of + -ing: a feeling about a routine", "example": "Many people are tired of taking orders", "try": "Many people are tired of ______."}, {"pattern": "Although + clause", "use": "although + clause: a concession", "example": "although it’s a real gamble when you’re starting from scratch", "try": "It pays well, although ______."}]}}, {"q": "Is it better to run your own business or to work for someone else?", "model": {"answer": "Neither is better across the board. Running your own business offers freedom and bigger rewards, but the income is unpredictable and you rarely switch off. Being employed is safer, with a regular salary and holidays. If I were starting my career now, I’d probably learn the ropes in a company first, and then, once I’d saved some money, take the plunge.", "phrases": [["across the board", "in all cases"], ["switch off", "stop thinking about work and relax"], ["safer", "less risky"], ["learn the ropes", "learn how a job works"], ["take the plunge", "finally make a big, risky decision"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If I were starting my career now, I’d probably learn the ropes in a company first", "try": "If I were ______, I’d probably ______."}, {"pattern": "Past perfect after once", "use": "once + past perfect: finished before another future action", "example": "once I’d saved some money", "try": "Once I’d ______, I’d ______."}]}}, {"q": "What skills do people need in order to run a business successfully?", "model": {"answer": "Firstly, a basic grasp of money, because many businesses fail simply by running out of cash. Beyond that, you need to think on your feet, since problems rarely arrive at convenient moments. People skills matter as well: persuading customers, negotiating with suppliers and keeping staff motivated. Last but not least, resilience, because not everyone can take setbacks in their stride.", "phrases": [["grasp", "understanding"], ["run out of cash", "have no money left"], ["think on your feet", "react and decide quickly"], ["keep staff motivated", "make employees stay enthusiastic"], ["take setbacks in your stride", "deal calmly with problems"]], "grammar": [{"pattern": "fail by + -ing", "use": "fail simply by + -ing: the cause of failure", "example": "many businesses fail simply by running out of cash", "try": "Many projects fail simply by ______."}, {"pattern": "Gerunds as a list", "use": "persuading..., negotiating... and...: parallel -ing forms", "example": "persuading customers, negotiating with suppliers and keeping staff motivated", "try": "______ing ______, ______ing ______ and ______ing ______."}]}}, {"q": "Do you think it is easier to start a business now than it was in the past?", "model": {"answer": "Technically, yes. These days you can set up shop online in an afternoon and reach customers across the country without renting premises. Yet the competition is far fiercer, so it’s much harder to stand out from the crowd. My father says that when he was young there were fewer rivals, but also far fewer ways to find customers, so I’d call it a trade-off rather than a clear improvement.", "phrases": [["set up shop", "start a business"], ["premises", "a building used for business"], ["fierce", "very strong and aggressive"], ["stand out from the crowd", "be noticeably different and better"], ["trade-off", "a situation where gaining one thing means losing another"]], "grammar": [{"pattern": "far + comparative", "use": "far / much + comparative: a big difference", "example": "the competition is far fiercer", "try": "Life is far ______ than ______."}, {"pattern": "when + past simple (past time)", "use": "My father says that when he was young...", "example": "when he was young there were fewer rivals", "try": "When my grandfather was young, ______."}]}}, {"q": "Do people in your country prefer to work for big companies or small ones?", "model": {"answer": "Judging by my friends, big companies still have the edge, mainly because of job security and a steady salary. Parents in particular see a corporate or state job as the safe option. That said, attitudes are shifting. More graduates are drawn to smaller firms, where they can take on more responsibility early and move up the ladder faster, even if the pay is less predictable.", "phrases": [["have the edge", "be slightly better or more popular"], ["job security", "the feeling that you won’t lose your job"], ["that said", "however; despite that"], ["take on responsibility", "accept more duties"], ["move up the ladder", "get promoted step by step"]], "grammar": [{"pattern": "Participle opening", "use": "Judging by + noun: based on what I see", "example": "Judging by my friends", "try": "Judging by ______, ______."}, {"pattern": "Passive with drawn to", "use": "be drawn to + noun: be attracted by", "example": "More graduates are drawn to smaller firms, where they can take on more responsibility early", "try": "Many young people are drawn to ______, where ______."}]}}, {"q": "What difficulties do small businesses usually face?", "model": {"answer": "Cash flow is the biggest headache. A small shop may make a profit on paper but still struggle to pay suppliers on time. Small firms also can’t compete with larger chains on price, because they lack the buying power. On top of that, rent, taxes and paperwork eat into already thin margins, and if one key employee leaves, there’s often nobody to step into their shoes.", "phrases": [["make a profit", "earn more than you spend"], ["compete with", "try to win customers against"], ["on top of that", "in addition"], ["eat into", "gradually reduce"], ["step into (someone’s) shoes", "take over someone’s role"]], "grammar": [{"pattern": "May + but still", "use": "may + verb ..., but still + verb: contrast", "example": "may make a profit on paper but still struggle to pay suppliers on time", "try": "A shop may ______ but still ______."}, {"pattern": "there’s + nobody to + infinitive", "use": "there’s nobody to + base verb", "example": "there’s often nobody to step into their shoes", "try": "There’s often nobody to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000015', 1015, 'Topic 15', 'Home you like but don’t want to live in', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 15, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a home that you like but don’t want to live in", "bullets": ["where it was", "what it looked like", "why you visited it", "why you don’t want to live there"], "explain": "", "notes": ["Where", "Look", "Why I Visited", "Why Not Live There"], "rounding": {"q": "Is there any kind of home that you would actually like to live in?", "model": {"answer": "Yes, a modern flat with a balcony, close to work and a park. It wouldn’t be as picturesque, but I’d value the convenience far more than the charm.", "phrases": [], "grammar": []}}, "model": {"answer": "The first place that comes to mind is a traditional courtyard house in the old part of Bukhara, which belongs to my friend Sardor’s grandparents. It’s tucked away in a maze of narrow alleys, just a stone’s throw from a mosque, so you’d never find it without a guide. From the street it looks rather unassuming, just a plain clay wall and a heavy wooden door. But the moment you step inside, you find a sunlit courtyard with a grapevine overhead, a small fountain and a raised wooden platform where the family sits to drink tea. Sardor’s grandfather restored it himself over many years, and you can tell it was a real labour of love. The whole place oozes character. I went there last spring, when Sardor invited me to his grandmother’s seventieth birthday. We sat on that platform for hours, eating plov that had been cooked over an open fire, while she told us stories about the neighbourhood, which is steeped in history. Beautiful as it is, I could never live there. For a start, the thick walls keep the heat out in summer, but the rooms are draughty and freezing in winter. The upkeep is endless as well; the roof seems to need repairing every year. And since it’s so off the beaten track, even buying bread means a long walk, while tourists keep wandering in with cameras, and I’d have to put up with that every day. I’d miss my creature comforts, and I suspect that the novelty would soon wear off. A place can be a joy to visit without being a joy to live in.", "sections": [{"label": "Where", "text": "The first place that comes to mind is a traditional courtyard house in the old part of Bukhara, which belongs to my friend Sardor’s grandparents. It’s tucked away in a maze of narrow alleys, just a stone’s throw from a mosque, so you’d never find it without a guide."}, {"label": "Look", "text": "From the street it looks rather unassuming, just a plain clay wall and a heavy wooden door. But the moment you step inside, you find a sunlit courtyard with a grapevine overhead, a small fountain and a raised wooden platform where the family sits to drink tea. Sardor’s grandfather restored it himself over many years, and you can tell it was a real labour of love. The whole place oozes character."}, {"label": "Why I Visited", "text": "I went there last spring, when Sardor invited me to his grandmother’s seventieth birthday. We sat on that platform for hours, eating plov that had been cooked over an open fire, while she told us stories about the neighbourhood, which is steeped in history."}, {"label": "Why Not Live There", "text": "Beautiful as it is, I could never live there. For a start, the thick walls keep the heat out in summer, but the rooms are draughty and freezing in winter. The upkeep is endless as well; the roof seems to need repairing every year. And since it’s so off the beaten track, even buying bread means a long walk, while tourists keep wandering in with cameras, and I’d have to put up with that every day. I’d miss my creature comforts, and I suspect that the novelty would soon wear off. A place can be a joy to visit without being a joy to live in."}], "phrases": [["tucked away", "hidden in a quiet, hard-to-find place"], ["a stone’s throw from", "very close to"], ["unassuming", "simple and modest-looking"], ["a labour of love", "work done with great care for enjoyment, not reward"], ["ooze character", "have a lot of charm and personality"], ["steeped in history", "full of historical tradition and stories"], ["draughty", "with cold air coming in through gaps"], ["upkeep", "the cost and effort of keeping a building in good condition"], ["off the beaten track", "far from the usual routes and busy areas"], ["put up with", "accept something annoying without complaining"], ["creature comforts", "the small modern things that make life easy"], ["wear off", "gradually disappear"]], "grammar": [{"pattern": "Concession with adjective + as", "use": "Adjective + as + subject + be, main clause: although it is...", "example": "Beautiful as it is, I could never live there", "try": "Charming as it is, ______."}, {"pattern": "Past perfect passive", "use": "had been + past participle: an earlier completed action", "example": "plov that had been cooked over an open fire", "try": "a meal that had been ______."}, {"pattern": "Relative clause with where", "use": "a place + where + clause", "example": "a raised wooden platform where the family sits to drink tea", "try": "a room where ______."}, {"pattern": "Gerund as subject", "use": "-ing + noun + means + noun: an activity as the subject", "example": "even buying bread means a long walk", "try": "Even ______ing ______ means ______."}, {"pattern": "Suspect that + would", "use": "I suspect (that) + would + base verb: a cautious prediction", "example": "I suspect that the novelty would soon wear off", "try": "I suspect that ______ would soon ______."}, {"pattern": "without + -ing", "use": "A can be X without being Y", "example": "a joy to visit without being a joy to live in", "try": "A place can be ______ without being ______."}]}}, "part3": {"intro": "We’ve been talking about a home that you like but don’t want to live in, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Home you like but don’t want to live in", "title": "Home you like but don’t want to live in", "questions": [{"q": "When people visit someone’s home in your country, do they usually bring a gift?", "model": {"answer": "Almost always, yes. It would feel rude to turn up empty-handed, so guests usually bring something sweet, such as a cake or chocolates, or fruit if it’s a casual visit. For a wedding or a housewarming, the gift is more generous. Nobody expects anything extravagant; it’s really a gesture of respect, and the hosts will normally send you off with something in return.", "phrases": [["turn up empty-handed", "arrive without bringing anything"], ["generous", "larger or more giving than usual"], ["extravagant", "very expensive or excessive"], ["gesture", "an action showing a feeling"], ["send (someone) off with", "let someone leave with"]], "grammar": [{"pattern": "Conditional with would", "use": "It would + adjective + to + verb: a polite general rule", "example": "It would feel rude to turn up empty-handed", "try": "It would feel strange to ______."}, {"pattern": "Nobody expects + noun", "use": "nobody expects + adjective + noun", "example": "Nobody expects anything extravagant", "try": "Nobody expects anything ______."}]}}, {"q": "What kinds of houses or apartments do people in your country prefer to buy?", "model": {"answer": "It varies by generation and location. In cities like Tashkent, apartments are by far the most common choice, since land is scarce and prices are high. Outside the cities, however, most families hanker after a house with a garden where children can play and fruit trees can grow. Many people also want to stay close to relatives, so a home in a familiar neighbourhood is a big selling point.", "phrases": [["by far", "much more than anything else"], ["hanker after", "strongly want"], ["close to relatives", "near family members"], ["familiar neighbourhood", "an area you know well"], ["selling point", "a feature that attracts buyers"]], "grammar": [{"pattern": "by far + superlative", "use": "by far the + superlative: emphasises a big gap", "example": "apartments are by far the most common choice", "try": "______ is by far the most ______."}, {"pattern": "Relative clause with where", "use": "a garden + where + clause", "example": "a garden where children can play and fruit trees can grow", "try": "a yard where ______."}]}}, {"q": "What is the difference between living in a house and living in an apartment?", "model": {"answer": "Mainly space and responsibility. A house usually offers a garden, more privacy and the freedom to extend or redecorate as you wish, but every repair is down to you. An apartment is cheaper to maintain and often closer to the centre, with shops and transport nearby, though you have to put up with noisy neighbours and thin walls, and there’s rarely anywhere for children to play outside.", "phrases": [["extend", "make a building bigger"], ["be down to you", "be your responsibility"], ["maintain", "keep in good condition"], ["put up with", "tolerate something annoying"], ["thin walls", "walls that let sound through"]], "grammar": [{"pattern": "Whereas contrast", "use": "A ... but ... / though ...: contrasting two things", "example": "though you have to put up with noisy neighbours and thin walls", "try": "It’s convenient, though ______."}, {"pattern": "with + noun + adverb", "use": "with + noun + nearby: adds a surrounding detail", "example": "with shops and transport nearby", "try": "______, with ______ nearby."}]}}, {"q": "Why do some people prefer to rent rather than buy a home?", "model": {"answer": "Flexibility, mostly. Renting means you’re not tied down, which suits people who change jobs or cities often. It also avoids a big deposit and the risk of prices dropping. If I were just starting out in Tashkent, I’d probably rent too, because buying would stretch my budget to breaking point. Paying off a mortgage for twenty years can feel like a trap when you’re young.", "phrases": [["tied down", "limited by commitments"], ["deposit", "money paid first when buying or renting"], ["stretch (someone’s) budget", "use up more money than is comfortable"], ["pay off", "finish paying a debt"], ["mortgage", "a long loan from a bank to buy a home"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If I were just starting out in Tashkent, I’d probably rent too", "try": "If I were ______, I’d ______."}, {"pattern": "which suits", "use": "relative clause with which: comments on the previous idea", "example": "which suits people who change jobs or cities often", "try": "______, which suits people who ______."}]}}, {"q": "What do people consider when they choose where to live?", "model": {"answer": "Location tops the list, particularly the commute. Few people want to spend two hours a day in traffic. Beyond that, families look at schools, safety and whether there’s a good sense of community. Price obviously narrows down the options, and so do the facilities nearby, such as a market, a clinic and a park. Younger people also care about nightlife, whereas older ones settle for somewhere peaceful.", "phrases": [["tops the list", "is the most important"], ["commute", "the regular journey to work or school"], ["sense of community", "a feeling of belonging to a group of neighbours"], ["narrow down", "reduce the number of choices"], ["settle for", "accept as good enough"]], "grammar": [{"pattern": "so do + subject", "use": "so + auxiliary + subject: and the same is true of", "example": "and so do the facilities nearby", "try": "Price matters, and so does ______."}, {"pattern": "whereas", "use": "whereas: contrasts two groups", "example": "Younger people also care about nightlife, whereas older ones settle for somewhere peaceful", "try": "Some people ______, whereas others ______."}]}}, {"q": "How might homes be different in the future?", "model": {"answer": "I suspect they’ll be smaller and smarter. As cities grow and land gets more expensive, more people will live in compact apartments with space-saving furniture. Voice-controlled heating and lighting will probably be standard, cutting down on energy bills. We’ll also see more eco-friendly features, such as solar panels, provided they’re affordable. I just hope that, amid all the technology, homes will still feel homely.", "phrases": [["compact", "small but well designed"], ["space-saving", "designed to use little room"], ["cut down on", "reduce"], ["eco-friendly", "not harmful to the environment"], ["homely", "comfortable and welcoming"]], "grammar": [{"pattern": "As + comparative clause", "use": "As + subject + verb, more/most ...: two linked changes", "example": "As cities grow and land gets more expensive, more people will live in compact apartments", "try": "As ______ grows, more people will ______."}, {"pattern": "Participle clause", "use": "main clause + , + -ing: a result", "example": "cutting down on energy bills", "try": "______, cutting down on ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000016', 1016, 'Topic 16', 'Important river', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 16, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an important river or lake in your country", "bullets": ["what it is and where it is", "what you know about it", "how people use it", "and explain why it is important"], "explain": "", "notes": ["What And Where", "What I Know", "How People Use", "It"], "rounding": {"q": "Have you ever visited that river as an adult?", "model": {"answer": "Yes, a couple of years ago. It looked smaller and quieter than I remembered, but sitting on the bank at sunset brought all those summers flooding back.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about the Amu Darya, one of the two great rivers of Central Asia. It rises in the mountains far to the south-east and flows north-west through several countries before it reaches Khorezm, the region where my mother’s family comes from, so I’ve known it since childhood. What I know about it comes partly from school and partly from my grandfather. The water looks brown because of all the silt it carries, and it’s a real lifeline for the whole region. Sadly, it used to flow into the Aral Sea, which has shrunk dramatically over the past few decades, largely because so much water has been diverted for irrigation. People use it in countless ways. Farmers draw water from it through a network of canals, which keeps cotton, wheat and orchards alive in an otherwise arid climate. Fishermen still set out at dawn, and on summer evenings families flock to the banks to picnic. When I was a child, we would spend whole afternoons paddling there, while my grandfather explained how the river used to flood every spring. For me, it’s important on two levels. Practically speaking, without it farming in Khorezm would be nearly impossible, and whole villages would be left high and dry. Emotionally, it’s bound up with my childhood. Never had I realised how fragile a river could be until I saw photographs of ships stranded in the desert where the Aral Sea once stood. If we don’t look after our rivers, we can’t expect them to go on providing for us. Looking back, that image taught me that nature should never be taken for granted.", "sections": [{"label": "What And Where", "text": "Let me tell you about the Amu Darya, one of the two great rivers of Central Asia. It rises in the mountains far to the south-east and flows north-west through several countries before it reaches Khorezm, the region where my mother’s family comes from, so I’ve known it since childhood."}, {"label": "What I Know", "text": "What I know about it comes partly from school and partly from my grandfather. The water looks brown because of all the silt it carries, and it’s a real lifeline for the whole region. Sadly, it used to flow into the Aral Sea, which has shrunk dramatically over the past few decades, largely because so much water has been diverted for irrigation."}, {"label": "How People Use", "text": "People use it in countless ways. Farmers draw water from it through a network of"}, {"label": "It", "text": "canals, which keeps cotton, wheat and orchards alive in an otherwise arid climate. Fishermen still set out at dawn, and on summer evenings families flock to the banks to picnic. When I was a child, we would spend whole afternoons paddling there, while my grandfather explained how the river used to flood every spring."}, {"label": "Why It Matters", "text": "For me, it’s important on two levels. Practically speaking, without it farming in Khorezm would be nearly impossible, and whole villages would be left high and dry. Emotionally, it’s bound up with my childhood. Never had I realised how fragile a river could be until I saw photographs of ships stranded in the desert where the Aral Sea once stood. If we don’t look after our rivers, we can’t expect them to go on providing for us. Looking back, that image taught me that nature should never be taken for granted."}], "phrases": [["silt", "very fine mud carried by moving water"], ["lifeline", "something essential that people depend on"], ["shrink", "become smaller"], ["divert", "send water in a different direction"], ["draw water from", "take water out of a source"], ["arid", "very dry, with little rain"], ["flock to", "go somewhere in large numbers"], ["be left high and dry", "be left without help or resources"], ["be bound up with", "be closely connected with"], ["stranded", "left stuck and unable to move"], ["take (something) for granted", "fail to value something because it is always there"]], "grammar": [{"pattern": "Relative clause with where", "use": "the region + where + clause", "example": "the region where my mother’s family comes from", "try": "the town where ______."}, {"pattern": "Present perfect passive", "use": "has / have been + past participle: a change up to now", "example": "so much water has been diverted for irrigation", "try": "A lot of ______ has been ______."}, {"pattern": "Would for past habit + used to", "use": "would + base verb: repeated past actions; used to: past states", "example": "we would spend whole afternoons paddling there", "try": "In summer we would ______."}, {"pattern": "Inversion after never", "use": "Never + had + subject + past participle ... until", "example": "Never had I realised how fragile a river could be until I saw photographs", "try": "Never had I ______ until ______."}, {"pattern": "First conditional", "use": "If + present simple, can’t expect + object + to + base verb", "example": "If we don’t look after our rivers, we can’t expect them to go on providing for us", "try": "If we don’t ______, we can’t expect ______ to ______."}, {"pattern": "Passive with should never", "use": "should never be + past participle: a strong rule", "example": "nature should never be taken for granted", "try": "______ should never be ______."}]}}, "part3": {"intro": "We’ve been talking about an important river or lake in your country, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Important river", "title": "Important river", "questions": [{"q": "Why are rivers and lakes important to local people?", "model": {"answer": "Because they provide so much more than water. Farmers depend on them for irrigation, and for many families they’re a source of income and food. They’re also where people unwind: on a hot day, nothing beats a picnic by the water. If a river dried up, a community would lose not just its livelihood but also a place that brings people together, and that’s very hard to replace.", "phrases": [["source of income", "a way of earning money"], ["unwind", "relax after work or stress"], ["nothing beats", "nothing is better than"], ["livelihood", "the way someone earns money to live"], ["bring people together", "make people meet and feel connected"]], "grammar": [{"pattern": "Not just ... but also", "use": "not just + noun + but also + noun", "example": "not just its livelihood but also a place that brings people together", "try": "They lose not just ______ but also ______."}, {"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If a river dried up, a community would lose not just its livelihood", "try": "If ______ dried up, ______ would ______."}]}}, {"q": "What water sports are popular in your country, and why do people enjoy them?", "model": {"answer": "Swimming is the obvious one, but at reservoirs like Charvak, which attract city dwellers at weekends, kayaking, windsurfing and boating are catching on. Rafting on mountain rivers is also on the rise. People enjoy them because they offer a thrill after a week at a desk, and being outdoors, surrounded by mountains, is a perfect way to recharge their batteries.", "phrases": [["city dweller", "a person who lives in a city"], ["catch on", "become popular"], ["on the rise", "increasing"], ["thrill", "a sudden feeling of excitement"], ["recharge your batteries", "rest and regain energy"]], "grammar": [{"pattern": "Non-defining relative with which", "use": "a place + , which + verb: extra information", "example": "reservoirs like Charvak, which attract city dwellers at weekends", "try": "lakes like ______, which ______."}, {"pattern": "Participle clause", "use": "being + adjective/phrase: a reason or description", "example": "being outdoors, surrounded by mountains, is a perfect way", "try": "Being ______, ______ is a perfect way to ______."}]}}, {"q": "Do you think rivers and lakes help to attract tourists?", "model": {"answer": "Definitely, provided the water is clean and the surroundings are well looked after. A scenic lake is a big draw, and it isn’t only about sightseeing: visitors spend money on guesthouses, boat trips and local food, which boosts the local economy. Take the yurt camps near Aydarkul, which attract people who simply want to swim and stargaze, far from the noise of the city.", "phrases": [["well looked after", "kept in good condition"], ["scenic", "with beautiful natural views"], ["big draw", "a feature that attracts many people"], ["boost the local economy", "help local business and income grow"], ["stargaze", "look at the stars"]], "grammar": [{"pattern": "provided (that)", "use": "provided + clause: a condition", "example": "provided the water is clean and the surroundings are well looked after", "try": "It works, provided ______."}, {"pattern": "Relative clause with who", "use": "people + who + verb", "example": "people who simply want to swim and stargaze", "try": "people who just want to ______."}]}}, {"q": "Are rivers still important for transport today?", "model": {"answer": "Not as much as they once were, at least in my country. Trains and motorways are quicker and more reliable, so few people travel by water. Elsewhere, though, rivers remain vital for moving heavy goods like grain or coal cheaply, since a single barge can carry what would otherwise take dozens of lorries. I’d say they’ve lost ground for passengers but still hold their own for freight.", "phrases": [["not as much as they once were", "less important than before"], ["vital", "extremely important"], ["barge", "a flat boat for carrying goods"], ["lose ground", "become less important"], ["hold your own", "stay strong against competition"]], "grammar": [{"pattern": "Present perfect", "use": "they’ve + past participle: change that affects now", "example": "they’ve lost ground for passengers but still hold their own for freight", "try": "They’ve ______ but still ______."}, {"pattern": "what ... would otherwise", "use": "what + would otherwise + verb: the alternative", "example": "what would otherwise take dozens of lorries", "try": "______ can carry what would otherwise ______."}]}}, {"q": "What problems can pollution cause for rivers and lakes?", "model": {"answer": "The effects snowball. Chemicals from farms and factories kill fish, which disrupts the whole food chain, and then the people who rely on fishing lose their income. Polluted water is also hazardous to drink, so waterborne diseases can spread. Worst of all, the damage can take decades to reverse. The Aral Sea is a sobering reminder of how quickly things can go downhill once a water source is neglected.", "phrases": [["snowball", "grow bigger and faster over time"], ["disrupt the food chain", "damage the links between living things"], ["hazardous", "dangerous"], ["sobering", "making you think seriously"], ["go downhill", "get steadily worse"]], "grammar": [{"pattern": "Relative clause with which", "use": "a result + , which + verb", "example": "which disrupts the whole food chain", "try": "______, which ______."}, {"pattern": "how + adverb + clause", "use": "a reminder of how + adverb + clause", "example": "a sobering reminder of how quickly things can go downhill once a water source is neglected", "try": "It’s a reminder of how quickly ______."}]}}, {"q": "Who should be responsible for protecting rivers and lakes?", "model": {"answer": "It has to be shared. Governments set and enforce the rules, for instance by fining factories that dump waste, and they have the funding for large projects like cleaning up riverbanks. But individuals matter just as much; if people keep leaving rubbish at picnic spots, no law will help. Schools can raise awareness early, and communities can organise clean-up days, so the burden shouldn’t fall on one group.", "phrases": [["enforce", "make sure people obey a rule"], ["fine", "make someone pay money as a punishment"], ["raise awareness", "make people notice a problem"], ["clean-up", "an organised effort to remove rubbish"], ["fall on", "become the duty of"]], "grammar": [{"pattern": "First conditional", "use": "if + present, no/will + base verb", "example": "if people keep leaving rubbish at picnic spots, no law will help", "try": "If people keep ______, no ______ will help."}, {"pattern": "by + -ing", "use": "by + -ing: the method", "example": "by fining factories that dump waste", "try": "Governments can help by ______ing ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000017', 1017, 'Topic 17', 'Thing you did to learn a language', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 17, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe something you did to learn a language", "bullets": ["what language you learned", "what you did", "how it helped you", "and explain how you felt about it"], "explain": "", "notes": ["What Language", "What I Did", "How It Helped", "Feelings"], "rounding": {"q": "Do you still use that method to learn languages today?", "model": {"answer": "Partly, yes. I’ve started learning Korean in much the same way, with dramas and a notebook, although I’m a lot more patient with myself now than I was at fifteen.", "phrases": [], "grammar": []}}, "model": {"answer": "One thing that really transformed my English was a summer routine I invented when I was fifteen. I’d been studying the language at school for years, yet I couldn’t hold a conversation, and the penny dropped one evening at my cousin’s house, when I failed to follow a single scene of an American film. I was so embarrassed that I decided something had to change. So I picked a sitcom and watched one episode every evening, first with Russian subtitles, then with English ones, and finally with none at all. Whenever a line struck me as useful, I’d pause the video, repeat it out loud and jot down the phrase in a notebook. It felt silly at first, talking to a screen, but I soon got the hang of it. By the end of August I’d filled almost two notebooks. The difference was striking. My listening improved first, because I could finally pick up on the jokes without reading, and my pronunciation became far more natural since I’d been copying real speakers. Had I stuck to the textbook, I’d probably still be translating every sentence in my head. When I started university, I could keep up with lectures in English from the very first week, which gave me a real head start. Honestly, I felt proud, and slightly addicted. It stopped feeling like homework and became something I looked forward to all day. What I learned is that a language sticks when you meet it in context and enjoy it, rather than cramming lists of words. That summer was a genuine turning point for me.", "sections": [{"label": "What Language", "text": "One thing that really transformed my English was a summer routine I invented when I was fifteen. I’d been studying the language at school for years, yet I couldn’t hold a conversation, and the penny dropped one evening at my cousin’s house, when I failed to follow a single scene of an American film. I was so embarrassed that I decided something had to change."}, {"label": "What I Did", "text": "So I picked a sitcom and watched one episode every evening, first with Russian subtitles, then with English ones, and finally with none at all. Whenever a line struck me as useful, I’d pause the video, repeat it out loud and jot down the phrase in a notebook. It felt silly at first, talking to a screen, but I soon got the hang of it. By the end of August I’d filled almost two notebooks."}, {"label": "How It Helped", "text": "The difference was striking. My listening improved first, because I could finally pick up on the jokes without reading, and my pronunciation became far more natural since I’d been copying real speakers. Had I stuck to the textbook, I’d probably still be translating every sentence in my head. When I started university, I could keep up with lectures in English from the very first week, which gave me a real head start."}, {"label": "Feelings", "text": "Honestly, I felt proud, and slightly addicted. It stopped feeling like homework and became something I looked forward to all day. What I learned is that a language sticks when you meet it in context and enjoy it, rather than cramming lists of words. That summer was a genuine turning point for me."}], "phrases": [["hold a conversation", "speak with someone in a normal, connected way"], ["the penny dropped", "I suddenly understood something"], ["jot down", "write something quickly and briefly"], ["get the hang of", "learn how to do something"], ["pick up on", "notice and understand"], ["keep up with", "stay at the same level as"], ["give (someone) a head start", "give an early advantage"], ["stick", "stay in your memory"], ["in context", "as part of real sentences or situations"], ["cram", "study a lot in a short time"], ["turning point", "a moment when things begin to change"]], "grammar": [{"pattern": "Past perfect continuous", "use": "had been + -ing: an activity continuing up to a past moment", "example": "I’d been studying the language at school for years", "try": "I’d been ______ for years when ______."}, {"pattern": "so ... that", "use": "so + adjective + that + result", "example": "I was so embarrassed that I decided something had to change", "try": "I was so ______ that I ______."}, {"pattern": "Would for repeated past actions", "use": "Whenever + past simple, I’d + base verb", "example": "Whenever a line struck me as useful, I’d pause the video", "try": "Whenever I ______, I’d ______."}, {"pattern": "Mixed conditional Had + subject + past participle, would + be", "use": "+ -ing: past cause, present result", "example": "Had I stuck to the textbook, I’d probably still be translating every sentence in my head", "try": "Had I ______, I’d probably still be ______."}, {"pattern": "Relative clause with which", "use": "a whole situation + , which + verb", "example": "which gave me a real head start", "try": "______, which gave me ______."}, {"pattern": "Cleft sentence with what", "use": "What + subject + verb + is that + clause", "example": "What I learned is that a language sticks when you meet it in context", "try": "What I learned is that ______."}]}}, "part3": {"intro": "We’ve been talking about something you did to learn a language, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Thing you did to learn a language", "title": "Thing you did to learn a language", "questions": [{"q": "What difficulties do people face when they learn a foreign language?", "model": {"answer": "Pronunciation and vocabulary are the usual hurdles, but I’d argue the hardest part is staying motivated. Progress is slow at the beginning, so many learners hit a plateau and give up. There’s also the fear of making mistakes: people who speak confidently in their own language suddenly freeze up, afraid of being laughed at. Time is another stumbling block, since adults have jobs and families.", "phrases": [["hurdle", "a difficulty that must be overcome"], ["stay motivated", "keep wanting to continue"], ["hit a plateau", "stop making progress"], ["freeze up", "become unable to speak or act because of nerves"], ["stumbling block", "something that makes progress difficult"]], "grammar": [{"pattern": "I’d argue (that)", "use": "I’d argue + (that) + clause: a considered opinion", "example": "I’d argue the hardest part is staying motivated", "try": "I’d argue the hardest part is ______."}, {"pattern": "Afraid of + being + past participle", "use": "afraid of + being + past participle: fear of a passive experience", "example": "afraid of being laughed at", "try": "afraid of being ______."}]}}, {"q": "Why do so many people learn foreign languages nowadays?", "model": {"answer": "Mostly because languages open doors. A good command of English can lead to better jobs, scholarships abroad and access to information that isn’t available in your own language. The internet has also made contact with other cultures part of daily life, so curiosity plays a part too. Once you’ve watched a subtitled film, you naturally want to understand it in the original, without anyone filtering it for you.", "phrases": [["open doors", "create new opportunities"], ["a good command of", "a high level of skill in"], ["part of daily life", "something normal that happens every day"], ["play a part", "contribute"], ["filter", "change or limit what reaches someone"]], "grammar": [{"pattern": "Noun clause as object", "use": "information + that + clause: relative pronoun", "example": "information that isn’t available in your own language", "try": "information that ______."}, {"pattern": "Once + present perfect", "use": "Once + you’ve + past participle, you + verb", "example": "Once you’ve watched a subtitled film, you naturally want to understand it in the original", "try": "Once you’ve ______, you naturally ______."}]}}, {"q": "What is the best way to learn a language, in your opinion?", "model": {"answer": "Combining several methods works best. Regular lessons give you structure, but immersion is what makes things stick: podcasts, reading what interests you and, above all, speaking with real people. The more you use the language outside the classroom, the faster you’ll improve. If I had to choose a single habit, it would be speaking daily, even for ten minutes, because that’s where fluency is built.", "phrases": [["structure", "an organised plan"], ["immersion", "being surrounded by the language you are learning"], ["stick", "stay in your memory"], ["above all", "most importantly"], ["fluency", "the ability to speak smoothly and easily"]], "grammar": [{"pattern": "The more... the faster", "use": "the + comparative + clause, the + comparative + clause", "example": "The more you use the language outside the classroom, the faster you’ll improve", "try": "The more you ______, the better you’ll ______."}, {"pattern": "Second conditional", "use": "If + past simple, it would be + noun", "example": "If I had to choose a single habit, it would be speaking daily", "try": "If I had to choose, it would be ______."}]}}, {"q": "Is it better to study a language alone or in a group?", "model": {"answer": "It depends on your goal. Studying alone suits grammar and vocabulary, because you can work at your own pace and repeat things as often as necessary. But if you’re aiming to speak, a group is far more effective: you get real conversation, instant feedback and the motivation that comes from other learners. Personally, I’d combine them, using a class for practice and self-study to consolidate what I’ve learnt.", "phrases": [["work at your own pace", "study at a speed that suits you"], ["far more effective", "much better at producing results"], ["instant feedback", "an immediate reaction to your work"], ["motivation", "the desire to keep going"], ["consolidate", "make stronger and more secure"]], "grammar": [{"pattern": "Participle after using", "use": "using + noun + for + noun: the way of doing something", "example": "using a class for practice and self-study to consolidate what I’ve learnt", "try": "I’d combine them, using ______ for ______."}, {"pattern": "Aim + -ing", "use": "be aiming to + base verb: a goal", "example": "if you’re aiming to speak", "try": "If you’re aiming to ______, ______."}]}}, {"q": "At what age is it best to start learning a foreign language?", "model": {"answer": "Earlier is generally better for pronunciation, as young children pick up sounds almost effortlessly. That said, adults aren’t at a disadvantage in every respect: they understand grammar rules and have clearer reasons to learn, so they often make rapid progress at first. I’d say starting at around six or seven is ideal, provided lessons are playful rather than pressured, and it’s never too late to begin.", "phrases": [["pick up", "learn without much effort"], ["effortlessly", "with no difficulty"], ["at a disadvantage", "in a weaker position"], ["make rapid progress", "improve quickly"], ["pressured", "made to feel stressed"]], "grammar": [{"pattern": "That said", "use": "That said, + clause: a concession", "example": "That said, adults aren’t at a disadvantage in every respect", "try": "That said, ______."}, {"pattern": "rather than", "use": "adjective + rather than + adjective", "example": "playful rather than pressured", "try": "lessons should be ______ rather than ______."}]}}, {"q": "Some people think that technology has made learning foreign languages unnecessary. What is your opinion?", "model": {"answer": "I’d strongly disagree, though I understand why people say it. Translation apps are excellent for getting by abroad, for instance when ordering a meal. But they can’t capture tone, humour or cultural nuance, and nobody builds a real friendship or negotiates a deal through a phone. Besides, speaking someone’s language builds trust in a way that no device can. So technology is a useful tool, not a replacement.", "phrases": [["get by", "manage with minimal ability"], ["nuance", "a small, subtle difference in meaning"], ["negotiate a deal", "discuss terms to reach an agreement"], ["build trust", "make people feel they can rely on you"], ["a useful tool", "something that helps but does not replace skill"]], "grammar": [{"pattern": "Strong disagreement with though", "use": "I’d strongly disagree, though + clause: softens", "example": "I’d strongly disagree, though I understand why people say it", "try": "I’d disagree, though ______."}, {"pattern": "in a way that", "use": "in a way that + clause: manner", "example": "in a way that no device can", "try": "______ in a way that ______."}]}}, {"q": "Do you think English will remain the world’s most important language?", "model": {"answer": "Probably, at least for the foreseeable future. English is so firmly rooted in science, business, aviation and the internet that replacing it would be enormously costly. Still, nothing lasts forever. Chinese or Spanish could gain ground, and machine translation may eventually reduce the need for a shared language. My guess is that English will stay on top for decades, though perhaps with less dominance than today.", "phrases": [["for the foreseeable future", "for as long as we can reasonably predict"], ["firmly rooted in", "deeply established in"], ["gain ground", "become more popular or powerful"], ["machine translation", "translation by computer software"], ["stay on top", "remain the leader"]], "grammar": [{"pattern": "so ... that", "use": "so + adjective + that + result", "example": "English is so firmly rooted in science, business, aviation and the internet that replacing it would be enormously costly", "try": "It is so ______ that ______."}, {"pattern": "Could for possibility", "use": "could + base verb: a real possibility", "example": "Chinese or Spanish could gain ground", "try": "______ could ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000018', 1018, 'Topic 18', 'Environmental law', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 18, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a law on environmental protection", "bullets": ["what the law is", "how you first learned about it", "who benefits from this law", "how you feel about it"], "explain": "", "notes": ["What The Law Is", "How I Learned", "Who Benefits", "Feelings"], "rounding": {"q": "Do you think a similar rule would work in your country?", "model": {"answer": "I think it could, as long as it was introduced gradually and shops offered cheap reusable bags. People here usually accept change when they can see the benefit, so some awareness campaigns would help.", "phrases": [], "grammar": []}}, "model": {"answer": "The law I’ve picked is one that requires shops to charge customers for plastic bags. As far as I know, it was first introduced in Ireland in the early 2000s, and a number of countries have since followed suit with similar rules. It sounds like a small thing, but it’s a good example of how legislation can bring about real change. I first came across it when I was on a two-week exchange in Dublin. At the supermarket checkout, the cashier asked whether I needed a bag, and when I said yes, she charged me extra. I was a bit taken aback and asked why, and she explained the whole thing with a smile, as if I’d asked a silly question. By the end of the week, I noticed I was carrying my own tote bag like everyone else, and I’d barely given it a second thought. Who benefits? Almost everyone, to be honest. The environment gains most, since fewer bags end up in rivers, parks and landfill, and wildlife is less at risk. Shops spend less on bags, and councils spend less on clean-ups. Even shoppers benefit in the long run, because reusing a bag saves a little money. I strongly approve of it. Some people grumbled that it was an inconvenience, but looking back at how quickly habits changed, I think it shows that a well-designed nudge can work better than a lecture. What I find encouraging is that nobody had to be punished; the law simply made the right choice the easy one. It’s certainly a step in the right direction, and I’d love to see something similar here.", "sections": [{"label": "What The Law Is", "text": "The law I’ve picked is one that requires shops to charge customers for plastic bags. As far as I know, it was first introduced in Ireland in the early 2000s, and a number of countries have since followed suit with similar rules. It sounds like a small thing, but it’s a good example of how legislation can bring about real change."}, {"label": "How I Learned", "text": "I first came across it when I was on a two-week exchange in Dublin. At the supermarket checkout, the cashier asked whether I needed a bag, and when I said yes, she charged me extra. I was a bit taken aback and asked why, and she explained the whole thing with a smile, as if I’d asked a silly question. By the end of the week, I noticed I was carrying my own tote bag like everyone else, and I’d barely given it a second thought."}, {"label": "Who Benefits", "text": "Who benefits? Almost everyone, to be honest. The environment gains most, since fewer bags end up in rivers, parks and landfill, and wildlife is less at risk. Shops spend less on bags, and councils spend less on clean-ups. Even shoppers benefit in the long run, because reusing a bag saves a little money."}, {"label": "Feelings", "text": "I strongly approve of it. Some people grumbled that it was an inconvenience, but looking back at how quickly habits changed, I think it shows that a well-designed nudge can work better than a lecture. What I find encouraging is that nobody had to be punished; the law simply made the right choice the easy one. It’s certainly a step in the right direction, and I’d love to see something similar here."}], "phrases": [["follow suit", "do the same as someone else has done"], ["bring about", "cause something to happen"], ["come across", "find or meet by chance"], ["taken aback", "surprised and slightly shocked"], ["not give it a second thought", "do something without thinking about it"], ["end up in", "finally arrive in a place, often unintentionally"], ["landfill", "a place where rubbish is buried"], ["in the long run", "over a long period of time"], ["grumble", "complain in a low, unhappy way"], ["nudge", "a small push that encourages a choice"], ["a step in the right direction", "progress towards a good goal"]], "grammar": [{"pattern": "Present perfect with since", "use": "have + since + past participle: a change from a past point until now", "example": "a number of countries have since followed suit", "try": "Many countries have since ______."}, {"pattern": "Indirect question with whether", "use": "asked + whether + clause (reported speech)", "example": "the cashier asked whether I needed a bag", "try": "She asked whether ______."}, {"pattern": "as if + past perfect", "use": "as if + had + past participle: an unreal comparison", "example": "as if I’d asked a silly question", "try": "He looked at me as if I’d ______."}, {"pattern": "Gerund as subject", "use": "-ing + noun + verb: an action as the subject", "example": "reusing a bag saves a little money", "try": "______ing ______ saves ______."}, {"pattern": "Participle clause", "use": "Looking back at + noun, I think...", "example": "looking back at how quickly habits changed, I think it shows", "try": "Looking back at ______, I think ______."}, {"pattern": "Cleft sentence with passive", "use": "What + I find + adjective + is that + clause", "example": "What I find encouraging is that nobody had to be punished", "try": "What I find encouraging is that ______."}]}}, "part3": {"intro": "We’ve been talking about a law on environmental protection, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Environmental law", "title": "Environmental law", "questions": [{"q": "Why do some people ignore rules that protect the environment?", "model": {"answer": "Often it’s a matter of convenience. If recycling means carrying waste to a distant bin, many people think, one bag won’t hurt, and they turn a blind eye to their own habits. Others assume the problem is too big for individuals to make an impact. And where enforcement is weak, rules lose credibility: if nobody gets caught for littering, it quickly becomes the norm.", "phrases": [["a matter of convenience", "something decided by what is easiest"], ["turn a blind eye", "pretend not to notice"], ["make an impact", "have a noticeable effect"], ["enforcement", "making sure rules are obeyed"], ["the norm", "what is normal and expected"]], "grammar": [{"pattern": "Conditional with means", "use": "If + present simple, ... means + -ing: explains consequence", "example": "If recycling means carrying waste to a distant bin, many people think, one bag won’t hurt", "try": "If recycling means ______ing, many people ______."}, {"pattern": "Where + clause", "use": "where + clause: in situations in which", "example": "where enforcement is weak, rules lose credibility", "try": "Where ______ is weak, ______."}]}}, {"q": "What can governments do to encourage people to protect the environment?", "model": {"answer": "They need both carrots and sticks. Tax breaks or subsidies for solar panels and electric cars make the greener option cheaper, while fines discourage the worst behaviour. Equally important is infrastructure, because people can’t recycle if there are no bins. Governments can also lead by example, for instance by running public buildings on renewable energy, and by funding awareness campaigns in schools and on television.", "phrases": [["carrots and sticks", "rewards and punishments"], ["subsidy", "money given by the government to lower prices"], ["infrastructure", "basic systems such as roads, bins and power"], ["lead by example", "behave in the way you want others to"], ["awareness campaign", "a public effort to inform people"]], "grammar": [{"pattern": "Both ... and", "use": "need both X and Y", "example": "They need both carrots and sticks", "try": "Governments need both ______ and ______."}, {"pattern": "because + clause", "use": "Equally important is + noun, because + clause", "example": "people can’t recycle if there are no bins", "try": "People can’t ______ if ______."}]}}, {"q": "Do you think heavy fines are an effective way to stop people breaking the law?", "model": {"answer": "Up to a point. A heavy fine can act as a deterrent, especially for individuals, but only if people believe they will actually be caught. A huge penalty that’s never enforced is meaningless. Fines alone also don’t change attitudes; they can simply drive the problem underground. So I’d say they work best hand in hand with education and regular inspections, rather than on their own.", "phrases": [["up to a point", "partly but not completely"], ["act as a deterrent", "discourage people from doing something"], ["penalty", "a punishment"], ["drive (a problem) underground", "make a problem hidden rather than solved"], ["hand in hand with", "together with"]], "grammar": [{"pattern": "Only if", "use": "only if + clause: the one condition", "example": "only if people believe they will actually be caught", "try": "It works only if ______."}, {"pattern": "A penalty that’s...", "use": "noun + that + passive: relative clause", "example": "A huge penalty that’s never enforced is meaningless", "try": "A rule that’s never ______ is ______."}]}}, {"q": "What rules do schools in your country have for students, and are they important?", "model": {"answer": "In many schools, students are expected to wear a uniform, arrive on time and switch off their phones during lessons, while bullying and cheating are taken very seriously. I’d say these rules matter because they teach responsibility and a sense of discipline, and they keep classrooms orderly, so everyone can learn. Of course, overly strict rules can backfire, so schools should explain the reasons behind them.", "phrases": [["be expected to", "be required by custom or rule"], ["take (something) seriously", "treat something as important"], ["a sense of discipline", "the habit of obeying rules and controlling yourself"], ["orderly", "calm and well organised"], ["overly strict", "too severe"]], "grammar": [{"pattern": "Passive with expected", "use": "be expected to + base verb", "example": "students are expected to wear a uniform, arrive on time and switch off their phones", "try": "Students are expected to ______."}, {"pattern": "so that purpose", "use": "clause + , so + subject + can + base verb", "example": "so everyone can learn", "try": "______, so everyone can ______."}]}}, {"q": "What can teachers do to make students follow school rules?", "model": {"answer": "The most effective thing is consistency. If a teacher applies the rules to everyone equally, students respect them. Explaining why a rule exists also helps, because teenagers are far more likely to comply once they see the point. Teachers should set a good example themselves, by arriving on time. And praise works wonders: rewarding good behaviour usually achieves more than coming down hard on every mistake.", "phrases": [["consistency", "behaving in the same way every time"], ["comply", "obey a rule"], ["see the point", "understand the purpose"], ["set a good example", "behave in a way others should copy"], ["work wonders", "have a very good effect"], ["come down hard on", "punish severely"]], "grammar": [{"pattern": "Zero/first conditional", "use": "If + present simple, + present simple: a general truth", "example": "If a teacher applies the rules to everyone equally, students respect them", "try": "If a teacher ______, students ______."}, {"pattern": "more than + -ing", "use": "usually achieves more than + -ing", "example": "rewarding good behaviour usually achieves more than coming down hard on every mistake", "try": "______ing achieves more than ______ing."}]}}, {"q": "Should companies be punished more severely than individuals for damaging the environment?", "model": {"answer": "In my view, yes, because the scale of damage is incomparable. A factory that pollutes a river can harm thousands of people, whereas an individual dropping litter does only minor harm. Companies also have the resources to cut corners and simply pay small fines as a cost of doing business. That said, punishment should be proportionate, and bosses who take responsibility and clean up quickly deserve some leniency.", "phrases": [["in my view", "in my opinion"], ["incomparable", "so different in size that no comparison is possible"], ["cut corners", "save money by doing something less carefully"], ["a cost of doing business", "an expense that a company accepts as normal"], ["leniency", "a less severe punishment"]], "grammar": [{"pattern": "whereas", "use": "A ..., whereas B: contrast", "example": "A factory that pollutes a river can harm thousands of people, whereas an individual dropping litter does only minor harm", "try": "______, whereas ______."}, {"pattern": "Relative clause with who", "use": "bosses + who + verb", "example": "bosses who take responsibility and clean up quickly deserve some leniency", "try": "People who ______ deserve ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000019', 1019, 'Topic 19', 'Special day out that didn’t cost a lot', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 19, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a special day out that didn’t cost a lot", "bullets": ["what you did", "when it was", "who you were with", "why it was special"], "explain": "", "notes": ["What", "When", "Who", "Why Special"], "rounding": {"q": "Do you often go out with friends like that at the weekend?", "model": {"answer": "Fairly often, especially in spring and autumn. We try to get out of the city at least once a month, because it’s cheap, healthy and a great way to catch up.", "phrases": [], "grammar": []}}, "model": {"answer": "The first thing that comes to mind is a day trip to Charvak Lake, about two hours from Tashkent. We didn’t splash out on anything. We took a shared minibus, packed our own lunch, and spent less than a single evening in a restaurant would have cost. It was a Saturday in late April, just as the long winter was coming to an end. The hills were covered in red tulips, which I’d been meaning to see for years, and it hadn’t rained for days, so the trails were dry. I went with my cousin Sardor and two friends from university. We’ve known each other for ages, so we can have a laugh about almost anything, and nobody felt the need to impress anyone. What made the day special was how laid-back it was. We set off along a trail at about nine, and no one was glued to their phone, partly because the signal kept dropping. Around noon we stumbled upon a flat rock beside a stream and ate sandwiches and boiled eggs, which was honestly the best meal I’d had in months. Had we spent more, I doubt we’d have enjoyed it any more. By the time we got home I was exhausted but on cloud nine. Looking back, it taught me that you don’t have to break the bank to make memories. Good company and a bit of fresh air do most of the work.", "sections": [{"label": "What", "text": "The first thing that comes to mind is a day trip to Charvak Lake, about two hours from Tashkent. We didn’t splash out on anything. We took a shared minibus, packed our own lunch, and spent less than a single evening in a restaurant would have cost."}, {"label": "When", "text": "It was a Saturday in late April, just as the long winter was coming to an end. The hills were covered in red tulips, which I’d been meaning to see for years, and it hadn’t rained for days, so the trails were dry."}, {"label": "Who", "text": "I went with my cousin Sardor and two friends from university. We’ve known each other for ages, so we can have a laugh about almost anything, and nobody felt the need to impress anyone."}, {"label": "Why Special", "text": "What made the day special was how laid-back it was. We set off along a trail at about nine, and no one was glued to their phone, partly because the signal kept dropping. Around noon we stumbled upon a flat rock beside a stream and ate sandwiches and boiled eggs, which was honestly the best meal I’d had in months. Had we spent more, I doubt we’d have enjoyed it any more. By the time we got home I was exhausted but on cloud nine."}, {"label": "Reflection", "text": "Looking back, it taught me that you don’t have to break the bank to make memories. Good company and a bit of fresh air do most of the work."}], "phrases": [["splash out", "spend a lot of money on something enjoyable"], ["come to an end", "finish"], ["know each other for ages", "have been friends for a very long time"], ["have a laugh", "enjoy joking together"], ["laid-back", "relaxed and informal"], ["set off", "start a journey"], ["be glued to your phone", "look at your phone all the time"], ["stumble upon", "find by chance"], ["on cloud nine", "extremely happy"], ["break the bank", "cost too much money"], ["make memories", "create experiences you will remember"]], "grammar": [{"pattern": "Inversion in a conditional", "use": "Had + subject + past participle, … would have + past participle", "example": "Had we spent more, I doubt we’d have enjoyed it any more", "try": "Had we ______, we would have ______."}, {"pattern": "Past perfect continuous", "use": "relative clause + I’d been meaning to + verb", "example": "which I’d been meaning to see for years", "try": "…, which I’d been meaning to ______ for years."}, {"pattern": "Cleft sentence with what", "use": "What made it + adjective + was + how + adjective", "example": "What made the day special was how laid-back it was", "try": "What made the day special was ______."}, {"pattern": "Superlative + past perfect", "use": "the best + noun + I’d + past participle", "example": "the best meal I’d had in months", "try": "the best ______ I’d ever had."}, {"pattern": "By the time", "use": "By the time + past simple, + past simple", "example": "By the time we got home I was exhausted", "try": "By the time we ______, I was ______."}, {"pattern": "Not have to … to …", "use": "you don’t have to + verb + to + verb", "example": "you don’t have to break the bank to make memories", "try": "You don’t have to ______ to ______."}]}}, "part3": {"intro": "We’ve been talking about a special day out that didn’t cost a lot, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Special day out that didn’t cost a lot", "title": "Special day out that didn’t cost a lot", "questions": [{"q": "How do people in your country usually spend their leisure time?", "model": {"answer": "It tends to revolve around family. At weekends, relatives get together for a long lunch, and the evening is a chance to catch up over tea. Younger people hang out in cafés or play football, and in summer anyone who can heads for the mountains to escape the heat. That said, a growing share of free time is being swallowed up by phones, which you see at every table.", "phrases": [["get together", "meet socially"], ["catch up", "talk about what has happened recently"], ["hang out", "spend relaxed time with friends"], ["escape the heat", "get away from very hot weather"], ["swallow up", "use up completely"]], "grammar": [{"pattern": "Concession with that said", "use": "That said, + contrasting point", "example": "That said, a growing share of free time is being swallowed up by phones", "try": "That said, ______."}, {"pattern": "Relative clause (anyone who)", "use": "anyone who + verb + main verb", "example": "anyone who can heads for the mountains", "try": "Anyone who ______ tends to ______."}]}}, {"q": "What leisure activities do older people prefer compared with younger people?", "model": {"answer": "Broadly speaking, older people favour quieter, more social pastimes, whereas the young go for things that are active or online. My grandfather, for instance, spends hours playing chess with neighbours in the courtyard, while my cousins would rather work out at the gym or binge-watch series. Not that the gap is absolute: my aunt, who’s in her fifties, has taken up hiking and puts me to shame.", "phrases": [["pastime", "a hobby or activity you do for pleasure"], ["work out", "exercise"], ["binge-watch", "watch many episodes in one go"], ["take up", "start a new hobby"], ["put someone to shame", "do something much better than them"]], "grammar": [{"pattern": "Contrast with whereas", "use": "A, whereas B", "example": "whereas the young go for things that are active or online", "try": "Older people ______, whereas the young ______."}, {"pattern": "Would rather", "use": "would rather + base verb", "example": "my cousins would rather work out at the gym", "try": "I would rather ______ than ______."}]}}, {"q": "How has technology changed the way people spend their free time?", "model": {"answer": "It has made free time richer but more passive. On the plus side, you can learn a language, keep in touch with friends abroad or stream a film without leaving home. The downside is that screens eat into the hours we used to spend outdoors. The more convenient entertainment becomes, the less people make the effort to go out, which takes a toll on health and friendships.", "phrases": [["on the plus side", "as a positive point"], ["keep in touch", "stay in contact"], ["eat into", "use up part of something valuable"], ["make the effort", "try hard to do something"], ["take a toll on", "have a harmful effect on"]], "grammar": [{"pattern": "The more… the less…", "use": "The more + subject + verb, the less + subject + verb", "example": "The more convenient entertainment becomes, the less people make the effort to go out", "try": "The more ______, the less ______."}, {"pattern": "Used to for past habit", "use": "the + noun + we used to + verb", "example": "the hours we used to spend outdoors", "try": "the time we used to ______."}]}}, {"q": "Is it important for everyone to have enough leisure time?", "model": {"answer": "Absolutely, and not only for individuals but for society as a whole. People who never switch off tend to burn out, and their work suffers, so rest actually pays for itself. Leisure also gives us room for friendships and hobbies, which give life a sense of purpose beyond a job. The trouble is that long hours or caring for young children leave some people with almost none.", "phrases": [["switch off", "relax and stop thinking about work"], ["burn out", "become exhausted from too much stress"], ["pay for itself", "give back as much as it costs"], ["a sense of purpose", "a feeling that life has meaning"], ["long hours", "a lot of working time each day"]], "grammar": [{"pattern": "Non-defining relative clause", "use": "…, which + verb", "example": "friendships and hobbies, which give life a sense of purpose beyond a job", "try": "…, which ______."}, {"pattern": "Not only … but …", "use": "not only for + A but for + B", "example": "not only for individuals but for society as a whole", "try": "not only for ______ but also for ______."}]}}, {"q": "Do you think people can enjoy themselves without spending much money?", "model": {"answer": "Definitely, and some of my happiest days have cost next to nothing. A picnic, a walk in the park or cooking with friends is remembered far longer than an expensive night out. If anything, spending a lot can backfire, because you start worrying about getting your money’s worth instead of relaxing. What matters is the company, not the price tag, and good conversation is free.", "phrases": [["cost next to nothing", "be almost free"], ["backfire", "have the opposite result to the one you wanted"], ["get your money’s worth", "receive good value for what you paid"], ["price tag", "the cost of something"], ["a night out", "an evening spent in restaurants, cafés or clubs"]], "grammar": [{"pattern": "Cleft sentence with what", "use": "What + verb + is + noun, not + noun", "example": "What matters is the company, not the price tag", "try": "What matters is ______, not ______."}, {"pattern": "Passive with comparative", "use": "is + past participle + far longer than", "example": "is remembered far longer than an expensive night out", "try": "______ is remembered far longer than ______."}]}}, {"q": "Do people have more leisure time now than they did in the past?", "model": {"answer": "It depends on whom you ask. Machines have freed up hours that our grandparents spent on housework, so on paper we should have more time. In practice, though, many people feel stretched thin, since smartphones mean work follows them home. Had I lived a century ago, I’d have worked harder physically, but I’d probably have clocked off properly at the end of the day.", "phrases": [["free up", "make time or space available"], ["on paper", "in theory"], ["stretched thin", "having too many things to do"], ["clock off", "finish work for the day"], ["follow someone home", "continue to affect someone after work"]], "grammar": [{"pattern": "Third conditional with inversion", "use": "Had + subject + past participle, … would have + past participle", "example": "Had I lived a century ago, I’d have worked harder physically", "try": "Had I ______, I’d have ______."}, {"pattern": "Present perfect vs past", "use": "Machines have + past participle + that + subject + past", "example": "Machines have freed up hours that our grandparents spent on housework", "try": "Technology has ______ hours that people used to spend on ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000020', 1020, 'Topic 20', 'Organizing a happy event', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 20, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a time when you organised a happy event successfully", "bullets": ["what the event was", "when and where it took place", "whether it was easy or difficult to organise", "and explain how you prepared for it"], "explain": "", "notes": ["What", "When & Where", "Easy Or Difficult", "Preparatio N"], "rounding": {"q": "Would you organise something like that again?", "model": {"answer": "Definitely. It was exhausting, but seeing my parents so happy made it worthwhile, and next time I’d start the planning even earlier.", "phrases": [], "grammar": []}}, "model": {"answer": "One occasion I’ll never forget is the surprise party I organised for my parents’ twenty-fifth wedding anniversary. My father had always claimed he hated fuss, so I knew it had to be a low-key affair, but I wanted it to feel genuinely special. It took place on a warm evening in June, in the garden of a small family restaurant in Samarkand where, as it happens, my parents had had their first date. About thirty relatives came. To be fair, it was harder than I’d expected. The biggest challenge was keeping it under wraps, because my mother can read me like a book. Every time she asked why I was phoning my aunts so often, I had to come up with a new excuse. I began planning about two months ahead. I booked the venue, drew up a guest list, and asked my brother to put together a slideshow of old photos. On the day, my cousin took my parents out for a drive, supposedly to buy a gift, so that the rest of us could set everything up. When they walked in and everyone shouted “Surprise!”, Mum burst into tears, and Dad, the man who hated fuss, was grinning from ear to ear. Never had I seen him so lost for words. What struck me was that the success had less to do with money than with attention to detail: if I hadn’t double-checked the timings, the cake would have arrived an hour late. It taught me that the best events aren’t the most expensive ones, but the ones that reflect the people they’re for.", "sections": [{"label": "What", "text": "One occasion I’ll never forget is the surprise party I organised for my parents’ twenty-fifth wedding anniversary. My father had always claimed he hated fuss, so I knew it had to be a low-key affair, but I wanted it to feel genuinely special."}, {"label": "When & Where", "text": "It took place on a warm evening in June, in the garden of a small family restaurant in Samarkand where, as it happens, my parents had had their first date. About thirty relatives came."}, {"label": "Easy Or Difficult", "text": "To be fair, it was harder than I’d expected. The biggest challenge was keeping it under wraps, because my mother can read me like a book. Every time she asked why I was phoning my aunts so often, I had to come up with a new excuse."}, {"label": "Preparatio N", "text": "I began planning about two months ahead. I booked the venue, drew up a guest list, and asked my brother to put together a slideshow of old photos. On the day, my cousin took my parents out for a drive, supposedly to buy a gift, so that the rest of us could set everything up. When they walked in and everyone shouted “Surprise!”, Mum burst into tears, and Dad, the man who hated fuss, was grinning from ear to ear. Never had I seen him so lost for words. What struck me was that the success had less to do with money than with attention to detail: if I hadn’t double-checked the timings, the cake would have arrived an hour late."}, {"label": "Reflection", "text": "It taught me that the best events aren’t the most expensive ones, but the ones that reflect the people they’re for."}], "phrases": [["low-key", "simple and quiet, not showy"], ["keep something under wraps", "keep it secret"], ["read someone like a book", "understand exactly what someone is thinking"], ["come up with", "think of an idea or excuse"], ["draw up", "prepare a list or plan in writing"], ["put together", "create by combining things"], ["set up", "arrange and prepare"], ["grin from ear to ear", "smile very widely"], ["lost for words", "too surprised to speak"], ["attention to detail", "care about small points"], ["double-check", "check again to be sure"], ["reflect", "show or represent clearly"]], "grammar": [{"pattern": "Past perfect for earlier events", "use": "where + subject + had had", "example": "where, as it happens, my parents had had their first date", "try": "where my parents had ______."}, {"pattern": "Inversion with never", "use": "Never had + subject + past participle", "example": "Never had I seen him so lost for words", "try": "Never had I ______ so ______."}, {"pattern": "Cleft sentence with what", "use": "What struck me was that + clause", "example": "What struck me was that the success had less to do with money than with attention to detail", "try": "What struck me was that ______."}, {"pattern": "Third conditional", "use": "if + past perfect, would have + past participle", "example": "if I hadn’t double-checked the timings, the cake would have arrived an hour late", "try": "If I hadn’t ______, ______ would have ______."}, {"pattern": "Non-defining relative clause with", "use": "person Dad, the man who + verb, + main clause", "example": "Dad, the man who hated fuss, was grinning from ear to ear", "try": "My uncle, the man who ______, ______."}, {"pattern": "Less … than …", "use": "had less to do with A than with B", "example": "had less to do with money than with attention to detail", "try": "It had less to do with ______ than with ______."}]}}, "part3": {"intro": "We’ve been talking about a time when you organised a happy event successfully, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Organizing a happy event", "title": "Organizing a happy event", "questions": [{"q": "What do people need to consider when they organise an event?", "model": {"answer": "First and foremost, the budget and the guest list, because everything else follows from those two. After that, logistics matter: a venue that is easy to reach, enough food, and a backup plan in case the weather lets you down. What people often overlook is the guests’ needs, such as dietary restrictions or elderly relatives who can’t climb stairs. A beautiful event that leaves guests uncomfortable has missed the point.", "phrases": [["first and foremost", "most importantly"], ["logistics", "practical arrangements such as transport and timing"], ["backup plan", "an alternative plan if the first one fails"], ["let someone down", "fail to do what is hoped for"], ["overlook", "fail to notice or consider"], ["miss the point", "fail to understand what is most important"]], "grammar": [{"pattern": "Cleft sentence with what", "use": "What + subject + verb + is + noun", "example": "What people often overlook is the guests’ needs", "try": "What people often forget is ______."}, {"pattern": "Relative clause with who", "use": "noun + who + can’t + verb", "example": "elderly relatives who can’t climb stairs", "try": "guests who ______."}]}}, {"q": "Why do some people enjoy organising events while others find it stressful?", "model": {"answer": "It largely comes down to personality and control. Some people thrive on juggling details and watching a plan come together, whereas perfectionists tend to stress out, because one small mistake feels like a disaster. Experience matters too: the more events you’ve run, the better you get at staying calm when things go wrong. Nobody enjoys a last-minute crisis, but experienced organisers simply expect one.", "phrases": [["come down to", "depend mainly on"], ["thrive on", "enjoy and do well in a challenging situation"], ["stress out", "become very anxious"], ["go wrong", "not happen as planned"], ["last-minute", "happening at the final moment"]], "grammar": [{"pattern": "The more… the better…", "use": "The more + subject + have + past participle, the better + subject + verb", "example": "the more events you’ve run, the better you get at staying calm", "try": "The more ______ you’ve ______, the better ______."}, {"pattern": "Contrast with whereas", "use": "A, whereas B", "example": "whereas perfectionists tend to stress out", "try": "Some people ______, whereas others ______."}]}}, {"q": "Is it better to hire a professional to organise a big event?", "model": {"answer": "For a wedding or a conference, yes, since professionals have contacts and know-how that save both time and money. They also take the pressure off the family, who can enjoy the day. For a birthday or a small gathering, though, I’d rather do it myself, because a personal touch is what people remember. It’s a question of scale and budget, and whether you can afford to hand it over.", "phrases": [["know-how", "practical knowledge and skill"], ["take the pressure off", "make someone feel less stressed"], ["a personal touch", "something that shows individual care"], ["scale", "the size of something"], ["hand over", "give responsibility to someone else"]], "grammar": [{"pattern": "Relative clause with who", "use": "noun + , who + verb", "example": "the family, who can enjoy the day", "try": "______, who can ______."}, {"pattern": "Reduced contrast with though", "use": "For A, yes. For B, though, + clause", "example": "For a birthday or a small gathering, though, I’d rather do it myself", "try": "For ______, though, I’d rather ______."}]}}, {"q": "How can parents help children to become more organised?", "model": {"answer": "By giving them small responsibilities from an early age and letting them take ownership. A child who packs their own school bag, even if they forget something once, learns far more than one whose parents do everything. Routines help too, so children get into the habit of doing homework at fixed times. If parents step in every time, children never learn from their mistakes, which is how these skills develop.", "phrases": [["from an early age", "when very young"], ["take ownership", "accept responsibility for something"], ["get into the habit", "start doing something regularly"], ["step in", "become involved to help or solve a problem"], ["learn from your mistakes", "improve by understanding what went wrong"]], "grammar": [{"pattern": "Relative clause with whose", "use": "one whose parents + verb", "example": "one whose parents do everything", "try": "a child whose parents ______."}, {"pattern": "First conditional with never", "use": "If + present simple, + will/never + verb", "example": "If parents step in every time, children never learn from their mistakes", "try": "If parents ______ every time, children ______."}]}}, {"q": "What kinds of events do families in your country usually organise?", "model": {"answer": "Weddings are by far the biggest, and they’re often a family affair involving dozens of relatives and weeks of preparation. There are also birthdays, celebrations for newborn babies and religious holidays like Eid, when families get together for a large meal. Even a modest occasion tends to turn into a gathering with neighbours, and no guest is expected to leave empty-handed.", "phrases": [["a family affair", "an event involving the whole family"], ["get together", "meet socially"], ["turn into", "gradually become"], ["leave empty-handed", "leave without taking anything"], ["by far the biggest", "much bigger than any other"]], "grammar": [{"pattern": "Participle clause", "use": "noun + involving + noun", "example": "a family affair involving dozens of relatives", "try": "an event involving ______."}, {"pattern": "Passive with expected", "use": "no + noun + is expected to + verb", "example": "no guest is expected to leave empty-handed", "try": "Nobody is expected to ______."}]}}, {"q": "Has technology made it easier to organise events?", "model": {"answer": "Enormously. Not long ago you had to phone every guest and write down the replies; now a group chat does it in minutes. Apps also help you compare prices for venues and keep track of the budget. The flip side is that technology raises the bar: guests expect a polished event, with professional photos shared instantly. So it’s easier to organise, but not necessarily less work, and certainly not foolproof.", "phrases": [["compare prices", "check costs of different options"], ["keep track of", "follow and record"], ["raise the bar", "make standards higher"], ["polished", "carefully prepared and professional"], ["foolproof", "impossible to go wrong"]], "grammar": [{"pattern": "Contrast with not necessarily", "use": "easier …, but not necessarily + comparative", "example": "easier to organise, but not necessarily less work", "try": "easier, but not necessarily ______."}, {"pattern": "Not long ago + past obligation", "use": "you had to + verb", "example": "you had to phone every guest and write down the replies", "try": "Not long ago you had to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000021', 1021, 'Topic 21', 'Traffic jam', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 21, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an occasion when you got stuck in a traffic jam", "bullets": ["where you were going", "when it happened", "how long you were stuck", "and explain how you felt about it"], "explain": "", "notes": ["Where", "When", "How Long", "Feelings"], "rounding": {"q": "Do you try to avoid travelling at rush hour now?", "model": {"answer": "Whenever I can. I leave earlier than necessary and I use the metro, because it’s less stressful to arrive early than to sit in traffic.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about the day I nearly missed a flight because of a traffic jam. I was heading to Tashkent airport at about five in the afternoon, on my way to Istanbul for a friend’s graduation. I’d allowed plenty of time, or so I thought, since the flight wasn’t until eight. It was a Friday in October, and rush hour was in full swing, which should have rung alarm bells. On top of that, it had been pouring all afternoon, and there’d been a collision on the ring road, so the traffic came to a standstill. We were stuck for nearly two hours, crawling along at walking pace and then not moving at all. The driver kept honking and drumming his fingers on the wheel, which didn’t exactly help. I refreshed my boarding pass every five minutes, as if that would speed things up. At first I was merely annoyed, but as the minutes ticked by, I started to panic. What made it worse was the sense of helplessness; there was literally nothing I could do. Eventually we got through the bottleneck, and I sprinted to check-in with fifteen minutes to spare, drenched in sweat. The agent smiled and said, “You’re lucky, the flight’s been delayed.” Had I left an hour earlier, none of it would have happened. Since then I always leave a margin for the unexpected, and I take the metro whenever I can. It taught me that being on time isn’t about speed; it’s about planning for the things you can’t control.", "sections": [{"label": "Where", "text": "Let me tell you about the day I nearly missed a flight because of a traffic jam. I was heading to Tashkent airport at about five in the afternoon, on my way to Istanbul for a friend’s graduation. I’d allowed plenty of time, or so I thought, since the flight wasn’t until eight."}, {"label": "When", "text": "It was a Friday in October, and rush hour was in full swing, which should have rung alarm bells. On top of that, it had been pouring all afternoon, and there’d been a collision on the ring road, so the traffic came to a standstill."}, {"label": "How Long", "text": "We were stuck for nearly two hours, crawling along at walking pace and then not moving at all. The driver kept honking and drumming his fingers on the wheel, which didn’t exactly help. I refreshed my boarding pass every five minutes, as if that would speed things up."}, {"label": "Feelings", "text": "At first I was merely annoyed, but as the minutes ticked by, I started to panic. What made it worse was the sense of helplessness; there was literally nothing I could do. Eventually we got through the bottleneck, and I sprinted to check-in with fifteen minutes to spare, drenched in sweat. The agent smiled and said, “You’re lucky, the flight’s been delayed.” Had I left an hour earlier, none of it would have happened. Since then I always leave a margin for the unexpected, and I take the metro whenever I can."}, {"label": "Reflection", "text": "It taught me that being on time isn’t about speed; it’s about planning for the things you can’t control."}], "phrases": [["allow plenty of time", "plan more time than you need"], ["rush hour", "the busiest travel time of day"], ["in full swing", "at its busiest"], ["ring alarm bells", "make you suspect a problem"], ["come to a standstill", "stop completely"], ["crawl along", "move very slowly"], ["speed things up", "make something happen faster"], ["tick by", "pass slowly"], ["panic", "feel sudden fear and be unable to think calmly"], ["get through", "pass through a difficult place or situation"], ["drenched in sweat", "extremely sweaty"], ["leave a margin", "allow extra time or space for problems"]], "grammar": [{"pattern": "Past perfect", "use": "I’d + past participle (earlier past)", "example": "I’d allowed plenty of time", "try": "I’d ______ plenty of time."}, {"pattern": "Past perfect continuous", "use": "it had been + -ing + time", "example": "it had been pouring all afternoon", "try": "It had been ______ all morning."}, {"pattern": "Non-defining relative clause", "use": "…, which + would/should have + past participle", "example": "which should have rung alarm bells", "try": "…, which should have ______."}, {"pattern": "As if + would", "use": "as if + that + would + verb", "example": "as if that would speed things up", "try": "as if that would ______."}, {"pattern": "Third conditional with inversion", "use": "Had + subject + past participle, … would have + past participle", "example": "Had I left an hour earlier, none of it would have happened", "try": "Had I ______, ______ would have ______."}, {"pattern": "Cleft sentence", "use": "What made it worse was + noun", "example": "What made it worse was the sense of helplessness", "try": "What made it worse was ______."}]}}, "part3": {"intro": "We’ve been talking about an occasion when you got stuck in a traffic jam, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Traffic jam", "title": "Traffic jam", "questions": [{"q": "Would you rather be stuck in a traffic jam in a car or on a bus?", "model": {"answer": "The bus, without hesitation. In a car you’re behind the wheel, getting angrier by the minute, whereas on a bus you can read, answer messages or simply zone out. In some cities buses even use dedicated lanes, so they may move faster than cars. The one drawback is the lack of privacy and the heat in summer, when a crowded bus can be unbearable.", "phrases": [["behind the wheel", "driving"], ["zone out", "stop paying attention and relax mentally"], ["dedicated lane", "a road lane used only by certain vehicles"], ["move faster", "travel more quickly"], ["unbearable", "too unpleasant to tolerate"]], "grammar": [{"pattern": "Contrast with whereas", "use": "A, whereas B", "example": "whereas on a bus you can read, answer messages or simply zone out", "try": "In a car you ______, whereas on a bus ______."}, {"pattern": "Relative clause with when", "use": "summer, when + clause", "example": "in summer, when a crowded bus can be unbearable", "try": "in ______, when ______."}]}}, {"q": "What are the main causes of traffic jams in cities?", "model": {"answer": "There are several, but the root cause is that too many cars compete for limited road space. Rising incomes mean more families own a car, while many roads were designed decades ago. Add poor traffic management, illegal parking and roadworks, and a single accident can bring a whole district to a halt. Rush hour, when everyone travels at once, simply makes things worse.", "phrases": [["compete for", "try to get the same limited thing"], ["poor traffic management", "badly organised control of traffic"], ["roadworks", "repairs being done on the road"], ["bring something to a halt", "stop it completely"], ["root cause", "the basic underlying reason"]], "grammar": [{"pattern": "Passive past", "use": "were + designed", "example": "many roads were designed decades ago", "try": "Many roads were ______ decades ago."}, {"pattern": "Imperative as conditional", "use": "Add A and B, and + clause", "example": "Add poor traffic management, illegal parking and roadworks, and a single accident can bring a whole district to a halt", "try": "Add ______, and ______."}]}}, {"q": "What can governments do to reduce traffic congestion?", "model": {"answer": "They could start by investing in reliable public transport, since people only leave their cars at home if the alternative is genuinely better. Congestion charges, like the one in London, make drivers think twice about entering the centre. Governments can also stagger working hours and build cycle lanes. Taken together, such measures work best, because people need both a carrot and a stick.", "phrases": [["invest in", "spend money on something to improve it"], ["think twice", "consider carefully before acting"], ["stagger working hours", "start and finish work at different times"], ["cycle lane", "a road lane for bicycles"], ["a carrot and a stick", "a reward together with a punishment"]], "grammar": [{"pattern": "Participle clause", "use": "Taken together, + clause", "example": "Taken together, such measures work best", "try": "Taken together, ______."}, {"pattern": "Only … if …", "use": "people only + verb + if + clause", "example": "people only leave their cars at home if the alternative is genuinely better", "try": "People only ______ if ______."}]}}, {"q": "Do you think building more roads solves traffic problems?", "model": {"answer": "Rarely, and not for long. New roads attract extra traffic, so within a few years they’re as congested as the old ones; economists call this induced demand. Wider roads can help at a genuine bottleneck, but they’re a short-term fix, not a long-term solution. A far better approach is to make public transport attractive, so that people choose it voluntarily rather than being forced out of their cars.", "phrases": [["induced demand", "extra demand created by improved supply"], ["bottleneck", "a narrow point where traffic slows"], ["short-term fix", "a quick solution that does not last"], ["long-term solution", "a solution that works for many years"], ["make something attractive", "make people want to use it"]], "grammar": [{"pattern": "Comparison as … as", "use": "as + adjective + as", "example": "they’re as congested as the old ones", "try": "They’re as ______ as ______."}, {"pattern": "So that", "use": "so that + clause", "example": "so that people choose it voluntarily", "try": "…, so that people ______."}]}}, {"q": "Would more people use public transport if it were free?", "model": {"answer": "Some would, certainly, but I doubt it would be a game-changer on its own. Cost matters less than convenience: if buses are crowded, infrequent and slow, people will stick to their cars, free or not. On the other hand, students and low-income families would benefit, and it might tempt occasional drivers. If the service were free and reliable, I think many more people would make the switch.", "phrases": [["game-changer", "something that changes a situation completely"], ["stick to", "continue using"], ["low-income family", "a family with little money"], ["make the switch", "change from one thing to another"], ["infrequent", "not happening often"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "If the service were free and reliable, I think many more people would make the switch", "try": "If it were ______, people would ______."}, {"pattern": "Less … than …", "use": "matters less than", "example": "Cost matters less than convenience", "try": "______ matters less than ______."}]}}, {"q": "What improvements does public transport need in your country?", "model": {"answer": "Reliability, first of all. Buses that turn up on time and show where they are on an app would win people back. On some routes, vehicles are also overcrowded and old, so newer, air-conditioned ones are needed, along with better links between metro and bus lines. Safer, well-lit stops matter too, particularly for women travelling at night. In short, frequency and comfort both have to improve.", "phrases": [["win people back", "persuade people to return"], ["overcrowded", "with too many people"], ["well-lit", "with good lighting"], ["frequency", "how often something happens"], ["links", "connections between routes"]], "grammar": [{"pattern": "Relative clause with that", "use": "Buses that + verb + would + verb", "example": "Buses that turn up on time and show where they are on an app would win people back", "try": "Buses that ______ would ______."}, {"pattern": "Both … and …", "use": "both A and B have to + verb", "example": "frequency and comfort both have to improve", "try": "______ and ______ both have to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000022', 1022, 'Topic 22', 'Long-term goal', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 22, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a long-term goal you would like to achieve", "bullets": ["what it is", "how long you have had it", "how you will achieve it", "why you set this goal"], "explain": "", "notes": ["What", "How Long", "How", "Why"], "rounding": {"q": "Have you told your family about this goal?", "model": {"answer": "Yes, they’ve been very supportive. My parents don’t fully understand economics, but they respect the effort, and my younger brother has even started copying my study routine.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one long-term goal, it would be to earn a master’s degree in economics abroad and, eventually, to teach at a university in Uzbekistan. It sounds ambitious, but I’ve set my heart on it. I’ve had this goal since I was sixteen. My economics teacher, Mr Karimov, once spent an entire lesson explaining why the price of bread had risen, and for the first time a school subject made sense of the world around me. That moment planted the seed, and it has stuck with me ever since. To get there, I’ve broken the goal down into milestones. I’m in my third year, so my first priority is to keep my grades up. I’m also preparing for the IELTS, because most scholarships ask for a high score. Next year I plan to apply for several of them, and meanwhile I’m building a track record by writing small research papers and tutoring younger students. If everything goes to plan, I’ll be starting my master’s in about two years. Of course there will be setbacks: I may not win the first scholarship I apply for, in which case I’ll simply try again. As for why, it’s partly personal and partly practical. Economics fascinates me, but I also believe a country’s growth depends on well-trained people, and I’d love to give something back. Having a clear goal keeps me on track on the days when I’d rather put things off. Whatever happens, I know the journey itself will have been worthwhile, because it’s already changed the way I study.", "sections": [{"label": "What", "text": "If I had to pick one long-term goal, it would be to earn a master’s degree in economics abroad and, eventually, to teach at a university in Uzbekistan. It sounds ambitious, but I’ve set my heart on it."}, {"label": "How Long", "text": "I’ve had this goal since I was sixteen. My economics teacher, Mr Karimov, once spent an entire lesson explaining why the price of bread had risen, and for the first time a school subject made sense of the world around me. That moment planted the seed, and it has stuck with me ever since."}, {"label": "How", "text": "To get there, I’ve broken the goal down into milestones. I’m in my third year, so my first priority is to keep my grades up. I’m also preparing for the IELTS, because most scholarships ask for a high score. Next year I plan to apply for several of them, and meanwhile I’m building a track record by writing small research papers and tutoring younger students. If everything goes to plan, I’ll be starting my master’s in about two years. Of course there will be setbacks: I may not win the first scholarship I apply for, in which case I’ll simply try again."}, {"label": "Why", "text": "As for why, it’s partly personal and partly practical. Economics fascinates me, but I also believe a country’s growth depends on well-trained people, and I’d love to give something back. Having a clear goal keeps me on track on the days when I’d rather put things off."}, {"label": "Reflection", "text": "Whatever happens, I know the journey itself will have been worthwhile, because it’s already changed the way I study."}], "phrases": [["set your heart on", "want something very much and decide to get it"], ["make sense of", "help you understand"], ["plant the seed", "start an idea that grows later"], ["stick with someone", "stay in someone’s mind"], ["milestone", "an important stage on the way to a goal"], ["keep your grades up", "maintain good marks"], ["apply for", "make a formal request for"], ["build a track record", "gradually create a history of achievements"], ["setback", "a problem that delays progress"], ["give something back", "do something good in return for what you’ve received"], ["on track", "progressing as planned"], ["put things off", "delay doing things"]], "grammar": [{"pattern": "Present perfect", "use": "I’ve + past participle + since + time", "example": "I’ve had this goal since I was sixteen", "try": "I’ve ______ since I was ______."}, {"pattern": "Past perfect in reported cause", "use": "explaining why + subject + had + past participle", "example": "explaining why the price of bread had risen", "try": "explaining why ______ had ______."}, {"pattern": "Participle clause of means", "use": "by + -ing", "example": "by writing small research papers and tutoring younger students", "try": "I’m improving by ______ and ______."}, {"pattern": "First conditional", "use": "If + present simple, + will + verb", "example": "If everything goes to plan, I’ll be starting my master’s in about two years", "try": "If everything goes to plan, I’ll ______."}, {"pattern": "Relative clause with in which", "use": "in which case + clause", "example": "in which case I’ll simply try again", "try": "…, in which case I’ll ______."}, {"pattern": "Would rather", "use": "I’d rather + base verb", "example": "on the days when I’d rather put things off", "try": "on days when I’d rather ______."}]}}, "part3": {"intro": "We’ve been talking about a long-term goal you would like to achieve, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Long-term goal", "title": "Long-term goal", "questions": [{"q": "Why do people set goals for themselves?", "model": {"answer": "Because a goal turns a vague wish into a plan. Without one, it’s easy to drift from day to day and lose sight of what matters. Goals also give us something to measure progress against, which is motivating in itself. When I started tracking my vocabulary targets, for instance, I noticed I was learning faster, because I knew what I was aiming for. A goal gives effort a direction.", "phrases": [["drift", "move along without direction"], ["lose sight of", "forget or stop paying attention to"], ["aim for", "try to achieve"], ["measure progress", "check how far you have advanced"], ["direction", "a clear purpose or path"]], "grammar": [{"pattern": "Because + clause", "use": "Because + subject + verb", "example": "Because a goal turns a vague wish into a plan", "try": "Because ______ turns ______ into ______."}, {"pattern": "Past continuous + because", "use": "I noticed I was + -ing, simply because + clause", "example": "I noticed I was learning faster, because I knew what I was aiming for", "try": "I noticed I was ______, simply because ______."}]}}, {"q": "Why is it important for teenagers to have goals?", "model": {"answer": "It’s a time of big decisions, such as choosing subjects and universities, so having a rough direction helps teenagers make informed choices. Goals also channel their energy into something constructive and protect them from peer pressure. That said, they shouldn’t be too rigid: a teenager who is forced down one path may resent it later, and flexibility is just as valuable.", "phrases": [["make an informed choice", "decide after thinking about the facts"], ["channel energy", "direct effort towards something useful"], ["peer pressure", "influence from people of the same age"], ["rigid", "unable to change"], ["resent", "feel angry about something unfair"]], "grammar": [{"pattern": "Participle clause", "use": "such as + -ing", "example": "such as choosing subjects and universities", "try": "big decisions, such as ______."}, {"pattern": "Passive with relative clause", "use": "a teenager who is forced + preposition", "example": "a teenager who is forced down one path may resent it later", "try": "a teenager who is forced to ______ may ______."}]}}, {"q": "Should parents encourage their children to have ambitions?", "model": {"answer": "Yes, as long as the ambitions are the child’s own. Parents who support their children’s interests boost their confidence, whereas those who impose their own dreams, such as insisting on medicine or law, often cause resentment. The best approach, in my experience, is to ask questions rather than give orders, and to praise effort rather than results. That way, ambition feels like a choice, not a burden.", "phrases": [["boost confidence", "make someone feel more sure of themselves"], ["impose your dreams on", "force your own wishes on someone"], ["ask questions", "show interest by asking, not telling"], ["praise effort", "say well done for trying hard"], ["burden", "a heavy responsibility"]], "grammar": [{"pattern": "As long as", "use": "as long as + clause", "example": "as long as the ambitions are the child’s own", "try": "as long as ______."}, {"pattern": "Rather than + base verb", "use": "to + verb rather than + verb", "example": "to ask questions rather than give orders", "try": "to ______ rather than ______."}]}}, {"q": "At what age do children start thinking about their future careers?", "model": {"answer": "Surprisingly early. Children as young as five or six announce that they want to be a doctor or a footballer, copying role models they see around them. Those ideas are fanciful and tend to change, but they lay the foundations for thinking. More realistic planning begins around fifteen or sixteen, when subject choices narrow down the options, and it starts to dawn on them that a career takes work.", "phrases": [["role model", "a person whose behaviour others copy"], ["lay the foundations", "create the basis for something"], ["narrow down", "reduce the number of choices"], ["it dawns on someone", "someone gradually realises"], ["as young as", "even at a very early age"]], "grammar": [{"pattern": "As young as", "use": "as young as + age", "example": "Children as young as five or six announce that they want to be a doctor", "try": "Children as young as ______ already ______."}, {"pattern": "Participle clause", "use": "…, + -ing + noun", "example": "copying role models they see around them", "try": "…, copying ______."}]}}, {"q": "Do you think people should change their goals as they get older?", "model": {"answer": "Often, yes, because priorities shift as we gain experience. A twenty-year-old may chase promotions, while someone with a family might value stability. Adjusting a goal isn’t the same as giving up; it simply means you’ve learned something about yourself. The key is to change goals deliberately, not on a whim when things get hard, and to avoid sticking to an old plan just out of pride.", "phrases": [["priorities shift", "what matters most changes"], ["chase", "try hard to get"], ["give up", "stop trying"], ["on a whim", "suddenly and without careful thought"], ["stick to", "continue with"]], "grammar": [{"pattern": "Present perfect", "use": "you’ve + past participle", "example": "you’ve learned something about yourself", "try": "It means you’ve ______."}, {"pattern": "Gerund as subject", "use": "-ing + isn’t the same as + -ing", "example": "Adjusting a goal isn’t the same as giving up", "try": "______-ing isn’t the same as ______-ing."}]}}, {"q": "What can people do to stay motivated when they are working towards a long-term goal?", "model": {"answer": "Breaking the goal into small, visible steps is the most effective method I know. Ticking off a weekly target gives you a sense of achievement that keeps you going. It also helps to surround yourself with people who share your aims, and to reward yourself occasionally. And when motivation dips, which it inevitably will, rely on habit: if studying is part of your routine, you don’t need willpower.", "phrases": [["tick off", "mark as completed"], ["a sense of achievement", "a feeling of having done something well"], ["surround yourself with", "stay close to"], ["reward yourself", "give yourself a treat for success"], ["dip", "go down for a short time"]], "grammar": [{"pattern": "Gerund as subject", "use": "Breaking + noun + into + noun + is + superlative", "example": "Breaking the goal into small, visible steps is the most effective method I know", "try": "______-ing ______ is the most effective way to ______."}, {"pattern": "Non-defining relative clause", "use": "…, which it inevitably will", "example": "which it inevitably will", "try": "…, which ______ inevitably will."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000023', 1023, 'Topic 23', 'Person who faced difficulties but succeeded', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 23, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person you know who faced difficulties but succeeded", "bullets": ["who this person is", "what difficulties this person faced", "how this person overcame them", "and explain why you admire this person"], "explain": "", "notes": ["Who", "Difficultie S", "How She Overcame", "Them"], "rounding": {"q": "Do you see her often?", "model": {"answer": "Quite often. We visit Namangan every summer, and I always come back with a bag of her sewing and some good advice.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be my aunt Gulnora, my mother’s younger sister, who lives in Namangan. She’s in her fifties now, with a quiet voice and a very sharp mind. When she was thirty-five, her husband passed away suddenly, leaving her to raise three children on her own. She’d never had a proper job, and money was tight. At one point she was barely able to make ends meet by sewing curtains for neighbours, yet she refused to depend on relatives. What struck me was how she turned things around. She took out a loan, bought a second-hand sewing machine and started making school uniforms, which she sold to local schools. There were setbacks: in the first year she hardly made a profit, and I remember her sewing until two in the morning. But she kept at it, and word of mouth did the rest. Today she runs a workshop with six employees, all of them women who, like her, needed a break. Her eldest son is at university now. What I admire most is not her success but her attitude. I never once heard her feel sorry for herself. Had she given up, nobody would have blamed her, yet she chose to carry on, against all odds. She taught me that resilience isn’t about being fearless; it’s about picking yourself up after every fall, and I try to bear that in mind whenever things get difficult.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be my aunt Gulnora, my mother’s younger sister, who lives in Namangan. She’s in her fifties now, with a quiet voice and a very sharp mind."}, {"label": "Difficultie S", "text": "When she was thirty-five, her husband passed away suddenly, leaving her to raise three children on her own. She’d never had a proper job, and money was tight. At one point she was barely able to make ends meet by sewing curtains for neighbours, yet she refused to depend on relatives."}, {"label": "How She Overcame", "text": "What struck me was how she turned things around. She took out a loan, bought"}, {"label": "Them", "text": "a second-hand sewing machine and started making school uniforms, which she sold to local schools. There were setbacks: in the first year she hardly made a profit, and I remember her sewing until two in the morning. But she kept at it, and word of mouth did the rest. Today she runs a workshop with six employees, all of them women who, like her, needed a break. Her eldest son is at university now."}, {"label": "Why I Admire Her", "text": "What I admire most is not her success but her attitude. I never once heard her feel sorry for herself. Had she given up, nobody would have blamed her, yet she chose to carry on, against all odds. She taught me that resilience isn’t about being fearless; it’s about picking yourself up after every fall, and I try to bear that in mind whenever things get difficult."}], "phrases": [["pass away", "die"], ["make ends meet", "earn just enough to live on"], ["turn things around", "change a bad situation into a good one"], ["take out a loan", "borrow money from a bank"], ["setback", "a problem that delays progress"], ["keep at it", "continue working hard"], ["word of mouth", "recommendation from person to person"], ["feel sorry for yourself", "spend time thinking about your own bad luck"], ["against all odds", "despite very difficult conditions"], ["pick yourself up", "recover after a failure"], ["bear in mind", "remember and take into account"], ["depend on", "need support from"]], "grammar": [{"pattern": "Participle clause", "use": "leaving + object + to + verb", "example": "leaving her to raise three children on her own", "try": "…, leaving her to ______."}, {"pattern": "Past perfect", "use": "She’d never + past participle", "example": "She’d never had a proper job", "try": "She’d never ______ before."}, {"pattern": "Cleft sentence with what", "use": "What struck me was how + clause", "example": "What struck me was how she turned things around", "try": "What struck me was how ______."}, {"pattern": "Relative clause with which", "use": "noun, which + subject + verb", "example": "school uniforms, which she sold to local schools", "try": "______, which she ______."}, {"pattern": "Third conditional with inversion", "use": "Had + subject + past participle, nobody would have + past participle", "example": "Had she given up, nobody would have blamed her", "try": "Had she ______, nobody would have ______."}, {"pattern": "Not … but …", "use": "not A but B", "example": "not her success but her attitude", "try": "What I admire is not ______ but ______."}]}}, "part3": {"intro": "We’ve been talking about a person you know who faced difficulties but succeeded, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who faced difficulties but succeeded", "title": "Person who faced difficulties but succeeded", "questions": [{"q": "How would you define success?", "model": {"answer": "For me, success means reaching goals that you set yourself, on your own terms, rather than ones imposed by others. Someone who becomes a wealthy executive but hates the job is hardly successful, in my view, whereas a teacher who loves her work and has financial security may well be. So I’d define it as a mix of achievement, fulfilment and a sense of purpose.", "phrases": [["on your own terms", "in the way you choose"], ["financial security", "having enough money to feel safe"], ["fulfilment", "satisfaction from doing something meaningful"], ["a sense of purpose", "a feeling that your life has meaning"], ["hardly", "almost not"]], "grammar": [{"pattern": "Relative clause with who", "use": "Someone who + verb + is hardly + adjective", "example": "Someone who becomes a wealthy executive but hates the job is hardly successful", "try": "Someone who ______ is hardly ______."}, {"pattern": "Passive reduced clause", "use": "ones imposed by others", "example": "ones imposed by others", "try": "goals ______ by others."}]}}, {"q": "How do people usually judge the success of others?", "model": {"answer": "Unfortunately, mostly by what’s visible: income, job title, the car someone drives. These are easy to compare, so they become a yardstick, particularly on social media, where people showcase only their best moments. But this can be misleading, since it ignores hidden struggles. A person who looks well off might be deeply in debt, while someone modest could be perfectly content.", "phrases": [["yardstick", "a standard for judging something"], ["showcase", "show something at its best"], ["misleading", "giving a false impression"], ["hidden struggles", "private difficulties"], ["well off", "wealthy"]], "grammar": [{"pattern": "Might for possibility", "use": "might + be + adjective", "example": "A person who looks well off might be deeply in debt", "try": "Someone who looks ______ might be ______."}, {"pattern": "Contrast with while", "use": "A, while B", "example": "while someone modest could be perfectly content", "try": "One person ______, while another ______."}]}}, {"q": "What does it take to become successful?", "model": {"answer": "A combination of persistence and good judgement. Talent helps, but I’ve seen plenty of gifted people fall by the wayside because they gave up at the first obstacle. You need the discipline to stick with it when results are slow, and the humility to learn from feedback. Luck plays a part too, which can’t be planned, though it helps to be well prepared when it comes.", "phrases": [["fall by the wayside", "fail to continue or succeed"], ["stick with it", "continue despite difficulty"], ["learn from", "improve by studying experience or advice"], ["can’t be planned", "cannot be arranged in advance"], ["well prepared", "ready for what may happen"]], "grammar": [{"pattern": "Present perfect", "use": "I’ve + seen + plenty of", "example": "I’ve seen plenty of gifted people fall by the wayside", "try": "I’ve seen plenty of people ______."}, {"pattern": "Non-defining relative clause", "use": "…, which can’t be planned", "example": "which can’t be planned", "try": "…, which can’t be ______."}]}}, {"q": "Why do some people achieve success earlier than others?", "model": {"answer": "A lot of it comes down to circumstances. Someone born into a family that can fund their education or open doors has a head start, whereas others work for years to reach the same starting line. Personality plays a part as well: some people take risks early, while others bide their time. Success arrives at different ages in different fields; a gymnast peaks at eighteen, a novelist at fifty.", "phrases": [["open doors", "create opportunities"], ["head start", "an early advantage"], ["bide your time", "wait patiently for the right moment"], ["peak", "reach the highest point of ability"], ["comes down to", "depends mainly on"]], "grammar": [{"pattern": "Past participle phrase", "use": "Someone born into + noun", "example": "Someone born into a family that can fund their education", "try": "Someone born into ______ has ______."}, {"pattern": "Ellipsis", "use": "a gymnast peaks at eighteen, a novelist at fifty", "example": "a gymnast peaks at eighteen, a novelist at fifty", "try": "A ______ peaks at ______, a ______ at ______."}]}}, {"q": "Do you think failure is necessary for success?", "model": {"answer": "Not strictly necessary, but I’d say it’s hard to succeed without it. Failure exposes weaknesses you didn’t know you had and teaches you to think on your feet. Had I passed my first driving test, I probably wouldn’t have practised parallel parking, which was my real problem. The danger lies in letting a failure knock your confidence, so the trick is to treat it as information, not a verdict.", "phrases": [["expose weaknesses", "make hidden problems visible"], ["think on your feet", "react quickly to new situations"], ["knock your confidence", "make you feel less sure"], ["strictly", "in the exact sense"], ["a verdict", "a final judgement"]], "grammar": [{"pattern": "Third conditional with inversion", "use": "Had + subject + past participle, … wouldn’t have + past participle", "example": "Had I passed my first driving test, I probably wouldn’t have practised parallel parking", "try": "Had I ______, I wouldn’t have ______."}, {"pattern": "Gerund after danger", "use": "The danger lies in + -ing", "example": "The danger lies in letting a failure knock your confidence", "try": "The danger lies in ______-ing ______."}]}}, {"q": "Are successful people always happy?", "model": {"answer": "Not necessarily. Success and happiness overlap, but they aren’t the same thing. Some high achievers work themselves into the ground, with little time for family, and end up feeling empty once they’ve reached the top. Conversely, people with modest careers can be perfectly content. The happiest successful people, I’d argue, are those who keep things in perspective and still make time for relationships.", "phrases": [["high achiever", "a person who does very well"], ["work yourself into the ground", "work until exhausted"], ["empty", "without feeling or meaning"], ["keep things in perspective", "not exaggerate how important things are"], ["overlap", "partly be the same"]], "grammar": [{"pattern": "End up + -ing", "use": "end up + -ing", "example": "end up feeling empty once they’ve reached the top", "try": "They end up ______-ing once ______."}, {"pattern": "Superlative + relative", "use": "The happiest … are those who", "example": "The happiest successful people, I’d argue, are those who keep things in perspective", "try": "The happiest people are those who ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000024', 1024, 'Topic 24', 'Technological problem', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 24, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a challenging technological problem you faced", "bullets": ["what the problem was", "when and where you faced it", "how challenging it was", "how you solved it"], "explain": "", "notes": ["What", "When & Where", "How Chall Enging", "How I Solved It"], "rounding": {"q": "Do you keep copies of your important files now?", "model": {"answer": "Absolutely. Everything is saved to the cloud automatically, and I also keep the most important documents on a small external drive, just in case.", "phrases": [], "grammar": []}}, "model": {"answer": "The first thing that comes to mind is the night my laptop suddenly crashed and refused to start. The screen went black, and no matter how many times I pressed the power button, nothing happened. It turned out that the hard drive had failed. It happened last December in my dorm room in Tashkent, two days before the deadline for my econometrics project, which was worth forty per cent of my grade. Everything, the data, the regression results and half of the report, was on that machine. To make matters worse, I’d never backed up my files. I’d put it off for months, always telling myself I’d do it at the weekend. Never had I regretted a habit so much. I couldn’t think straight and spent an hour pacing around the room. It was honestly one of the most stressful nights of my university life. In the end, I calmed down and thought it through. First I borrowed my roommate’s laptop and dug through my emails, where I found a draft I’d sent to my supervisor a week earlier, which saved about half the work. The next morning I took the laptop to a technician near the Chorsu market, who managed to recover most of the data. It cost about fifteen dollars, and I handed the project in with three hours to spare. Since then I automatically back up everything to the cloud. It was a tough lesson, but a cheap one. If it hadn’t happened then, it would probably have happened during my thesis.", "sections": [{"label": "What", "text": "The first thing that comes to mind is the night my laptop suddenly crashed and refused to start. The screen went black, and no matter how many times I pressed the power button, nothing happened. It turned out that the hard drive had failed."}, {"label": "When & Where", "text": "It happened last December in my dorm room in Tashkent, two days before the deadline for my econometrics project, which was worth forty per cent of my grade. Everything, the data, the regression results and half of the report, was on that machine."}, {"label": "How Chall Enging", "text": "To make matters worse, I’d never backed up my files. I’d put it off for months, always telling myself I’d do it at the weekend. Never had I regretted a habit so much. I couldn’t think straight and spent an hour pacing around the room. It was honestly one of the most stressful nights of my university life."}, {"label": "How I Solved It", "text": "In the end, I calmed down and thought it through. First I borrowed my roommate’s laptop and dug through my emails, where I found a draft I’d sent to my supervisor a week earlier, which saved about half the work. The next morning I took the laptop to a technician near the Chorsu market, who managed to recover most of the data. It cost about fifteen dollars, and I handed the project in with three hours to spare. Since then I automatically back up everything to the cloud."}, {"label": "Reflection", "text": "It was a tough lesson, but a cheap one. If it hadn’t happened then, it would probably have happened during my thesis."}], "phrases": [["crash", "suddenly stop working (a computer)"], ["to make matters worse", "to make a bad situation even worse"], ["back up", "save a copy of files in a second place"], ["put off", "delay"], ["can’t think straight", "unable to think clearly"], ["pace around", "walk up and down nervously"], ["think it through", "consider all aspects carefully"], ["dig through", "search through a lot of material"], ["recover", "get back lost data"], ["hand in", "submit work"]], "grammar": [{"pattern": "Past perfect", "use": "I’d never + past participle", "example": "I’d never backed up my files", "try": "I’d never ______ before."}, {"pattern": "Inversion with never", "use": "Never had + subject + past participle", "example": "Never had I regretted a habit so much", "try": "Never had I ______ so much."}, {"pattern": "Reported phrase", "use": "telling myself + clause", "example": "always telling myself I’d do it at the weekend", "try": "always telling myself I’d ______."}, {"pattern": "Relative clause with where", "use": "where + subject + past perfect", "example": "where I found a draft I’d sent to my supervisor a week earlier", "try": "…, where I found ______ I’d ______."}, {"pattern": "Non-defining relative clause", "use": "…, who managed to + verb", "example": "who managed to recover most of the data", "try": "…, who managed to ______."}, {"pattern": "Third conditional (mixed)", "use": "If + past perfect, would probably have + past participle", "example": "If it hadn’t happened then, it would probably have happened during my thesis", "try": "If it hadn’t ______, it would probably have ______."}]}}, "part3": {"intro": "We’ve been talking about a challenging technological problem you faced, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Technological problem", "title": "Technological problem", "questions": [{"q": "What technological problems do people commonly experience in daily life?", "model": {"answer": "Slow Wi-Fi tops the list, followed by phones that run out of battery at the worst moment. Forgotten passwords are another everyday nuisance, and so are updates that arrive just as you’re about to start a meeting. More seriously, people fall victim to online scams or lose photos because they haven’t made a backup. Most of these glitches are minor, but they can be a real headache.", "phrases": [["top the list", "be the most common"], ["run out of battery", "have no power left"], ["fall victim to", "be harmed by"], ["glitch", "a small fault"], ["a real headache", "a source of annoying problems"]], "grammar": [{"pattern": "Participle clause", "use": "followed by + noun", "example": "followed by phones that run out of battery at the worst moment", "try": "______, followed by ______."}, {"pattern": "Just as", "use": "just as + subject + are about to", "example": "just as you’re about to start a meeting", "try": "just as you’re about to ______."}]}}, {"q": "Do you think people rely too much on technology?", "model": {"answer": "In many ways, yes. We depend on our phones for directions, memory and even basic arithmetic, and when the battery dies we feel lost. That said, relying on tools is nothing new; nobody blames us for using a calculator. The real concern is that constant convenience weakens skills like concentration and navigation, which you only notice when technology lets you down.", "phrases": [["depend on", "need"], ["feel lost", "not know what to do"], ["weaken", "make less strong"], ["nothing new", "something that has always happened"], ["let someone down", "fail to work when needed"]], "grammar": [{"pattern": "Concession with that said", "use": "That said, + clause", "example": "That said, relying on tools is nothing new", "try": "That said, ______."}, {"pattern": "Cleft sentence", "use": "The real concern is that + clause", "example": "The real concern is that constant convenience weakens skills like concentration and navigation", "try": "The real concern is that ______."}]}}, {"q": "Who should teach older people how to use new technology?", "model": {"answer": "Ideally, family members, because older people learn best from someone they trust and who will be patient. A grandchild can sit beside a grandmother and show her how to make a video call, at her own pace. Where that isn’t possible, community centres could run hands-on classes. Schools might even organise volunteer days where students pass on their skills, which would benefit both sides.", "phrases": [["at your own pace", "as quickly or slowly as you like"], ["hands-on", "practical, learning by doing"], ["pass on", "give knowledge to someone else"], ["benefit both sides", "be good for everyone involved"], ["ideally", "in the best possible situation"]], "grammar": [{"pattern": "Relative clause with who", "use": "someone they trust and who will be patient", "example": "someone they trust and who will be patient", "try": "someone ______ and who ______."}, {"pattern": "Where + clause", "use": "Where that isn’t possible, + clause", "example": "Where that isn’t possible, community centres could run hands-on classes", "try": "Where that isn’t possible, ______."}]}}, {"q": "How has artificial intelligence changed the way people work or study?", "model": {"answer": "Quite dramatically. Students use AI to brainstorm ideas, check grammar and summarise long articles, which saves hours. In offices, routine tasks such as writing reports or answering customer questions are being automated, so employees can focus on more creative work. Although it’s a powerful assistant, its output depends on the user, and it still needs to be double-checked, because it can sound confident while being wrong.", "phrases": [["brainstorm", "produce ideas quickly"], ["routine task", "a regular, repetitive job"], ["automate", "make a machine do it automatically"], ["double-check", "check again to be sure"], ["dramatically", "in a very big and sudden way"]], "grammar": [{"pattern": "Passive continuous", "use": "are being + past participle", "example": "are being automated", "try": "Routine tasks are being ______."}, {"pattern": "Concession with although", "use": "Although + clause, + clause", "example": "Although it’s a powerful assistant, its output depends on the user", "try": "Although it’s ______, ______."}]}}, {"q": "What are the possible dangers of artificial intelligence?", "model": {"answer": "A few come to mind. The first is misinformation: AI can produce convincing but false text, images or videos, making it hard to tell what’s real. Then there’s privacy, as these systems are trained on huge amounts of data. Finally, if people lean on AI for every decision, they may stop thinking critically. Used responsibly it’s useful, but it needs clear rules and human oversight.", "phrases": [["be trained on", "learn from large amounts of data"], ["lean on", "depend on"], ["clear rules", "definite regulations"], ["human oversight", "supervision by people"], ["misinformation", "false information"]], "grammar": [{"pattern": "Participle clause", "use": "making it hard to + verb", "example": "making it hard to tell what’s real", "try": "…, making it hard to ______."}, {"pattern": "Past participle clause", "use": "Used + adverb, it + verb", "example": "Used responsibly it’s useful", "try": "Used ______, it ______."}]}}, {"q": "Do you think AI will replace human workers in the future?", "model": {"answer": "Some jobs, yes, but not all. Repetitive roles such as data entry are most at risk, and companies will be tempted to cut costs. Jobs that require empathy, creativity or physical skill, like nursing or plumbing, are much harder to replace. What I expect is that work will shift rather than vanish: new roles will appear, and workers who adapt will be fine, whereas those who don’t may struggle.", "phrases": [["most at risk", "in the greatest danger of being lost"], ["cut costs", "reduce spending"], ["shift", "change in position or type"], ["adapt", "change to suit new conditions"], ["data entry", "typing information into a computer system"]], "grammar": [{"pattern": "Cleft sentence with what", "use": "What I expect is that + clause", "example": "What I expect is that work will shift rather than vanish", "try": "What I expect is that ______."}, {"pattern": "Contrast with whereas", "use": "A, whereas B", "example": "whereas those who don’t may struggle", "try": "______, whereas those who don’t ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000025', 1025, 'Topic 25', 'Person who helped you solve a problem', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 25, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person who did something to help you solve a problem", "bullets": ["what the problem was", "when and where you faced it", "how this person solved it", "how you felt about the experience"], "explain": "", "notes": ["The Problem", "When And Where", "How He Solved It", "How I Felt"], "rounding": {"q": "Do you still keep in touch with Mr Rustam?", "model": {"answer": "Yes, we exchange a few messages every now and then. Last month I wrote to tell him I’d been accepted onto a master’s course, and he replied within an hour saying he’d never doubted I would manage.", "phrases": [], "grammar": []}}, "model": {"answer": "The first person who comes to mind is Mr Rustam, my statistics lecturer at university. Two years ago he bailed me out of a situation that could easily have wrecked my semester. I’d been working on a group project, but a week before the deadline my teammates left me in the lurch one by one, which meant I was alone with a data set I barely understood and was completely out of my depth. It was a December night in the university library, and the heating had broken down, so I was sitting there in my coat, staring at a spreadsheet and at my wits’ end. Mr Rustam happened to be walking past on his way home. Instead of simply giving me the answer, he sat down and asked, “What are you actually trying to find out?” That one question cleared things up more than three hours of panic. He then walked me through the analysis and stayed for nearly two hours, even though he had a train to catch. What struck me was that he never made me feel stupid. A few days later he even put in a good word for me, which allowed me to present the results myself. Looking back, I felt relieved, but also a little ashamed that I hadn’t asked sooner. Had I swallowed my pride earlier, I wouldn’t have spent a whole week panicking. I received a high mark in the end, though what I really took away from it was that a great teacher will go the extra mile and point you in the right direction rather than do the work for you.", "sections": [{"label": "The Problem", "text": "The first person who comes to mind is Mr Rustam, my statistics lecturer at university. Two years ago he bailed me out of a situation that could easily have wrecked my semester. I’d been working on a group project, but a week before the deadline my teammates left me in the lurch one by one, which meant I was alone with a data set I barely understood and was completely out of my depth."}, {"label": "When And Where", "text": "It was a December night in the university library, and the heating had broken down, so I was sitting there in my coat, staring at a spreadsheet and at my wits’ end."}, {"label": "How He Solved It", "text": "Mr Rustam happened to be walking past on his way home. Instead of simply giving me the answer, he sat down and asked, “What are you actually trying to find out?” That one question cleared things up more than three hours of panic. He then walked me through the analysis and stayed for nearly two hours, even though he had a train to catch. What struck me was that he never made me feel stupid. A few days later he even put in a good word for me, which allowed me to present the results myself."}, {"label": "How I Felt", "text": "Looking back, I felt relieved, but also a little ashamed that I hadn’t asked sooner. Had I swallowed my pride earlier, I wouldn’t have spent a whole week panicking. I received a high mark in the end, though what I really took away from it was that a great teacher will go the extra mile and point you in the right direction rather than do the work for you."}], "phrases": [["bail (someone) out", "rescue someone from a difficult situation"], ["leave (someone) in the lurch", "abandon someone when they need help"], ["out of my depth", "in a situation too difficult for my knowledge or skill"], ["at my wits’ end", "so worried and tired that I could not think of what to do"], ["clear things up", "make something easy to understand"], ["walk (someone) through", "explain or show something slowly, step by step"], ["put in a good word for (someone)", "speak well of someone to help them"], ["swallow your pride", "admit you need help even though it feels embarrassing"], ["take away (from)", "learn or remember as the main lesson"], ["go the extra mile", "make more effort than is expected"], ["point (someone) in the right direction", "give someone useful guidance"]], "grammar": [{"pattern": "Past perfect continuous", "use": "had/’d been + -ing: an activity in progress before a past moment", "example": "I’d been working on a group project", "try": "I’d been ______ for hours when ______."}, {"pattern": "Participle clause", "use": "-ing phrase describing what the subject was doing at the same time", "example": "sitting there in my coat, staring at a spreadsheet", "try": "I was sitting in the café, ______ ing ______."}, {"pattern": "Cleft sentence with What", "use": "What + subject + verb + was (that) …: puts focus on one idea", "example": "What struck me was that he never made me feel stupid", "try": "What impressed me most was that ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, subject + would have + past participle", "example": "Had I swallowed my pride earlier, I wouldn’t have spent a whole week panicking", "try": "Had I ______ earlier, I wouldn’t have ______."}, {"pattern": "Non-defining which-clause", "use": "…, which + verb: comments on the whole previous idea", "example": "which meant I was alone with a data set I barely understood", "try": "…, which meant ______."}]}}, "part3": {"intro": "We’ve been talking about a person who did something to help you solve a problem, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who helped you solve a problem", "title": "Person who helped you solve a problem", "questions": [{"q": "Do you think people are born intelligent, or do they become intelligent through learning?", "model": {"answer": "It’s a bit of both, but I lean towards learning. Some children are naturally quick at picking things up, yet without encouragement and a stimulating environment that ability goes to waste. Meanwhile, a child with an average starting point can make remarkable progress when teachers believe in them. Genes might give you a head start, but it’s effort that determines how far you go.", "phrases": [["naturally quick", "able to learn easily without much effort"], ["stimulating environment", "surroundings that make you think and want to learn"], ["go to waste", "be lost or never used"], ["make remarkable progress", "improve a great deal"], ["head start", "an early advantage"]], "grammar": [{"pattern": "Hedging with might", "use": "might + base verb: a careful, less certain claim", "example": "Genes might give you a head start", "try": "Talent might ______, but ______."}, {"pattern": "Cleft with it", "use": "It is/’s + focus + that/noun clause: emphasises one idea", "example": "it’s effort that determines how far you go", "try": "It’s ______ that decides whether ______."}]}}, {"q": "Why are some children more successful at school than others?", "model": {"answer": "Often it comes down to what happens at home rather than raw ability. A child whose parents read with them and ask about their day tends to develop good study habits early on, and school feels within reach. By contrast, a bright pupil who is constantly under pressure, or simply tired and hungry, can easily fall behind without anyone noticing why.", "phrases": [["come down to", "be mainly decided by"], ["develop good study habits", "build useful routines for learning"], ["within reach", "possible to achieve"], ["under pressure", "feeling stress because of high demands"], ["fall behind", "progress more slowly than others"]], "grammar": [{"pattern": "Relative clause with whose", "use": "noun + whose + noun + verb: shows possession", "example": "A child whose parents read with them", "try": "A student whose ______ is more likely to ______."}, {"pattern": "Rather than", "use": "X rather than Y: contrasts two factors", "example": "what happens at home rather than raw ability", "try": "Success depends on ______ rather than ______."}]}}, {"q": "Is it better to ask for help or to solve problems on your own?", "model": {"answer": "It depends on the problem. With something small, struggling through it yourself is the best way to learn, because you remember the solution. But if you’ve been going round in circles for hours, asking someone is efficient. I used to hate admitting I was stuck, yet a fresh pair of eyes can figure out in two minutes what I’d missed for two hours, so now I swallow my pride.", "phrases": [["struggle through", "manage something with difficulty"], ["go round in circles", "keep trying without making progress"], ["a fresh pair of eyes", "a new person looking at a problem"], ["figure out", "find the answer by thinking"], ["swallow my pride", "admit I need help"]], "grammar": [{"pattern": "Used to + verb", "use": "used to + base verb: a past habit or state that has changed", "example": "I used to hate admitting I was stuck", "try": "I used to ______, but now ______."}, {"pattern": "Present perfect continuous", "use": "have/’ve been + -ing: an action continuing up to now", "example": "if you’ve been going round in circles for hours", "try": "If you’ve been ______ for hours, ______."}]}}, {"q": "Does society need people with different kinds of intelligence?", "model": {"answer": "Absolutely, and probably more than we realise. A hospital can’t run on brilliant surgeons alone; it also needs nurses with emotional intelligence, technicians with practical know-how and managers who keep things running smoothly. Were everyone good at the same thing, society would be out of balance. The trouble is that schools tend to reward academic ability, so other talents are overlooked.", "phrases": [["emotional intelligence", "the ability to understand and handle feelings"], ["practical know-how", "hands-on skill and experience"], ["keep things running smoothly", "make sure everything works without problems"], ["out of balance", "not properly shared or equal"], ["overlook", "fail to notice or value"]], "grammar": [{"pattern": "Inverted second conditional", "use": "Were + subject + …, subject + would + base verb", "example": "Were everyone good at the same thing, society would be out of balance", "try": "Were everyone ______, the world would ______."}, {"pattern": "Passive", "use": "be + past participle: the doer is less important", "example": "other talents are overlooked", "try": "Creative skills are often ______."}]}}, {"q": "Are intelligent people always happier than others?", "model": {"answer": "Not necessarily. If anything, the opposite can be true, because people who think deeply tend to overthink everything and set very high standards for themselves. Happiness seems to depend more on relationships and a sense of purpose than on IQ. I know a brilliant engineer who is constantly stressed, while his much less academic brother seems perfectly content with his lot.", "phrases": [["overthink", "think about something too much"], ["set high standards", "expect a lot from yourself or others"], ["sense of purpose", "a feeling that your life has meaning"], ["content with his lot", "satisfied with the life he has"], ["if anything", "used for a point that is perhaps even truer"]], "grammar": [{"pattern": "Comparative structure", "use": "depend more on A than on B", "example": "depend more on relationships and a sense of purpose than on IQ", "try": "Success depends more on ______ than on ______."}, {"pattern": "Contrast with while", "use": "while + clause: contrasts two people or situations", "example": "while his much less academic brother seems perfectly content", "try": "My sister is ______, while my brother is ______."}]}}, {"q": "How can we judge a person’s intelligence?", "model": {"answer": "That’s hard to do with a single test. Exam results measure memory and speed under pressure, but a good indication is how someone handles an unfamiliar problem: do they ask sharp questions, learn from their mistakes and explain things clearly? Personally, I’d trust a long conversation over a certificate, because it shows how a person actually thinks rather than what they happen to have memorised.", "phrases": [["under pressure", "in a stressful situation"], ["handle an unfamiliar problem", "deal with something new"], ["ask sharp questions", "ask clever, precise questions"], ["learn from your mistakes", "improve after making errors"], ["a good indication", "a clear sign"]], "grammar": [{"pattern": "Noun clause with how", "use": "how + subject + verb: reported idea as a noun", "example": "how someone handles an unfamiliar problem", "try": "What matters is how people ______."}, {"pattern": "Would for preference", "use": "I’d + verb + X over Y", "example": "I’d trust a long conversation over a certificate", "try": "I’d choose ______ over ______."}]}}, {"q": "Do you think there are things that very intelligent people find difficult?", "model": {"answer": "Quite a few, actually. Highly intelligent people sometimes struggle to relate to others, because they take for granted things that are far from obvious to everyone else. A brilliant professor may talk over his students’ heads because he’s forgotten what it’s like not to know. Having rarely failed, they can also find it hard to cope with failure, and some become perfectionists who never finish anything.", "phrases": [["struggle to relate to", "find it hard to understand and connect with"], ["take for granted", "assume something is obvious or always true"], ["cope with failure", "deal with not succeeding"], ["talk over someone’s head", "explain in a way that is too difficult to follow"], ["perfectionist", "someone who wants everything to be perfect"]], "grammar": [{"pattern": "Participle clause (perfect)", "use": "Having + past participle, clause: a reason from earlier", "example": "Having rarely failed, they can also find it hard", "try": "Having never ______, she finds it ______."}, {"pattern": "Defining relative clause", "use": "noun + who + verb", "example": "perfectionists who never finish anything", "try": "People who ______ often ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000026', 1026, 'Topic 26', 'Changing an opinion', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 26, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a time when you changed your opinion", "bullets": ["what the original opinion was", "why you changed it", "when it was", "how you felt about it"], "explain": "", "notes": ["The Old Opinion", "Why I Changed It", "When And Where", "How I Felt"], "rounding": {"q": "Do you listen to classical music at home as well?", "model": {"answer": "Sometimes, especially when I’m studying, because it helps me concentrate better than songs with lyrics. I’ve also started exploring film soundtracks, which feel like a gentle way into the genre.", "phrases": [], "grammar": []}}, "model": {"answer": "One occasion I’ll never forget is when I did a complete U-turn on classical music. Until I was about nineteen, I was convinced it was stuffy and slow, something only elderly people pretended to enjoy. I’d written it off without ever listening to a whole piece, mostly because at school we’d been made to sit through recordings that nobody understood. What changed my mind was my friend Dilnoza, who talked me into going to a concert with her. I only agreed because she’d already bought the tickets and I didn’t want to let her down. It was a cold evening in February, about three years ago, at the Navoi Theatre in Tashkent. I walked in with low expectations, fully prepared to check my phone every five minutes. Then the orchestra began Tchaikovsky’s Fifth Symphony, and within minutes I was hooked. Never had I realised how physical live music could be; I could feel the double basses in my chest. My phone stayed in my pocket for the rest of the night. Afterwards I felt slightly embarrassed, to be honest, because I was eating my words as we walked out. Dilnoza just grinned. If she hadn’t dragged me along, I’d probably still be dismissing that kind of music today. Since then I’ve been going to a concert every couple of months. It taught me to keep an open mind, because it’s very easy to judge something you’ve never really experienced.", "sections": [{"label": "The Old Opinion", "text": "One occasion I’ll never forget is when I did a complete U-turn on classical music. Until I was about nineteen, I was convinced it was stuffy and slow, something only elderly people pretended to enjoy. I’d written it off without ever listening to a whole piece, mostly because at school we’d been made to sit through recordings that nobody understood."}, {"label": "Why I Changed It", "text": "What changed my mind was my friend Dilnoza, who talked me into going to a concert with her. I only agreed because she’d already bought the tickets and I didn’t want to let her down."}, {"label": "When And Where", "text": "It was a cold evening in February, about three years ago, at the Navoi Theatre in Tashkent. I walked in with low expectations, fully prepared to check my phone every five minutes. Then the orchestra began Tchaikovsky’s Fifth Symphony, and within minutes I was hooked. Never had I realised how physical live music could be; I could feel the double basses in my chest. My phone stayed in my pocket for the rest of the night."}, {"label": "How I Felt", "text": "Afterwards I felt slightly embarrassed, to be honest, because I was eating my words as we walked out. Dilnoza just grinned. If she hadn’t dragged me along, I’d probably still be dismissing that kind of music today. Since then I’ve been going to a concert every couple of months. It taught me to keep an open mind, because it’s very easy to judge something you’ve never really experienced."}], "phrases": [["do a U-turn on (something)", "completely change your opinion or decision"], ["write (something) off", "decide something is not worth your attention"], ["sit through", "stay until the end of something boring"], ["talk (someone) into (doing)", "persuade someone to do something"], ["let (someone) down", "disappoint someone who is relying on you"], ["with low expectations", "not expecting much"], ["hooked", "so interested that you cannot stop"], ["eat your words", "admit you were wrong about something you said"], ["drag (someone) along", "make someone come with you when they don’t really want to"], ["dismiss", "refuse to take something seriously"], ["keep an open mind", "stay willing to consider new ideas"]], "grammar": [{"pattern": "Cleft sentence with What", "use": "What + subject + verb + was + noun: highlights the key fact", "example": "What changed my mind was my friend Dilnoza", "try": "What surprised me most was ______."}, {"pattern": "Past perfect", "use": "had/’d + past participle: earlier than the main past events", "example": "she’d already bought the tickets", "try": "I only went because my friend had already ______."}, {"pattern": "Negative inversion", "use": "Never + had + subject + past participle: strong emphasis", "example": "Never had I realised how physical live music could be", "try": "Never had I ______ so ______."}, {"pattern": "Mixed conditional", "use": "If + past perfect, would + base verb (past cause, present result)", "example": "If she hadn’t dragged me along, I’d probably still be dismissing that kind of music today", "try": "If I hadn’t ______, I would still ______ today."}, {"pattern": "Participle clause of preparation", "use": "fully/ready + adjective + to-infinitive", "example": "fully prepared to check my phone every five minutes", "try": "I went in, fully prepared to ______."}, {"pattern": "Present perfect continuous", "use": "have + been + -ing: a habit that started in the past and continues", "example": "I’ve been going to a concert every couple of months", "try": "Since then I’ve been ______ regularly."}]}}, "part3": {"intro": "We’ve been talking about a time when you changed your opinion, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Changing an opinion", "title": "Changing an opinion", "questions": [{"q": "At what age do children begin to form their own opinions?", "model": {"answer": "Earlier than most parents expect. By the age of three or four, children insist on choosing their own clothes or refusing certain foods, which is a basic form of opinion. Genuinely reasoned views, though, take shape much later, usually in the early teens, once children can weigh up different arguments and are no longer simply echoing what they hear at home.", "phrases": [["insist on", "firmly demand to do something"], ["take shape", "gradually develop into a clear form"], ["weigh up", "consider the good and bad sides"], ["echo", "repeat what someone else says"], ["reasoned view", "an opinion supported by logical thinking"]], "grammar": [{"pattern": "Non-defining which-clause", "use": "…, which + verb: comments on the previous idea", "example": "which is a basic form of opinion", "try": "…, which is a sign of ______."}, {"pattern": "Once-clause", "use": "once + subject + verb: from the moment something happens", "example": "once children can weigh up different arguments", "try": "Once teenagers can ______, they ______."}]}}, {"q": "Who influences children’s opinions more, their parents or their teachers?", "model": {"answer": "Parents, at least in the early years, since children absorb their values at home long before they reach a classroom. Teachers become more influential as pupils grow older, particularly when they’re charismatic or genuinely passionate about their subject. That said, the two aren’t in competition: the strongest effect comes when both pull in the same direction and children receive consistent messages.", "phrases": [["absorb", "take in naturally without trying"], ["charismatic", "having a strong personal charm that attracts people"], ["in competition", "trying to win against each other"], ["pull in the same direction", "work towards the same goal"], ["consistent message", "advice that stays the same everywhere"]], "grammar": [{"pattern": "Concession with That said", "use": "That said, + clause: adds a balancing point", "example": "That said, the two aren’t in competition", "try": "That said, ______."}, {"pattern": "Comparative + when", "use": "more + adjective + as + clause", "example": "Teachers become more influential as pupils grow older", "try": "Friends become more important as ______."}]}}, {"q": "Do you think children always share their parents’ opinions?", "model": {"answer": "Not at all, and that’s quite healthy. Children who grow up in the same house often end up with very different views, especially in their teens, when they push back against their parents on everything from music to career choices. Sometimes it’s just a passing phase, but occasionally the gap widens into a generation gap that takes years of patience to bridge.", "phrases": [["grow up", "develop from a child into an adult"], ["end up", "finally be in a situation, often unplanned"], ["push back against", "resist or argue against"], ["phase", "a short period of behaviour that children grow out of"], ["generation gap", "difference in attitudes between older and younger people"]], "grammar": [{"pattern": "Defining relative clause", "use": "noun + who + verb", "example": "Children who grow up in the same house", "try": "Students who ______ often ______."}, {"pattern": "Relative clause with that", "use": "noun + that + verb: describes a result", "example": "a generation gap that takes years of patience to bridge", "try": "…a misunderstanding that ______."}]}}, {"q": "What do young people tend to have strong opinions about?", "model": {"answer": "Anything bound up with their identity: music, fashion, football teams and, increasingly, climate change. What’s striking is how fiercely loyal they can be; criticise a favourite band and they take it as a personal insult. Political opinions usually come later, once they start paying taxes. Young people also like to weigh in on social media debates, sometimes before they’ve thought things through.", "phrases": [["bound up with", "closely connected with"], ["fiercely loyal", "extremely faithful and protective"], ["a personal insult", "something said that feels like an attack on you"], ["weigh in on", "give your opinion in a discussion"], ["think things through", "consider all the consequences carefully"]], "grammar": [{"pattern": "Cleft with What", "use": "What’s + adjective + is how + clause", "example": "What’s striking is how fiercely loyal they can be", "try": "What’s interesting is how ______."}, {"pattern": "Present perfect after before", "use": "before + subject + have/has + past participle", "example": "before they’ve thought things through", "try": "…before they’ve ______."}]}}, {"q": "How can teachers help children develop their own ideas?", "model": {"answer": "By asking more questions than they answer. If a teacher asks, “Why do you think the author ended it that way?”, pupils have to think for themselves instead of memorising one correct answer. Debates and project work also encourage independent thinking, provided students feel safe enough to disagree without being laughed at. The more room they’re given, the more self-assured they become.", "phrases": [["think for yourself", "form your own opinions"], ["encourage independent thinking", "help people reason without depending on others"], ["provided (that)", "only if"], ["self-assured", "confident in yourself"], ["room", "freedom or space to do something"]], "grammar": [{"pattern": "The more… the more", "use": "The more + subject + verb, the more + clause", "example": "The more room they’re given, the more self-assured they become", "try": "The more ______, the more ______."}, {"pattern": "Provided + participle clause", "use": "provided + subject + verb: a condition", "example": "provided students feel safe enough to disagree", "try": "…provided people ______."}]}}, {"q": "What makes people change their opinions?", "model": {"answer": "Usually personal experience rather than a clever argument. You can debate with someone for hours without success, but one trip abroad or one honest conversation can shift their perspective overnight. New evidence helps too, if people are open to it. What rarely works is telling them they’re wrong, because that makes them dig their heels in and you’ll never win them over.", "phrases": [["shift (someone’s) perspective", "change how someone sees something"], ["open to (something)", "willing to consider something"], ["dig your heels in", "refuse to change your position"], ["win (someone) over", "persuade someone to agree with you"], ["personal experience", "something that happened to you directly"]], "grammar": [{"pattern": "Cleft with What", "use": "What + verb + is + -ing: focuses on a key action", "example": "What rarely works is telling them they’re wrong", "try": "What rarely helps is ______ing."}, {"pattern": "Causative make", "use": "make + object + base verb", "example": "that makes them dig their heels in", "try": "That makes people ______."}]}}, {"q": "Do you think it is a sign of weakness to change your mind?", "model": {"answer": "Quite the opposite; I’d say it takes strength. Sticking to a view you know is wrong just to save face is far worse. The people I admire most are those who can say, “I looked into it and I was mistaken.” In politics or business, leaders who never back down are often seen as stubborn, while flexibility suggests confidence and intellectual honesty.", "phrases": [["stick to", "refuse to change"], ["save face", "avoid looking foolish in front of others"], ["back down", "give up a position in an argument"], ["intellectual honesty", "willingness to admit the truth even when it is uncomfortable"], ["take strength", "needs courage"]], "grammar": [{"pattern": "Reduced relative clause", "use": "noun + (that) + subject + verb", "example": "a view you know is wrong", "try": "A habit you know is ______."}, {"pattern": "Superlative + relative", "use": "the + noun + I + verb + most", "example": "The people I admire most are those who", "try": "The things I value most are ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000027', 1027, 'Topic 27', 'Message or email with no reply', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 27, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a time when you sent a message or an email to someone but received no reply for a long time", "bullets": ["who you sent it to", "what it was about", "whether you finally received the reply", "how you felt about the experience"], "explain": "", "notes": ["Who", "What", "The Reply", "How I Felt"], "rounding": {"q": "Do you usually reply to messages straight away?", "model": {"answer": "Not always, to be honest. I tend to read things quickly and then forget to answer, so I try to set aside a few minutes each evening to catch up. I’d hate anyone to feel the way I did that spring.", "phrases": [], "grammar": []}}, "model": {"answer": "The first thing that comes to mind is an email I wrote to a professor in England last spring. Her name was Dr Hughes, and I’d found her research on behavioural economics while I was working on my dissertation. Never having met her, I was nervous about writing out of the blue, but I decided it was worth a shot. In the email, I introduced myself politely and asked whether she could recommend a couple of articles and answer a few questions about her method. I spent ages drafting it, rewriting the first line at least five times so that it would strike the right tone. Then I pressed send and waited. A week went by, then two. Every morning I checked my inbox before I’d even brushed my teeth. Eventually, after nearly three weeks, I took the plunge and sent a short follow-up. To my surprise, she got back to me within an hour. It turned out that my first message had landed in her spam folder, and she’d only found it while clearing out her mailbox. She apologised warmly and sent a long reply, along with two articles I hadn’t come across. Looking back, I was far more anxious than the situation deserved. I’d jumped to the conclusion that she was ignoring me, when in fact she had never even seen the message. It taught me not to take silence personally. Now, if I don’t hear back after a week, I assume the best and send a polite reminder, and more often than not, that’s all it takes.", "sections": [{"label": "Who", "text": "The first thing that comes to mind is an email I wrote to a professor in England last spring. Her name was Dr Hughes, and I’d found her research on behavioural economics while I was working on my dissertation. Never having met her, I was nervous about writing out of the blue, but I decided it was worth a shot."}, {"label": "What", "text": "In the email, I introduced myself politely and asked whether she could recommend a couple of articles and answer a few questions about her method. I spent ages drafting it, rewriting the first line at least five times so that it would strike the right tone. Then I pressed send and waited. A week went by, then two. Every morning I checked my inbox before I’d even brushed my teeth."}, {"label": "The Reply", "text": "Eventually, after nearly three weeks, I took the plunge and sent a short follow-up. To my surprise, she got back to me within an hour. It turned out that my first message had landed in her spam folder, and she’d only found it while clearing out her mailbox. She apologised warmly and sent a long reply, along with two articles I hadn’t come across."}, {"label": "How I Felt", "text": "Looking back, I was far more anxious than the situation deserved. I’d jumped to the conclusion that she was ignoring me, when in fact she had never even seen the message. It taught me not to take silence personally. Now, if I don’t hear back after a week, I assume the best and send a polite reminder, and more often than not, that’s all it takes."}], "phrases": [["out of the blue", "without warning or any earlier contact"], ["worth a shot", "worth trying even if it might fail"], ["spend ages (doing)", "spend a very long time"], ["strike the right tone", "find a suitable style, polite but natural"], ["take the plunge", "finally decide to do something risky or uncomfortable"], ["follow-up", "a later message that checks on an earlier one"], ["get back to (someone)", "reply to someone"], ["come across", "find or meet by chance"], ["jump to the conclusion", "decide something too quickly without enough evidence"], ["take (something) personally", "feel it is directed at you"], ["assume the best", "expect a good reason, not a bad one"]], "grammar": [{"pattern": "Perfect participle clause", "use": "Never having + past participle, clause: a reason from earlier", "example": "Never having met her, I was nervous about writing out of the blue", "try": "Never having ______, I felt ______."}, {"pattern": "Past perfect", "use": "had/’d + past participle: an earlier past action", "example": "I’d found her research on behavioural economics", "try": "I’d found her work while I ______."}, {"pattern": "It turned out that", "use": "It turned out that + clause: reveals a surprising explanation", "example": "It turned out that my first message had landed in her spam folder", "try": "It turned out that ______."}, {"pattern": "Comparative with than", "use": "far more + adjective + than + noun clause", "example": "I was far more anxious than the situation deserved", "try": "I was far more ______ than ______."}, {"pattern": "Zero conditional", "use": "if + present simple, present simple: a habit", "example": "if I don’t hear back after a week, I assume the best", "try": "If ______, I usually ______."}]}}, "part3": {"intro": "We’ve been talking about a time when you sent a message or an email to someone but received no reply for a long time, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Message or email with no reply", "title": "Message or email with no reply", "questions": [{"q": "Why do some people still write letters nowadays?", "model": {"answer": "Because a letter feels personal in a way that a message never can. Someone has chosen the paper, thought about every sentence and taken the time to post it, and that effort is part of the message. Others simply enjoy the slower pace, or like the idea that a letter can become a keepsake for decades. For them, writing by hand is also a break from screens.", "phrases": [["take the time", "make the effort to do something properly"], ["part of the message", "an important element of what is being said"], ["keepsake", "a small item kept to remember someone"], ["a break from screens", "time away from phones and computers"], ["slower pace", "less hurried way of doing things"]], "grammar": [{"pattern": "Relative clause with in a way that", "use": "in a way that + clause", "example": "in a way that a message never can", "try": "It feels special in a way that ______."}, {"pattern": "Present perfect", "use": "has/have + past participle: a completed action with a present result", "example": "Someone has chosen the paper", "try": "Someone has ______ every detail."}]}}, {"q": "Do people in your country prefer to write letters or emails?", "model": {"answer": "Emails, by a wide margin, at least for official matters, although messaging apps like Telegram are even more common in everyday life. Letters have almost died out among young people, apart from greeting cards on special occasions. My grandmother’s generation, however, used to write long letters to relatives in other cities, and some people still hold on to that habit.", "phrases": [["by a wide margin", "by a large difference"], ["die out", "gradually disappear"], ["apart from", "except for"], ["greeting card", "a card with a message, sent for a birthday or holiday"], ["hold on to", "keep (a habit or belief)"]], "grammar": [{"pattern": "Used to", "use": "used to + base verb: a past habit", "example": "used to write long letters to relatives", "try": "My grandfather used to ______."}, {"pattern": "Concession with although", "use": "although + clause: a contrast", "example": "although messaging apps like Telegram are even more common in everyday life", "try": "Although ______, most people ______."}]}}, {"q": "On what occasions might a handwritten letter be better than a message?", "model": {"answer": "Whenever the occasion is emotional or deserves to be marked. A thank-you note after a wedding, a letter of condolence or an apology to a close friend all carry more weight than a text. Were I to message a friend who’d lost a parent, it would feel rushed, whereas a letter shows I’d put real thought into it and that my sympathy is heartfelt.", "phrases": [["deserve to be marked", "be important enough to celebrate or recognise"], ["carry more weight", "be taken more seriously"], ["put thought into", "plan carefully and sincerely"], ["heartfelt", "sincere and deeply felt"], ["condolence", "an expression of sympathy after a death"]], "grammar": [{"pattern": "Inverted conditional", "use": "Were + subject + to + verb, subject + would …", "example": "Were I to message a friend who’d lost a parent, it would feel rushed", "try": "Were I to ______, it would ______."}, {"pattern": "Contrast with whereas", "use": "clause, whereas + clause", "example": "whereas a letter shows I’d put real thought into it", "try": "A call is quick, whereas a letter ______."}]}}, {"q": "How has instant messaging changed the way people communicate?", "model": {"answer": "Dramatically. We now keep up with people in real time, so a conversation is spread across the whole day instead of one phone call. Messages have also become shorter and more informal, full of emojis and abbreviations. The upside is that distance no longer matters much; I chat with my cousin in Korea every day. The downside is that we’re always reachable, which can feel intrusive.", "phrases": [["keep up with", "stay in regular contact with"], ["in real time", "as things happen, without delay"], ["full of", "containing a lot of"], ["no longer matter", "stop being important"], ["always reachable", "available to be contacted at any moment"]], "grammar": [{"pattern": "Passive", "use": "be + past participle", "example": "a conversation is spread across the whole day", "try": "Work is ______ across ______."}, {"pattern": "No longer", "use": "no longer + verb", "example": "distance no longer matters much", "try": "______ no longer matters."}]}}, {"q": "Do you think people expect an immediate reply nowadays?", "model": {"answer": "Increasingly, yes, and that’s a bit unfair. Because people can see when you were last online, or whether a message has been read, a delayed answer is easily read as rudeness. Between friends that’s manageable, but at work it puts pressure on employees to reply in the evening. In my experience, the ones who answer fastest aren’t necessarily the ones who care most; often they just can’t resist the notification.", "phrases": [["read as", "interpreted as"], ["put pressure on", "make someone feel they must do something"], ["care most", "be most concerned"], ["can’t resist", "find it very hard not to"], ["a delayed answer", "a reply that comes late"]], "grammar": [{"pattern": "Because-clause", "use": "Because + subject + verb, main clause", "example": "Because people can see when you were last online", "try": "Because ______, people ______."}, {"pattern": "Passive with easily", "use": "be + easily + past participle", "example": "a delayed answer is easily read as rudeness", "try": "Silence is easily ______."}]}}, {"q": "What problems can arise when people communicate mainly by text?", "model": {"answer": "Misunderstandings, mainly. Without tone of voice or facial expression, a short message can come across as cold or even angry when it was meant neutrally. Sensitive issues are the worst; arguments by text tend to escalate quickly. Another problem is that people lose the habit of talking face to face, so some young people find phone calls nerve-racking, and they read too much into every word.", "phrases": [["come across as", "seem to other people to be"], ["escalate", "become more serious or intense"], ["lose the habit of", "stop doing regularly"], ["nerve-racking", "making you very nervous"], ["read too much into", "find hidden meanings that are not there"]], "grammar": [{"pattern": "Reduced passive/when clause", "use": "when + past participle: shortened clause", "example": "when it was meant neutrally", "try": "…when it was meant ______."}, {"pattern": "Tend to", "use": "subject + tend to + base verb: a general tendency", "example": "arguments by text tend to escalate quickly", "try": "Online disputes tend to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000028', 1028, 'Topic 28', 'Ad with a famous person in it', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 28, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an ad with a famous person in it", "bullets": ["who the person is", "what the ad is about", "where you can see it", "how you feel about it"], "explain": "", "notes": ["Who", "What It’S About", "Where", "How I Feel"], "rounding": {"q": "Do you think advertisements with famous people influence you?", "model": {"answer": "A little, though probably less than they influence others. I notice the ad and remember the brand, but when it comes to buying something, I still compare prices and read reviews before deciding.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about a commercial that has stuck in my mind for years. It features Lionel Messi, who needs no introduction, in an advert for a well-known brand of potato crisps. I first saw it as a teenager, and I can still picture the opening scene. It starts with Messi strolling through a quiet neighbourhood, when a group of kids kicking a ball in the street spot him and freeze. Instead of showing off, he joins their game in an ordinary T-shirt and ends up losing to a ten-year-old, which cracks everyone up. At the end, they all share a packet of crisps on the kerb. There’s hardly any dialogue; the laughter does the work, and the product only appears in the last few seconds, which I thought was rather clever. I used to catch it on television during football matches, but these days it mostly turns up on YouTube, usually just before a video I actually want to watch, and occasionally on billboards near the stadium in Tashkent. I still find it appealing, mainly because it doesn’t feel like a hard sell. Had they simply shown him eating crisps, I’d have scrolled past it. Instead, it taps into something universal, the joy of playing with friends, and it makes a global star look down-to-earth. What I find interesting, though, is that I’ve never become a regular customer. The advert has left a lasting impression, but not a lasting habit, which proves that brand awareness and brand loyalty are two very different things.", "sections": [{"label": "Who", "text": "Let me tell you about a commercial that has stuck in my mind for years. It features Lionel Messi, who needs no introduction, in an advert for a well-known brand of potato crisps. I first saw it as a teenager, and I can still picture the opening scene."}, {"label": "What It’S About", "text": "It starts with Messi strolling through a quiet neighbourhood, when a group of kids kicking a ball in the street spot him and freeze. Instead of showing off, he joins their game in an ordinary T-shirt and ends up losing to a ten-year-old, which cracks everyone up. At the end, they all share a packet of crisps on the kerb. There’s hardly any dialogue; the laughter does the work, and the product only appears in the last few seconds, which I thought was rather clever."}, {"label": "Where", "text": "I used to catch it on television during football matches, but these days it mostly turns up on YouTube, usually just before a video I actually want to watch, and occasionally on billboards near the stadium in Tashkent."}, {"label": "How I Feel", "text": "I still find it appealing, mainly because it doesn’t feel like a hard sell. Had they simply shown him eating crisps, I’d have scrolled past it. Instead, it taps into something universal, the joy of playing with friends, and it makes a global star look down-to-earth. What I find interesting, though, is that I’ve never become a regular customer. The advert has left a lasting impression, but not a lasting habit, which proves that brand awareness and brand loyalty are two very different things."}], "phrases": [["stick in (someone’s) mind", "be remembered clearly"], ["need no introduction", "be so famous that everyone knows them"], ["show off", "try to impress people with your skills"], ["crack (someone) up", "make someone laugh a lot"], ["turn up", "appear, often unexpectedly"], ["hard sell", "aggressive, pushy way of selling"], ["scroll past", "ignore something while scrolling on a screen"], ["tap into", "make use of an existing feeling or need"], ["down-to-earth", "practical, friendly and not arrogant"], ["leave a lasting impression", "be remembered for a long time"], ["brand awareness", "how well people know a brand"], ["brand loyalty", "the habit of always buying the same brand"]], "grammar": [{"pattern": "Present perfect", "use": "has/have + past participle: from the past until now", "example": "a commercial that has stuck in my mind for years", "try": "It’s a song that has ______ for years."}, {"pattern": "Instead of + -ing", "use": "instead of + -ing: the opposite of what is expected", "example": "Instead of showing off, he joins their game", "try": "Instead of ______ing, she ______."}, {"pattern": "Non-defining which-clause", "use": "…, which + verb: comments on the previous idea", "example": "which cracks everyone up", "try": "…, which made ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, subject + would have + past participle", "example": "Had they simply shown him eating crisps, I’d have scrolled past it", "try": "Had they ______, I’d have ______."}, {"pattern": "Cleft sentence", "use": "What + I + verb + is + that-clause: highlights one idea", "example": "What I find interesting, though, is that I’ve never become a regular customer", "try": "What I find strange is that ______."}, {"pattern": "Used to", "use": "used to + base verb: a past habit", "example": "I used to catch it on television", "try": "I used to ______ on ______."}]}}, "part3": {"intro": "We’ve been talking about an ad with a famous person in it, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Ad with a famous person in it", "title": "Ad with a famous person in it", "questions": [{"q": "Why do companies use famous people in their advertisements?", "model": {"answer": "Mainly to grab attention. A familiar face stops viewers in seconds, which matters when everyone is scrolling past dozens of ads. Beyond that, consumers tend to transfer their admiration for the person to the product; if an athlete I respect vouches for a brand, I’m more inclined to give it a try. For a new company, that instant credibility can be worth an enormous fee.", "phrases": [["grab attention", "make people notice you immediately"], ["transfer", "move a feeling from one thing to another"], ["vouch for", "publicly say something is good or reliable"], ["give it a try", "test something"], ["instant credibility", "immediate trust"]], "grammar": [{"pattern": "Relative clause with which", "use": "…, which + verb: explains why something matters", "example": "which matters when everyone is scrolling past dozens of ads", "try": "…, which matters because ______."}, {"pattern": "First conditional", "use": "if + present simple, subject + am/is + more inclined to", "example": "if an athlete I respect vouches for a brand, I’m more inclined to give it a try", "try": "If a friend recommends ______, I’m more likely to ______."}]}}, {"q": "Do you think celebrity endorsements are effective?", "model": {"answer": "Sometimes, but it depends on whether it’s a good fit. A footballer promoting sports shoes is believable, whereas the same person advertising a bank may come across as forced. People are also more sceptical than they used to be, since everyone knows celebrities are paid. When it works, it usually boosts awareness rather than sales on its own: viewers remember the star, then forget the brand.", "phrases": [["believable", "easy to accept as true"], ["come across as", "give a certain impression"], ["a good fit", "suitable, matching well"], ["sceptical", "doubtful, not easily convinced"], ["boost awareness", "increase how well people know something"]], "grammar": [{"pattern": "Comparative with than they used", "use": "to more + adjective + than + used to", "example": "more sceptical than they used to be", "try": "People are more ______ than they used to be."}, {"pattern": "Since for reason", "use": "since + clause: a reason that is known", "example": "since everyone knows celebrities are paid", "try": "Since everyone knows ______, ______."}]}}, {"q": "Which is more effective, online advertising or newspaper advertising?", "model": {"answer": "Online, without a doubt, at least for reaching young people. Digital ads can be targeted at people’s interests, and companies can see immediately how many viewers clicked through, which lets them adjust the campaign. Newspaper ads still have a place, especially for local businesses and older readers who still enjoy a physical paper. But as print readership keeps shrinking, the balance has clearly shifted towards screens.", "phrases": [["targeted", "aimed at a specific group"], ["click through", "click a link in an advert"], ["adjust", "change slightly to improve"], ["have a place", "still be useful or relevant"], ["keep shrinking", "continue to become smaller"]], "grammar": [{"pattern": "Passive with modal", "use": "can be + past participle", "example": "Digital ads can be targeted at people’s interests", "try": "Messages can be ______ at ______."}, {"pattern": "As-clause of change", "use": "as + subject + verb, present perfect result", "example": "as print readership keeps shrinking, the balance has clearly shifted", "try": "As ______, the situation has ______."}]}}, {"q": "Do you think advertising has a positive influence on society?", "model": {"answer": "It cuts both ways. On the positive side, advertising funds a lot of free content, helps small businesses get off the ground and can raise awareness of issues such as road safety. On the other hand, it can fuel consumerism by making people feel they need things they don’t, and it often promotes unrealistic images of beauty, which affects teenagers most.", "phrases": [["fund", "pay for"], ["get off the ground", "start successfully"], ["raise awareness", "make people more informed about something"], ["fuel consumerism", "encourage people to buy more and more"], ["cut both ways", "have good and bad effects"]], "grammar": [{"pattern": "Two-sided structure", "use": "On the positive side, … On the other hand, …", "example": "On the other hand, it can fuel consumerism", "try": "On the one hand, ______. On the other hand, ______."}, {"pattern": "By + -ing", "use": "by + -ing: the method or cause", "example": "by making people feel they need things they don’t", "try": "It does harm by ______ing ______."}]}}, {"q": "What should advertisers take into account when they create an advert?", "model": {"answer": "First, the audience: a joke that works for teenagers may fall flat with their parents. Advertisers also need to be truthful, because exaggerated claims backfire once customers discover them. Another point is cultural sensitivity; an image that is harmless in one country can cause offence in another. If an ad crosses the line, the brand pays the price for years.", "phrases": [["fall flat", "fail to have the intended effect"], ["backfire", "have the opposite effect to the one intended"], ["sensitivity", "awareness of what might upset people"], ["cause offence", "upset or insult someone"], ["cross the line", "go beyond what is acceptable"]], "grammar": [{"pattern": "Defining relative clause", "use": "noun + that + verb", "example": "a joke that works for teenagers", "try": "An advert that ______ can ______."}, {"pattern": "Zero/first conditional", "use": "If + present simple, present simple", "example": "If an ad crosses the line, the brand pays the price for years", "try": "If a company ______, it ______."}]}}, {"q": "Should there be stricter rules about advertising to children?", "model": {"answer": "Yes, I’d support that, since children can’t yet tell entertainment from persuasion. They take adverts at face value and then pester their parents for sweets or toys. I’d ban promotions for sugary snacks during children’s programmes, and clamp down on hidden advertising by influencers online. Parents can’t supervise every screen, so some safeguards have to come from the rules themselves.", "phrases": [["take at face value", "accept without questioning"], ["pester", "keep asking in an annoying way"], ["supervise", "watch over and guide"], ["safeguard", "a protection against harm"], ["clamp down on", "take strict action against"]], "grammar": [{"pattern": "Would for a proposal", "use": "I’d + base verb: suggests a policy", "example": "I’d ban promotions for sugary snacks during children’s programmes", "try": "I’d introduce ______."}, {"pattern": "Modal have to", "use": "have to + base verb: necessity", "example": "some safeguards have to come from the rules themselves", "try": "Some changes have to come from ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000029', 1029, 'Topic 29', 'Boring place', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 29, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a boring place", "bullets": ["what place it is", "who you went there with", "what you did there", "why you think it’s boring"], "explain": "", "notes": ["What", "Who With", "What We Did", "Why It Was Boring"], "rounding": {"q": "Would you ever go back to a place like that?", "model": {"answer": "Probably, yes, if I heard it had been renovated. Museums have changed a lot, and many now use touch screens and storytelling, so I’d be curious to see whether it has finally come alive.", "phrases": [], "grammar": []}}, "model": {"answer": "The first place that springs to mind is a small regional museum in a town near Fergana. I won’t name it, because it has probably improved since then, but I visited when I was about fourteen, and I can still remember how the time dragged. We went on a school trip, all thirty of us, with our history teacher, Mr Karimov, who’d talked the visit up for days. He promised us “a journey through the ages”, so we were genuinely looking forward to it. In reality, we spent nearly three hours shuffling from one hall to another, reading yellowed labels behind glass. The lights were dim, the air was stuffy, and a guide droned on about dates we were supposed to memorise. I distinctly remember counting the ceiling tiles in the second room. By the end, half the class was sitting on the steps outside, desperate for fresh air. Looking back, it wasn’t the history itself that was dull; it was the way it was presented. Nothing was interactive, nobody told a story, and we were simply expected to take everything in. Had there been one hands-on exhibit, or a guide with a bit of enthusiasm, I think I’d have come away with a completely different impression. For me, a place is boring when you’re a passive spectator rather than a participant, and I’ve steered clear of that kind of exhibition ever since.", "sections": [{"label": "What", "text": "The first place that springs to mind is a small regional museum in a town near Fergana. I won’t name it, because it has probably improved since then, but I visited when I was about fourteen, and I can still remember how the time dragged."}, {"label": "Who With", "text": "We went on a school trip, all thirty of us, with our history teacher, Mr Karimov, who’d talked the visit up for days. He promised us “a journey through the ages”, so we were genuinely looking forward to it."}, {"label": "What We Did", "text": "In reality, we spent nearly three hours shuffling from one hall to another, reading yellowed labels behind glass. The lights were dim, the air was stuffy, and a guide droned on about dates we were supposed to memorise. I distinctly remember counting the ceiling tiles in the second room. By the end, half the class was sitting on the steps outside, desperate for fresh air."}, {"label": "Why It Was Boring", "text": "Looking back, it wasn’t the history itself that was dull; it was the way it was presented. Nothing was interactive, nobody told a story, and we were simply expected to take everything in. Had there been one hands-on exhibit, or a guide with a bit of enthusiasm, I think I’d have come away with a completely different impression. For me, a place is boring when you’re a passive spectator rather than a participant, and I’ve steered clear of that kind of exhibition ever since."}], "phrases": [["drag", "seem to pass very slowly"], ["talk (something) up", "make something sound better than it is"], ["look forward to", "feel excited about something in the future"], ["shuffle", "walk slowly without lifting your feet"], ["drone on", "talk in a dull, flat voice for a long time"], ["desperate for", "needing something very much"], ["hands-on", "involving direct practical activity"], ["enthusiasm", "strong interest and excitement"], ["come away with", "leave with a particular feeling or idea"], ["a passive spectator", "someone who only watches and does nothing"], ["steer clear of", "deliberately avoid"]], "grammar": [{"pattern": "Past perfect", "use": "had + past participle: before the trip", "example": "who’d talked the visit up for days", "try": "Our teacher, who’d ______ for days, ______."}, {"pattern": "Cleft sentence with it", "use": "It was + focus + that/who: emphasises the real reason", "example": "it wasn’t the history itself that was dull; it was the way it was presented", "try": "It wasn’t ______ that ______; it was ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, subject + would have + past participle", "example": "Had there been one hands-on exhibit, or a guide with a bit of enthusiasm, I think I’d have come away with a completely different impression", "try": "Had there been ______, I’d have ______."}, {"pattern": "Passive with expected", "use": "was/were expected to + base verb", "example": "we were simply expected to take everything in", "try": "We were expected to ______."}, {"pattern": "Past continuous", "use": "was/were + -ing: a situation in progress", "example": "half the class was sitting on the steps outside", "try": "Half the class was ______ing when ______."}]}}, "part3": {"intro": "We’ve been talking about a boring place, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Boring place", "title": "Boring place", "questions": [{"q": "What can people do to overcome boredom?", "model": {"answer": "Changing what you’re doing, even slightly, usually helps. A ten-minute walk, a phone call with a friend or tidying your desk can break the monotony. For longer-term boredom, it’s better to take up a new hobby or set yourself a challenge, such as learning ten words a day. And in a dull meeting, jotting down a to-do list keeps your mind occupied.", "phrases": [["break the monotony", "stop something from being repetitive"], ["take up", "start a new activity"], ["set yourself a challenge", "decide on a goal to aim for"], ["occupied", "busy, not idle"], ["jot down", "write quickly and briefly"]], "grammar": [{"pattern": "Gerund as subject", "use": "-ing phrase + verb: an action as the subject", "example": "Changing what you’re doing, even slightly, usually helps", "try": "Taking a short walk often ______."}, {"pattern": "It’s better to", "use": "It’s better to + base verb", "example": "it’s better to take up a new hobby", "try": "It’s better to ______ than to ______."}]}}, {"q": "Do young people get bored more quickly than older people?", "model": {"answer": "Probably, and technology is a big reason. Having grown up with phones, young people are used to constant stimulation, so a quiet bus ride can feel unbearable. Older people, on the other hand, remember waiting without any entertainment, so they’ve built up more patience. Mind you, teenagers also have more free time and fewer responsibilities, which makes boredom more likely.", "phrases": [["constant stimulation", "something exciting happening all the time"], ["unbearable", "too unpleasant to accept"], ["patience", "ability to wait calmly"], ["free time", "time when you are not working or studying"], ["build up", "gradually develop"]], "grammar": [{"pattern": "Perfect participle clause", "use": "Having + past participle, clause", "example": "Having grown up with phones, young people are used to constant stimulation", "try": "Having grown up with ______, they ______."}, {"pattern": "Be used to", "use": "be used to + noun: familiar with", "example": "young people are used to constant stimulation", "try": "People today are used to ______."}]}}, {"q": "In what situations do people usually feel bored?", "model": {"answer": "Typically when they’re stuck waiting or doing something repetitive, like filling in forms: queues at the bank, long journeys or lessons that drag on. Interestingly, it’s often the lack of control that matters. If I can choose what to do, even a quiet Sunday feels pleasant, but if I’m forced to sit through a long, rambling talk, I’m checking the clock after ten minutes.", "phrases": [["stuck", "unable to move or leave a situation"], ["drag on", "continue for too long"], ["lack of control", "not having the power to decide"], ["sit through", "stay until the end of something dull"], ["repetitive", "done again and again"]], "grammar": [{"pattern": "Cleft with it", "use": "It’s + often + the + noun + that + verb", "example": "it’s often the lack of control that matters", "try": "It’s often the ______ that matters."}, {"pattern": "Contrast conditionals", "use": "If + present, present … but if …", "example": "If I can choose what to do, even a quiet Sunday feels pleasant", "try": "If I can ______, ______."}]}}, {"q": "Why do some people get bored more easily than others?", "model": {"answer": "Partly personality: people who crave excitement, thrill-seekers you might call them, need more stimulation than other people. Another factor is imagination; someone who can daydream or entertain themselves with a book is rarely bored. Then there’s habit. The more we rely on screens, the less tolerance we build for quiet. So in the end it’s a mix of natural temperament and training.", "phrases": [["thrill-seeker", "a person who loves excitement and risk"], ["entertain yourself", "find ways to enjoy yourself without help"], ["less tolerance", "a lower ability to put up with something"], ["daydream", "think about pleasant things while awake"], ["crave", "want very strongly"]], "grammar": [{"pattern": "The more… the less", "use": "The more + clause, the less + noun + clause", "example": "The more we rely on screens, the less tolerance we build for quiet", "try": "The more ______, the less ______."}, {"pattern": "Relative clause with who", "use": "noun + who + verb", "example": "someone who can daydream or entertain themselves", "try": "Someone who can ______ is rarely ______."}]}}, {"q": "Do you think having a daily routine is boring?", "model": {"answer": "It can be, but not necessarily. A rigid routine, with the same tasks in the same order every day, can become mind-numbing. Yet a loose structure actually gives you stability and frees you up to do what you enjoy. My mornings are routine, but I keep my evenings flexible, and that balance stops me from getting stuck in a rut.", "phrases": [["mind-numbing", "so boring that you stop thinking"], ["stability", "a steady, predictable situation"], ["flexible", "able to change easily"], ["get stuck in a rut", "fall into a boring, unchanging pattern"], ["rigid", "fixed and unable to change"]], "grammar": [{"pattern": "Free-up phrasal verb", "use": "give someone + noun + and free + up", "example": "gives you stability and frees you up to do what you enjoy", "try": "A schedule frees you up to ______."}, {"pattern": "Stop + object + from -ing", "use": "stop + me + from + -ing", "example": "that balance stops me from getting stuck in a rut", "try": "That habit stops me from ______."}]}}, {"q": "Some people say it is good to feel bored sometimes. What do you think?", "model": {"answer": "I’d agree, within limits. When we’re bored, the mind wanders, and that’s often when good ideas come to the surface. Children with a few unstructured afternoons a week invent their own games, which builds resourcefulness. Constant entertainment, by contrast, leaves no space for reflection. Of course, chronic boredom at work or school is a problem, but an occasional quiet hour does us good.", "phrases": [["come to the surface", "become noticed or appear"], ["invent their own games", "create new games from nothing"], ["resourcefulness", "skill at finding ways to solve problems"], ["reflection", "serious thought about something"], ["chronic boredom", "boredom that lasts for a long time"]], "grammar": [{"pattern": "That’s when", "use": "that’s often when + clause: emphasises time", "example": "that’s often when good ideas come to the surface", "try": "That’s often when ______."}, {"pattern": "By contrast", "use": "X. Y, by contrast, …", "example": "Constant entertainment, by contrast, leaves no space for reflection", "try": "Routine work, by contrast, ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000030', 1030, 'Topic 30', 'Interesting video', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 30, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an interesting video", "bullets": ["what it is about", "when and where you watched it", "why you watched it", "how you feel about it"], "explain": "", "notes": ["What", "When And Where", "Why I Watched", "How I Feel"], "rounding": {"q": "Do you often watch documentaries like that?", "model": {"answer": "Fairly often, usually on weekends when I have time to focus. I prefer ones about people and their work, because they give me ideas about how to approach my own studies.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one video, it would be a short documentary about a ceramics master in Rishtan, a town famous for its blue-and-turquoise pottery. It follows an old craftsman called Usto Akbar through a single day in his workshop, from digging the clay to firing the finished plates, and it lingers on every small movement of his hands. I watched it last autumn, on a rainy Sunday afternoon, curled up on the sofa with my laptop. I remember the rain against the window, which oddly made the slow pace of the film feel even more soothing. The reason I clicked on it was that my cousin, who’s a designer, kept raving about it. I’d been in a creative rut for weeks, and she swore it would snap me out of it. I expected twenty minutes of pleasant background noise. Instead, I was glued to the screen from start to finish. What fascinated me was the precision. Every brushstroke was done by hand, and the master spoke about patience as if it were an ingredient. One line stuck with me: “You can’t hurry clay.” It felt a world away from the endless scrolling I usually do. Since then I’ve watched it twice, and last month I even signed up for a pottery workshop. The video reminded me that real craftsmanship takes time, and that being fully absorbed in something is a kind of rest.", "sections": [{"label": "What", "text": "If I had to pick one video, it would be a short documentary about a ceramics master in Rishtan, a town famous for its blue-and-turquoise pottery. It follows an old craftsman called Usto Akbar through a single day in his workshop, from digging the clay to firing the finished plates, and it lingers on every small movement of his hands."}, {"label": "When And Where", "text": "I watched it last autumn, on a rainy Sunday afternoon, curled up on the sofa with my laptop. I remember the rain against the window, which oddly made the slow pace of the film feel even more soothing."}, {"label": "Why I Watched", "text": "The reason I clicked on it was that my cousin, who’s a designer, kept raving about it. I’d been in a creative rut for weeks, and she swore it would snap me out of it. I expected twenty minutes of pleasant background noise. Instead, I was glued to the screen from start to finish."}, {"label": "How I Feel", "text": "What fascinated me was the precision. Every brushstroke was done by hand, and the master spoke about patience as if it were an ingredient. One line stuck with me: “You can’t hurry clay.” It felt a world away from the endless scrolling I usually do. Since then I’ve watched it twice, and last month I even signed up for a pottery workshop. The video reminded me that real craftsmanship takes time, and that being fully absorbed in something is a kind of rest."}], "phrases": [["linger on", "spend time showing or dwelling on"], ["soothing", "calming and comforting"], ["rave about", "talk about with great enthusiasm"], ["in a creative rut", "stuck without new ideas"], ["snap (someone) out of it", "help someone stop feeling stuck or low"], ["glued to the screen", "unable to look away"], ["stick with (someone)", "stay in someone’s memory"], ["a world away from", "completely different from"], ["sign up for", "register to take part in"], ["craftsmanship", "skill in making things by hand"], ["fully absorbed", "completely focused and interested"]], "grammar": [{"pattern": "Past perfect", "use": "had/’d been + …: a state before a past moment", "example": "I’d been in a creative rut for weeks", "try": "I’d been ______ for weeks when ______."}, {"pattern": "Cleft with The reason", "use": "The reason + subject + verb + was that-clause", "example": "The reason I clicked on it was that my cousin, who’s a designer, kept raving about it", "try": "The reason I chose it was that ______."}, {"pattern": "Non-defining which-clause", "use": "…, which + adverb + verb: comment on a detail", "example": "which oddly made the slow pace of the film feel even more soothing", "try": "…, which oddly made ______."}, {"pattern": "As if", "use": "as if + past tense: a comparison", "example": "as if it were an ingredient", "try": "She spoke as if it were ______."}, {"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If I had to pick one video, it would be a short documentary", "try": "If I had to choose, it would be ______."}, {"pattern": "Cleft with What", "use": "What + verb + me + was + noun", "example": "What fascinated me was the precision", "try": "What fascinated me was ______."}]}}, "part3": {"intro": "We’ve been talking about an interesting video, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Interesting video", "title": "Interesting video", "questions": [{"q": "Do teachers use videos in the classroom in your country?", "model": {"answer": "Increasingly, yes, though it varies from school to school. In well-equipped classrooms, teachers show short clips to illustrate a science experiment or a historical event, which brings the topic to life. In rural areas, limited equipment and an unreliable internet connection are obstacles. Language teachers especially love videos, because students hear authentic pronunciation. Still, the best teachers use them sparingly, as a starting point for discussion.", "phrases": [["illustrate", "show or explain clearly with an example"], ["bring to life", "make interesting and real"], ["limited equipment", "not enough tools or devices"], ["authentic", "real, not artificial"], ["sparingly", "in small amounts"]], "grammar": [{"pattern": "Non-defining which-clause", "use": "…, which + verb", "example": "which brings the topic to life", "try": "…, which makes lessons ______."}, {"pattern": "Superlative", "use": "the best + noun + verb", "example": "the best teachers use them sparingly", "try": "The best ______ never ______."}]}}, {"q": "Why are so many young people obsessed with short videos?", "model": {"answer": "They’re designed to be addictive. Each clip lasts under a minute and the next starts automatically, so there’s no natural moment to stop. They also offer instant gratification without effort, plus a sense of belonging when everyone shares the same trends. Had these apps existed when I was a teenager, I’d probably have lost whole afternoons to them as well.", "phrases": [["designed to be addictive", "made so that people keep using it"], ["gratification", "pleasure from getting what you want"], ["a sense of belonging", "feeling part of a group"], ["lose whole afternoons", "spend hours without noticing"], ["natural moment", "obvious point"]], "grammar": [{"pattern": "Inverted third conditional", "use": "Had + subject + past participle, subject + would have + past participle", "example": "Had these apps existed when I was a teenager, I’d probably have lost whole afternoons to them", "try": "Had ______ existed, I’d have ______."}, {"pattern": "Passive infinitive", "use": "be designed to + base verb", "example": "They’re designed to be addictive", "try": "They’re designed to ______."}]}}, {"q": "What are the advantages of learning from videos rather than from books?", "model": {"answer": "Videos can demonstrate things that are hard to describe in words: how to tie a tie, how an engine works or how to pronounce a tricky word. They also combine sound, image and movement, which helps information stick. Books, however, go into more depth and demand concentration. So for practical skills I’d choose video, but for abstract ideas a good book usually wins.", "phrases": [["demonstrate", "show how something is done"], ["help information stick", "make facts easier to remember"], ["go into depth", "explain in detail"], ["abstract ideas", "ideas about concepts, not physical things"], ["tricky", "difficult"]], "grammar": [{"pattern": "Hard to + verb", "use": "adjective + to + verb", "example": "things that are hard to describe", "try": "Skills that are hard to ______."}, {"pattern": "Contrast with however", "use": "Subject, however, + verb", "example": "Books, however, go into more depth", "try": "Videos are fast; books, however, ______."}]}}, {"q": "Do you think watching too many videos is harmful?", "model": {"answer": "In excess, yes. Hours in front of a screen cut into sleep and exercise, and passive watching doesn’t exercise the mind the way reading does. Some people also find it harder to concentrate on longer tasks afterwards. That said, the problem isn’t videos themselves but the quantity. An hour of a good documentary after dinner is hardly harmful; five hours of random clips probably is.", "phrases": [["cut into", "reduce the time available for"], ["exercise the mind", "make the brain work"], ["concentrate", "focus your attention"], ["in excess", "too much"], ["random", "without any plan"]], "grammar": [{"pattern": "Comparison with the way", "use": "the way + clause", "example": "the way reading does", "try": "It doesn’t train the brain the way ______ does."}, {"pattern": "Not X but Y", "use": "the problem isn’t X but Y", "example": "the problem isn’t videos themselves but the quantity", "try": "The problem isn’t ______ but ______."}]}}, {"q": "What kinds of videos are popular in your country?", "model": {"answer": "From what I see, comedy sketches and music videos are hugely popular, along with vlogs about daily life in Uzbek and Russian. Cooking videos, especially about traditional dishes such as plov, get a lot of views, and so do tutorials on everything from English to car repair. Among teenagers, short clips and gaming streams dominate, whereas their parents tend to prefer TV series and the news.", "phrases": [["comedy sketch", "a short funny scene"], ["traditional dish", "a food from long-standing local culture"], ["tutorial", "a video that teaches a skill"], ["dominate", "be the most common or powerful"], ["get a lot of views", "be watched by many people"]], "grammar": [{"pattern": "So do", "use": "so + do/does + subject: agreeing with a positive statement", "example": "and so do tutorials on everything from English to car repair", "try": "Comedy gets a lot of views, and so do ______."}, {"pattern": "Contrast with whereas", "use": "clause, whereas + clause", "example": "whereas their parents tend to prefer TV series and the news", "try": "Teens like ______, whereas parents ______."}]}}, {"q": "Do you think video platforms will replace television in the future?", "model": {"answer": "Gradually, I think, at least for younger viewers. Platforms let you watch on demand, so nobody has to wait for a programme at a fixed time, and many families already have smart TVs that stream everything. Television may survive, though, for live events such as football finals, where sharing the moment matters. So it will probably shrink instead of disappearing altogether.", "phrases": [["on demand", "whenever you want"], ["wait for", "stay until something happens"], ["survive", "continue to exist"], ["share the moment", "experience something together"], ["disappear altogether", "vanish completely"]], "grammar": [{"pattern": "Let + object + verb", "use": "let + person + base verb", "example": "Platforms let you watch on demand", "try": "Apps let you ______."}, {"pattern": "Prediction with will probably", "use": "will probably + base verb", "example": "it will probably shrink instead of disappearing altogether", "try": "It will probably ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000031', 1031, 'Topic 31', 'Story or book with animals in it', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 31, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a story or book with animals in it", "bullets": ["what it is about", "what animals are in it", "why you read it", "what you think of it"], "explain": "", "notes": ["What", "Animals", "Why", "Opinion"], "rounding": {"q": "Would you recommend it to a younger child?", "model": {"answer": "Not to a very young one, no. The ending is quite bleak, so I’d wait until they’re around twelve, old enough to see the political meaning behind the story.", "phrases": [], "grammar": []}}, "model": {"answer": "The first thing that comes to mind is Animal Farm by George Orwell, which my literature teacher, Mr Karimov, had us read when I was sixteen. On the surface it’s a simple tale about farm animals who drive out their careless owner and decide to run the farm themselves. But the story soon takes a dark turn, because the pigs seize power and the others end up working harder than ever. The cast is unforgettable. Napoleon and Snowball, the two pigs, are at each other’s throats over who should lead. Boxer, a huge, loyal carthorse, works himself to the bone, convinced that his own effort will fix everything. Then there’s Benjamin, an old donkey who sees through it all but never speaks up, which is probably the most realistic character of the lot. I read it simply because it was on our syllabus, and I’d expected it to be dull. Had I known how gripping it was, I’d have started months earlier. In fact, I finished it in two evenings, staying up late reading under the blanket with a torch because my mother kept telling me to go to sleep. What struck me most was Boxer’s fate. I remember closing the book and just staring at the wall for a while. It’s the kind of story that leaves a lasting impression, and even now, whenever I hear a politician making big promises, I think of those pigs. Looking back, it taught me that a book doesn’t have to be long or complicated to hit home; it only has to be honest. Animals just happen to be a surprisingly effective vehicle for saying uncomfortable things.", "sections": [{"label": "What", "text": "The first thing that comes to mind is Animal Farm by George Orwell, which my literature teacher, Mr Karimov, had us read when I was sixteen. On the surface it’s a simple tale about farm animals who drive out their careless owner and decide to run the farm themselves. But the story soon takes a dark turn, because the pigs seize power and the others end up working harder than ever."}, {"label": "Animals", "text": "The cast is unforgettable. Napoleon and Snowball, the two pigs, are at each other’s throats over who should lead. Boxer, a huge, loyal carthorse, works himself to the bone, convinced that his own effort will fix everything. Then there’s Benjamin, an old donkey who sees through it all but never speaks up, which is probably the most realistic character of the lot."}, {"label": "Why", "text": "I read it simply because it was on our syllabus, and I’d expected it to be dull. Had I known how gripping it was, I’d have started months earlier. In fact, I finished it in two evenings, staying up late reading under the blanket with a torch because my mother kept telling me to go to sleep."}, {"label": "Opinion", "text": "What struck me most was Boxer’s fate. I remember closing the book and just staring at the wall for a while. It’s the kind of story that leaves a lasting impression, and even now, whenever I hear a politician making big promises, I think of those pigs."}, {"label": "Reflection", "text": "Looking back, it taught me that a book doesn’t have to be long or complicated to hit home; it only has to be honest. Animals just happen to be a surprisingly effective vehicle for saying uncomfortable things."}], "phrases": [["come to mind", "be the first thing you think of"], ["on the surface", "at first sight, before you look deeper"], ["drive out", "force someone to leave a place"], ["take a dark turn", "become much more serious or disturbing"], ["seize power", "take control by force"], ["at each other’s throats", "fighting or arguing fiercely"], ["work yourself to the bone", "work extremely hard until exhausted"], ["see through (something)", "realise the truth behind something, not be fooled"], ["stay up", "not go to bed, remain awake"], ["leave a lasting impression", "have an effect you remember for a long time"], ["hit home", "have a strong emotional effect because it feels true"], ["effective vehicle", "a very useful means of expressing an idea"]], "grammar": [{"pattern": "", "use": "Causative: have + person + base verb had + object + base verb: someone made us do something", "example": "which my literature teacher, Mr Karimov, had us read", "try": "Our teacher had us ______ every week."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, would have + past participle", "example": "Had I known how gripping it was, I’d have started months earlier", "try": "Had I known, I’d have ______."}, {"pattern": "Participle clause", "use": "-ing phrase giving how or while something happened", "example": "staying up late reading under the blanket with a torch", "try": "______ on the sofa, I finished the whole book."}, {"pattern": "Adjective + that-clause", "use": "convinced / sure / certain + that + clause", "example": "convinced that his own effort will fix everything", "try": "He’s convinced that ______."}, {"pattern": "Defining relative clause", "use": "the kind of + noun + that + verb", "example": "It’s the kind of story that leaves a lasting impression", "try": "It’s the kind of film that ______."}, {"pattern": "Whenever + present simple", "use": "whenever + present simple, present simple: a repeated reaction", "example": "whenever I hear a politician making big promises, I think of those pigs", "try": "Whenever I smell fresh bread, I ______."}]}}, "part3": {"intro": "We’ve been talking about a story or book with animals in it, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Story or book with animals in it", "title": "Story or book with animals in it", "questions": [{"q": "Why do so many children’s stories feature animals?", "model": {"answer": "Partly because animals let writers tackle difficult subjects without upsetting children. A story about a lonely rabbit feels much safer than one about a lonely child, yet the child still identifies with the feeling. Animals also work as shorthand: a fox is cunning, a tortoise is patient, so authors can get the message across in a few lines instead of spelling out every trait.", "phrases": [["tackle", "deal with a difficult topic directly"], ["identify with", "feel that you understand and share someone’s feelings"], ["shorthand", "a quick, simple way of expressing something"], ["get the message across", "make people understand your point"], ["spell out", "explain something in full detail"]], "grammar": [{"pattern": "", "use": "Comparison: much + comparative much + comparative + than", "example": "feels much safer than one about a lonely child", "try": "Learning feels much ______ than ______."}, {"pattern": "Colon for explanation", "use": "statement + colon + example", "example": "a fox is cunning, a tortoise is patient", "try": "Animals show character: a lion is ______, a mouse is ______."}]}}, {"q": "Why do people keep pets?", "model": {"answer": "Companionship, first and foremost. Coming home to a dog that’s thrilled to see you lifts your spirits, especially if you live on your own. There’s a routine benefit too: an animal that needs feeding and walking gives structure to the day. And for families, a pet can teach children responsibility, although in my experience the parents usually end up doing most of the work.", "phrases": [["first and foremost", "above all, most importantly"], ["lift your spirits", "make you feel happier"], ["give structure to", "make a day more organised and regular"], ["teach children responsibility", "help children learn to look after others"], ["end up doing", "finally do something, often unexpectedly"]], "grammar": [{"pattern": "Gerund as subject", "use": "-ing phrase + verb", "example": "Coming home to a dog that’s thrilled to see you lifts your spirits", "try": "Waking up early ______."}, {"pattern": "Defining relative clause", "use": "an + noun + that + verb", "example": "an animal that needs feeding and walking", "try": "a hobby that ______."}]}}, {"q": "What are the disadvantages of keeping a pet?", "model": {"answer": "Cost is the obvious one. Vet bills add up quickly, and a pet ties you down: you can’t simply book a last-minute holiday without finding someone to look after it. In a small flat there’s also noise and mess, and allergies can be a real problem for some families. Anyone thinking of getting a pet should weigh up all of that first.", "phrases": [["add up", "gradually become a large total"], ["tie (someone) down", "limit your freedom to do what you want"], ["look after", "take care of"], ["think of (doing)", "consider doing something"], ["weigh up", "consider the good and bad points carefully"]], "grammar": [{"pattern": "Without + -ing", "use": "without + gerund", "example": "without finding someone to look after it", "try": "You can’t leave without ______."}, {"pattern": "Anyone + participle + should", "use": "Anyone + -ing phrase + should + base verb", "example": "Anyone thinking of getting a pet should weigh up all of that first", "try": "Anyone planning to ______ should ______."}]}}, {"q": "How is the way people treat pets different from the past?", "model": {"answer": "Pets used to be working animals: dogs guarded the house, cats caught mice, and nobody thought of them as family. Nowadays many owners treat their pets like family, buying them special food, winter coats, even birthday cakes. Whether that’s healthy is debatable, but animal welfare has certainly come a long way, and cruelty is frowned upon far more than it was.", "phrases": [["used to", "describes a past habit or situation that is no longer true"], ["treat their pets like family", "behave towards animals as if they were relatives"], ["debatable", "not certain, open to argument"], ["come a long way", "make great progress"], ["frown upon", "disapprove of"]], "grammar": [{"pattern": "used to + base verb", "use": "used to + infinitive: past state or habit", "example": "Pets used to be working animals", "try": "Cities used to be ______."}, {"pattern": "Noun clause as subject", "use": "Whether + clause + is + adjective", "example": "Whether that’s healthy is debatable", "try": "Whether it’s fair is ______."}]}}, {"q": "Do you think it is safe for animals to live in cities?", "model": {"answer": "Not really, at least not for all of them. Traffic is by far the biggest danger, and stray dogs and cats struggle to find food and shelter, particularly in winter. That said, some species have adapted remarkably well; pigeons and foxes seem to thrive on what people leave behind. If cities planted more trees and parks, wildlife would stand a better chance.", "phrases": [["stray", "without an owner or home"], ["struggle to", "find it hard to do something"], ["that said", "however, despite that"], ["thrive", "grow and live very successfully"], ["stand a better chance", "be more likely to succeed or survive"]], "grammar": [{"pattern": "", "use": "Concession: that said that said + clause", "example": "That said, some species have adapted remarkably well", "try": "That said, ______."}, {"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If cities planted more trees and parks, wildlife would stand a better chance", "try": "If cities ______, animals would ______."}]}}, {"q": "Should schools teach children about animals and nature?", "model": {"answer": "Definitely, and the earlier the better. Children who spend time outdoors tend to grow into adults who care about the environment, which is hard to learn from a textbook. Even a small school garden or a trip to a farm can spark curiosity. If we want the next generation to look after the planet, then that has to start in the classroom.", "phrases": [["tend to", "usually do something"], ["grow into", "gradually become"], ["spark curiosity", "make someone start to be interested"], ["look after", "protect and care for"], ["start in the classroom", "begin with education at school"]], "grammar": [{"pattern": "the + comparative, the +", "use": "comparative (short form) the + comparative (the earlier the better)", "example": "the earlier the better", "try": "The ______ the better."}, {"pattern": "Relative clause with which", "use": "clause + , which + verb: comments on the whole idea", "example": "which is hard to learn from a textbook", "try": "______, which is ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000032', 1032, 'Topic 32', 'Person who wants to work in the medical field', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 32, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person you know who would like to work in the medical field", "bullets": ["how you know them", "what they would like to do", "when they started to think about that", "why they would like to choose this career"], "explain": "", "notes": ["Who", "What", "When", "Why"], "rounding": {"q": "Do you think she will make a good doctor?", "model": {"answer": "Without a doubt. She’s patient, she listens carefully and she doesn’t give up easily, which are exactly the qualities patients need.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be my cousin Dilnoza, who’s set her heart on becoming a paediatrician. We’ve been close since childhood, mainly because our families live a few streets apart in Samarkand, and we grew up more like sisters than cousins. She’s in her second year at medical university now, and her plan is to specialise in children’s medicine, ideally in a regional hospital where doctors are in short supply. She has even talked about volunteering at a rural clinic during her summer holidays. The idea took root when she was about ten. Her little brother had come down with severe pneumonia, and she watched a young doctor stay at his bedside through the night. ‘She didn’t say much,’ Dilnoza told me once, ‘but my mother finally stopped shaking.’ From that moment on, she never wavered. As for why, I think it’s a mixture of compassion and a love of problem-solving. She’s the sort of person who can’t bear seeing anyone suffer, yet she stays level-headed under pressure. Not only does she study for hours, but she also keeps up with the latest research, and she pulls all-nighters before exams without complaining. With long hours and years of training ahead of her, it won’t be easy, but she takes it in her stride. What I admire most is that she has never been after the money. Watching her has put things into perspective for me: a career can be a calling, not just a salary.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be my cousin Dilnoza, who’s set her heart on becoming a paediatrician. We’ve been close since childhood, mainly because our families live a few streets apart in Samarkand, and we grew up more like sisters than cousins."}, {"label": "What", "text": "She’s in her second year at medical university now, and her plan is to specialise in children’s medicine, ideally in a regional hospital where doctors are in short supply. She has even talked about volunteering at a rural clinic during her summer holidays."}, {"label": "When", "text": "The idea took root when she was about ten. Her little brother had come down with severe pneumonia, and she watched a young doctor stay at his bedside through the night. ‘She didn’t say much,’ Dilnoza told me once, ‘but my mother finally stopped shaking.’ From that moment on, she never wavered."}, {"label": "Why", "text": "As for why, I think it’s a mixture of compassion and a love of problem-solving. She’s the sort of person who can’t bear seeing anyone suffer, yet she stays level-headed under pressure. Not only does she study for hours, but she also keeps up with the latest research, and she pulls all-nighters before exams without complaining. With long hours and years of training ahead of her, it won’t be easy, but she takes it in her stride."}, {"label": "Reflection", "text": "What I admire most is that she has never been after the money. Watching her has put things into perspective for me: a career can be a calling, not just a salary."}], "phrases": [["set your heart on", "want something very much and be determined to get it"], ["grow up", "spend your childhood"], ["in short supply", "not available in large enough amounts"], ["take root", "begin to develop and grow strong"], ["come down with", "become ill with"], ["waver", "hesitate or become uncertain about a decision"], ["can’t bear", "find something impossible to tolerate"], ["level-headed", "calm and sensible in difficult situations"], ["keep up with", "stay informed about the latest developments"], ["pull an all-nighter", "stay up all night studying or working"], ["take it in your stride", "deal with something difficult calmly"], ["put things into perspective", "help you see what really matters"]], "grammar": [{"pattern": "Present perfect", "use": "has / have + past participle: a plan or state linked to now", "example": "who’s set her heart on becoming a paediatrician", "try": "She’s always ______ about becoming ______."}, {"pattern": "Past perfect", "use": "had + past participle: an event before the main past time", "example": "Her little brother had come down with severe pneumonia", "try": "By the time I arrived, she had already ______."}, {"pattern": "Perception verb + bare infinitive", "use": "watch / see + object + base verb: you saw the whole action", "example": "she watched a young doctor stay at his bedside through the night", "try": "I watched my father ______ the whole car."}, {"pattern": "", "use": "Inversion: Not only … but also Not only + auxiliary + subject + verb, but … also …", "example": "Not only does she study for hours, but she also keeps up with the latest research", "try": "Not only does he ______, but he also ______."}, {"pattern": "With + noun + ahead of With + noun phrase + ahead of + her,", "use": "clause: a reason or condition", "example": "With long hours and years of training ahead of her, it won’t be easy", "try": "With a busy week ahead of me, ______."}, {"pattern": "Cleft sentence", "use": "What + subject + verb + is + that-clause", "example": "What I admire most is that she has never been after the money", "try": "What surprised me most was that ______."}]}}, "part3": {"intro": "We’ve been talking about a person you know who would like to work in the medical field, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who wants to work in the medical field", "title": "Person who wants to work in the medical field", "questions": [{"q": "Do you think everyone should learn basic first aid?", "model": {"answer": "Yes, I’d even make it compulsory. Accidents happen without warning, and in the first few minutes the person standing nearest is usually the only help available. Knowing how to stop the bleeding or start CPR can mean the difference between life and death. It needn’t take long either; a one-day course every few years would be enough to give ordinary people the confidence to step in.", "phrases": [["without warning", "suddenly, with no signal beforehand"], ["stop the bleeding", "prevent someone losing more blood"], ["the difference between life and death", "what decides whether someone survives"], ["be enough to", "be sufficient to"], ["step in", "get involved to help in a difficult situation"], ["compulsory", "required by law or rules"]], "grammar": [{"pattern": "Would + base verb for suggestions", "use": "I’d + base verb + even: a strong personal proposal", "example": "I’d even make it compulsory", "try": "I’d even ______."}, {"pattern": "Needn’t + base verb", "use": "needn’t + infinitive: it is not necessary", "example": "It needn’t take long either", "try": "It needn’t ______ a lot of money."}]}}, {"q": "What is the difference between the work of a doctor and that of a nurse?", "model": {"answer": "Broadly speaking, doctors diagnose conditions and decide on treatment, whereas nurses carry out that treatment and monitor patients day to day. Nurses therefore spend far more time at the bedside, which makes them the ones who pick up on small changes. In practice, though, the roles overlap quite a lot, and a good hospital runs on teamwork rather than a strict hierarchy.", "phrases": [["broadly speaking", "in general, without going into detail"], ["diagnose", "identify an illness from its symptoms"], ["carry out", "perform or complete a task"], ["pick up on", "notice something subtle"], ["run on", "depend on something to function"]], "grammar": [{"pattern": "Contrast with whereas", "use": "clause + , whereas + clause", "example": "doctors diagnose conditions and decide on treatment, whereas nurses carry out that treatment", "try": "Teachers plan lessons, whereas ______."}, {"pattern": "the ones who", "use": "the ones who + verb: identifies a group", "example": "which makes them the ones who pick up on small changes", "try": "Parents are often the ones who ______."}]}}, {"q": "Why do some children want to become doctors when they grow up?", "model": {"answer": "Probably because it’s a job they can easily picture. Children meet doctors when they’re ill, and a kind one leaves a strong impression. They also link the profession with helping people, and with a rather heroic white coat. Of course, the reality is more down to earth, but that early image stays with them, and for some it eventually turns into a genuine ambition.", "phrases": [["leave a strong impression", "make someone remember you"], ["link (something) with", "connect an idea with something else"], ["down to earth", "practical and realistic"], ["stay with (someone)", "remain in the memory for a long time"], ["turn into", "gradually become"]], "grammar": [{"pattern": "Reason with because + pronoun", "use": "Probably because + clause (a short answer)", "example": "Probably because it’s a job they can easily picture", "try": "Probably because ______."}, {"pattern": "Comparative with more + adjective", "use": "more + adjective + than expected", "example": "the reality is more down to earth", "try": "The reality is more ______."}]}}, {"q": "Is being a doctor an easy job?", "model": {"answer": "Far from it. Not only are the hours long, with night shifts that take a toll on your health, but doctors also carry the weight of decisions that affect people’s lives. Years of training come before any of that, and the learning never really stops. Having said that, many doctors insist that watching a patient make a full recovery is worth every sacrifice.", "phrases": [["far from it", "not at all, the opposite"], ["take a toll on", "have a harmful effect on"], ["carry the weight of", "bear the responsibility for"], ["having said that", "however, despite that"], ["make a full recovery", "become completely healthy again"]], "grammar": [{"pattern": "Inversion after Not only", "use": "Not only + be + subject, but also", "example": "Not only are the hours long", "try": "Not only is the work ______, but ______."}, {"pattern": "Relative clause with that", "use": "noun + that + verb", "example": "night shifts that take a toll on your health", "try": "jobs that ______."}]}}, {"q": "Should governments invest more money in medical research?", "model": {"answer": "Yes, although it has to be done wisely. Research pays for itself in the long run, because a single new vaccine can save far more than it costs. Private companies tend to chase profitable drugs, so public money is what keeps rare diseases from being forgotten. If governments cut back on research now, we’d be much less prepared for the next outbreak.", "phrases": [["pay for itself", "earn back the money spent on it"], ["in the long run", "over a long period of time"], ["tend to", "usually do something"], ["chase", "pursue eagerly"], ["cut back on", "spend less on"]], "grammar": [{"pattern": "Cleft sentence", "use": "public money + is what + verb", "example": "public money is what keeps rare diseases from being forgotten", "try": "Time is what ______."}, {"pattern": "Second conditional", "use": "If + present simple, would + base verb: a warning", "example": "If governments cut back on research now, we’d be much less prepared", "try": "If we ignore this problem, ______."}]}}, {"q": "Why is there sometimes a shortage of doctors in certain areas?", "model": {"answer": "Mostly because of money and lifestyle. Doctors gravitate towards big cities, where salaries are higher, hospitals are better equipped and their children can attend good schools. Remote villages, by contrast, struggle to attract them, however badly they’re needed. Unless governments offer incentives such as housing or higher pay, the imbalance will probably persist for years, leaving rural patients to travel long distances.", "phrases": [["gravitate towards", "be naturally drawn to"], ["by contrast", "in comparison, on the other hand"], ["struggle to", "find it hard to do something"], ["incentives", "something that encourages people to act"], ["persist", "continue to exist"]], "grammar": [{"pattern": "Unless + present simple", "use": "Unless + present, will + base verb", "example": "Unless governments offer incentives such as housing or higher pay, the imbalance will probably persist", "try": "Unless people ______, the problem will ______."}, {"pattern": "Participle clause of result", "use": "main clause + , leaving + object + to-infinitive", "example": "leaving rural patients to travel long distances", "try": "The bus was cancelled, leaving us to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000033', 1033, 'Topic 33', 'Person who works in a successful company', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 33, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person who works in a successful company", "bullets": ["who this person is", "what this person does in this company", "what this business does", "why you think it’s successful"], "explain": "", "notes": ["Who", "What", "Business", "Why"], "rounding": {"q": "Would you like to work for that company yourself?", "model": {"answer": "Definitely, at some point. The pay is good, but what appeals to me more is the chance to learn from people who are genuinely passionate about what they do.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about my cousin Timur, who has worked for a Tashkent software company for about six years. He’d only just graduated when he landed the job, and he’s been climbing the ladder ever since. He’s a product manager, which basically means he acts as a bridge between the engineers and the clients. He listens to what customers need, turns that into a clear plan, and makes sure the team delivers on time, which is harder than it sounds. The company develops mobile banking apps and online payment tools. If you’ve ever paid a bill or sent money from your phone here, there’s a good chance you’ve used something they built from scratch, although you’d never see their name on the screen. In my view, three things explain its success. First, they stay ahead of the curve: instead of copying competitors, they test new ideas early. Second, they look after their people. Timur once told me that when the team had been working flat out on a launch, the founder ordered pizza himself and stayed until midnight. Staff turnover is low, which is unusual in this industry, and most new clients arrive through word of mouth. Finally, they take feedback seriously; if a customer reports a bug, it’s usually fixed within days. Hearing about it from the inside has opened my eyes. Success isn’t only about clever products; it’s about a culture in which people feel trusted. If I ever start up a business of my own, that’s the model I’ll follow.", "sections": [{"label": "Who", "text": "Let me tell you about my cousin Timur, who has worked for a Tashkent software company for about six years. He’d only just graduated when he landed the job, and he’s been climbing the ladder ever since."}, {"label": "What", "text": "He’s a product manager, which basically means he acts as a bridge between the engineers and the clients. He listens to what customers need, turns that into a clear plan, and makes sure the team delivers on time, which is harder than it sounds."}, {"label": "Business", "text": "The company develops mobile banking apps and online payment tools. If you’ve ever paid a bill or sent money from your phone here, there’s a good chance you’ve used something they built from scratch, although you’d never see their name on the screen."}, {"label": "Why", "text": "In my view, three things explain its success. First, they stay ahead of the curve: instead of copying competitors, they test new ideas early. Second, they look after their people. Timur once told me that when the team had been working flat out on a launch, the founder ordered pizza himself and stayed until midnight. Staff turnover is low, which is unusual in this industry, and most new clients arrive through word of mouth. Finally, they take feedback seriously; if a customer reports a bug, it’s usually fixed within days."}, {"label": "Reflection", "text": "Hearing about it from the inside has opened my eyes. Success isn’t only about clever products; it’s about a culture in which people feel trusted. If I ever start up a business of my own, that’s the model I’ll follow."}], "phrases": [["land a job", "manage to get a job"], ["climb the ladder", "move up to better positions in a career"], ["act as a bridge", "connect two groups and help them communicate"], ["deliver on time", "finish work by the agreed deadline"], ["build from scratch", "create something completely new, starting with nothing"], ["stay ahead of the curve", "be more advanced than competitors"], ["work flat out", "work as hard as possible"], ["staff turnover", "the rate at which employees leave and are replaced"], ["word of mouth", "recommendations passed on by people talking"], ["take feedback seriously", "treat people’s comments as important"], ["open someone’s eyes", "make someone realise something new"], ["start up", "set up a new business"]], "grammar": [{"pattern": "Present perfect (duration)", "use": "has / have + past participle + for + period", "example": "who has worked for a Tashkent software company for about six years", "try": "She has lived here for ______."}, {"pattern": "Past perfect", "use": "had + only just + past participle + when + past simple", "example": "He’d only just graduated when he landed the job", "try": "I’d only just ______ when ______."}, {"pattern": "Non-defining which", "use": "clause + , which + verb: a comment on the whole idea", "example": "which is harder than it sounds", "try": "______, which is more difficult than it looks."}, {"pattern": "Concession with although", "use": "although + clause", "example": "although you’d never see their name on the screen", "try": "Although it looks ______, ______."}, {"pattern": "Past perfect continuous", "use": "had been + -ing: an activity before a past event", "example": "when the team had been working flat out on a launch", "try": "When I arrived, they had been ______ for hours."}, {"pattern": "Preposition + which", "use": "a noun + in which + clause", "example": "a culture in which people feel trusted", "try": "a workplace in which ______."}]}}, "part3": {"intro": "We’ve been talking about a person who works in a successful company, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who works in a successful company", "title": "Person who works in a successful company", "questions": [{"q": "Is having happy employees important for the success of a company?", "model": {"answer": "Absolutely, because motivated people simply do better work. Employees who feel valued go the extra mile, stay for years and speak highly of the firm, which saves it a fortune in recruitment costs. Unhappy staff, by contrast, tend to do the bare minimum, and a bad atmosphere soon rubs off on customers. So it isn’t a luxury; it’s just plain business sense.", "phrases": [["do better work", "perform at a higher standard"], ["go the extra mile", "make more effort than is required"], ["speak highly of", "praise"], ["do the bare minimum", "do only what is strictly necessary"], ["rub off on", "influence someone else"], ["business sense", "good judgement about how to run a business"]], "grammar": [{"pattern": "Relative clause with who", "use": "noun + who + verb", "example": "Employees who feel valued go the extra mile", "try": "People who ______ tend to ______."}, {"pattern": "Which for a result", "use": "clause + , which + verb", "example": "which saves it a fortune in recruitment", "try": "______, which saves time."}]}}, {"q": "What are the advantages of working for a big company?", "model": {"answer": "The main one is security. A large firm can usually afford steady salaries, proper training and clear promotion routes, so you know where your career could lead. There’s also the chance to learn from specialists in every field, which a small start-up rarely offers. The trade-off is that you may feel like a small cog in a big machine, but for a graduate that’s often a sensible starting point.", "phrases": [["steady salary", "a regular, reliable income"], ["promotion route", "a clear path to better positions"], ["learn from", "gain knowledge by working with someone"], ["a small cog in a big machine", "an unimportant part of a huge organisation"], ["trade-off", "a loss that you accept in return for a benefit"]], "grammar": [{"pattern": "Modal could for possibility", "use": "where + subject + could + verb", "example": "so you know where your career could lead", "try": "so you can see where this job could ______."}, {"pattern": "Non-defining which", "use": "noun + , which + clause", "example": "which a small start-up rarely offers", "try": "______, which a small shop rarely offers."}]}}, {"q": "What are the benefits and drawbacks of working for an international company?", "model": {"answer": "On the plus side, you meet colleagues from different backgrounds, which broadens your horizons, and the experience looks good on a CV. You might even be sent abroad. On the downside, time-zone differences can mean late-night meetings, and decisions are sometimes taken at a head office that doesn’t understand local needs. Cultural misunderstandings also crop up, even when everyone speaks English.", "phrases": [["broaden your horizons", "give you new experiences and ideas"], ["look good on a CV", "impress future employers"], ["time-zone difference", "the gap in local time between countries"], ["understand local needs", "know what people in one area really require"], ["crop up", "appear unexpectedly"]], "grammar": [{"pattern": "Passive voice", "use": "are + sometimes + past participle", "example": "decisions are sometimes taken at a head office", "try": "Decisions are usually ______ by ______."}, {"pattern": "Even when", "use": "even when + clause: surprising contrast", "example": "even when everyone speaks English", "try": "Even when ______, ______."}]}}, {"q": "What makes some companies more successful than others?", "model": {"answer": "I’d put it down to adaptability. Plenty of firms have a good product, but the ones that survive keep reinventing themselves as the market changes. Strong leadership matters too, since a clear vision keeps everyone pulling in the same direction. Many businesses fell by the wayside simply because they ignored new technology, while the more flexible ones came out on top.", "phrases": [["put it down to", "say that something is caused by"], ["keep reinventing yourself", "continually change in order to stay relevant"], ["pull in the same direction", "work towards the same goal"], ["fall by the wayside", "fail and be forgotten"], ["come out on top", "end up as the winner"]], "grammar": [{"pattern": "the ones that", "use": "the ones that + verb: a defining group", "example": "the ones that survive keep reinventing themselves", "try": "The ones that ______ are usually ______."}, {"pattern": "Comparative with while", "use": "the more + adjective + ones", "example": "while the more flexible ones came out on top", "try": "while the more ______ ones ______."}]}}, {"q": "How important is customer service to the success of a business?", "model": {"answer": "It’s absolutely central. If a shop handles a complaint well, an annoyed customer can end up more loyal than before, whereas one rude reply can drive away a customer for good. These days people post reviews within a few minutes, so a single bad experience can spread like wildfire. A good product may attract customers, but service is what makes them come back.", "phrases": [["handle a complaint", "deal with a customer’s problem"], ["drive away", "make someone leave or stop coming"], ["post a review", "publish an opinion online"], ["spread like wildfire", "spread very fast"], ["come back", "return"]], "grammar": [{"pattern": "", "use": "Comparative: more + adjective + than before can end up + more + adjective + than before", "example": "an annoyed customer can end up more loyal than before", "try": "She ended up more ______ than before."}, {"pattern": "", "use": "Cleft: X is what service is what makes them come back", "example": "service is what makes them come back", "try": "Trust is what ______."}]}}, {"q": "Do you think companies have a responsibility to protect the environment?", "model": {"answer": "Yes, particularly big manufacturers, since they have by far the largest carbon footprint. They also have the resources to switch to cleaner energy and cut down on waste, which small businesses often lack. Many customers now choose brands that take sustainability seriously, so it’s increasingly in a company’s own interest. Even so, governments must set clear rules; otherwise good intentions may stay on paper.", "phrases": [["carbon footprint", "the amount of carbon dioxide produced by an activity"], ["switch to", "change to something different"], ["cut down on", "reduce"], ["take sustainability seriously", "treat protecting the environment as important"], ["stay on paper", "never be put into practice"]], "grammar": [{"pattern": "By far + superlative", "use": "by far the + superlative", "example": "they have by far the largest carbon footprint", "try": "It’s by far the ______."}, {"pattern": "Otherwise as a conditional", "use": "clause + ; otherwise + may + verb", "example": "otherwise good intentions may stay on paper", "try": "We must act now; otherwise ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

-- Check: 33 topics here, 3 pages each.
select count(*) as topics,
       (select count(*) from public.materials where collection like 'Speaking Topics%' and storage_path like any (array(select 'speaking:' || id || '#%' from public.speaking_sets where (content->>'topic_no')::int between 1 and 33))) as pages
  from public.speaking_sets where (content->>'topic_no')::int between 1 and 33;
